34	pub(crate) fn emit_function(module: &Module, index: usize) -> Result<String, String> {
35	    let f = module.functions.get(index).ok_or("invalid function index")?;
36	    if f.import.is_some() { return Err("attempted to emit an import as wasm code".into()); }
37	    let ty = module.types.get(f.type_idx as usize).ok_or("invalid function type")?.clone();
38	    let mut locals = ty.params.clone();
39	    locals.extend_from_slice(&f.locals);
40	    let stack_cap = f.max_stack.max(1).saturating_add(8);
41	    let args = ty.params.iter().enumerate().map(|(i, t)| format!("{} %p{i}", t.llvm())).collect::<Vec<_>>().join(", ");
42	    let mut emitter = FunctionEmitter {
43	        module, index, ty: ty.clone(), locals, out: String::new(), stack: Vec::new(), stack_cap,
44	        controls: Vec::new(), temp_id: 0, label_id: 0, current: false, ret_label: "fn_return".into(),
45	    };
46	    let ret = crate::codegen::return_type(&ty.results);
47	    let _ = writeln!(emitter.out, "define internal {ret} @{}({args}) {{", crate::codegen::fn_name(index));
48	    emitter.start_label("entry");
49	    emitter.line("call void @w2l_depth_enter()");
50	    emitter.line(&format!("%stack = alloca [{} x <16 x i8>], align 16", stack_cap));
51	    for (local, local_ty) in emitter.locals.iter().enumerate() {
52	        emitter.line(&format!("%local{local} = alloca {}, align {}", local_ty.llvm(), local_ty.natural_align()));
53	        if local >= ty.params.len() {
54	            emitter.line(&format!("store {} zeroinitializer, ptr %local{local}, align {}", local_ty.llvm(), local_ty.natural_align()));
55	        } else {
56	            emitter.line(&format!("store {} %p{local}, ptr %local{local}, align {}", local_ty.llvm(), local_ty.natural_align()));
57	        }
58	    }
59	    emitter.ret_label = emitter.fresh_label("fn_return");
60	    emitter.controls.push(ControlTarget {
61	        kind: TargetKind::Function, height: 0, params: Vec::new(), results: ty.results.clone(),
62	        exit: emitter.ret_label.clone(), loop_header: None, has_break: false,
63	    });
64	    emitter.compile_seq(&f.body)?;
65	    if emitter.current {
66	        emitter.branch_to_target(0)?;
67	    }
68	    if emitter.controls[0].has_break {
69	        let label = emitter.ret_label.clone();
70	        emitter.start_label(&label);
71	        emitter.emit_return_from_stack(&ty.results)?;
72	    }
73	    emitter.out.push_str("}\n");
74	    Ok(emitter.out)
75	}
