77	impl FunctionEmitter<'_> {
78	    pub(crate) fn line(&mut self, text: &str) {
79	        debug_assert!(self.current, "instruction emitted after terminator");
80	        let _ = writeln!(self.out, "  {text}");
81	    }
82	
83	    pub(crate) fn fresh(&mut self) -> String {
84	        let id = self.temp_id;
85	        self.temp_id += 1;
86	        format!("%t{id}")
87	    }
88	
89	    pub(crate) fn fresh_label(&mut self, prefix: &str) -> String {
90	        let id = self.label_id;
91	        self.label_id += 1;
92	        format!("{prefix}_{id}")
93	    }
94	
95	    pub(crate) fn start_label(&mut self, label: &str) {
96	        debug_assert!(!self.current, "label inserted before previous block was terminated");
97	        let _ = writeln!(self.out, "{label}:");
98	        self.current = true;
99	    }
