101	    pub(crate) fn branch(&mut self, label: &str) {
102	        self.line(&format!("br label %{label}"));
103	        self.current = false;
104	    }
105	
106	    fn cond_branch(&mut self, cond: &str, yes: &str, no: &str) {
107	        self.line(&format!("br i1 {cond}, label %{yes}, label %{no}"));
108	        self.current = false;
109	    }
