111	    pub(crate) fn emit_trap_if(&mut self, cond: &str, code: u32) {
112	        let trap = self.fresh_label("trap");
113	        let ok = self.fresh_label("checked");
114	        self.cond_branch(cond, &trap, &ok);
115	        self.start_label(&trap);
116	        self.line(&format!("call void @w2l_trap(i32 {code})"));
117	        self.line("unreachable");
118	        self.current = false;
119	        self.start_label(&ok);
120	    }
121	
122	    fn terminate_unreachable(&mut self) {
123	        self.line("unreachable");
124	        self.current = false;
125	    }
126	
127	    pub(crate) fn slot_ptr(&mut self, index: usize) -> String {
128	        let ptr = self.fresh();
129	        self.line(&format!("{ptr} = getelementptr [{} x <16 x i8>], ptr %stack, i32 0, i32 {index}", self.stack_cap));
130	        ptr
131	    }
132	
133	    pub(crate) fn load_slot(&mut self, index: usize, ty: ValType) -> String {
134	        let ptr = self.slot_ptr(index);
135	        let value = self.fresh();
136	        self.line(&format!("{value} = load {}, ptr {ptr}, align 1", ty.llvm()));
137	        value
138	    }
