140	    pub(crate) fn store_slot(&mut self, index: usize, ty: ValType, value: &str) {
141	        let ptr = self.slot_ptr(index);
142	        self.line(&format!("store {} {value}, ptr {ptr}, align 1", ty.llvm()));
143	    }
