145	    pub(crate) fn pop(&mut self, expected: ValType) -> Result<String, String> {
146	        let index = self.stack.len().checked_sub(1).ok_or_else(|| self.error("code generation stack underflow"))?;
147	        let actual = self.stack.pop().unwrap();
148	        if actual != expected { return Err(self.error(format!("code generation type mismatch: got {actual}, expected {expected}"))); }
149	        Ok(self.load_slot(index, expected))
150	    }
