152	    pub(crate) fn pop_any(&mut self) -> Result<(ValType, String), String> {
153	        let index = self.stack.len().checked_sub(1).ok_or_else(|| self.error("code generation stack underflow"))?;
154	        let ty = self.stack.pop().unwrap();
155	        let value = self.load_slot(index, ty);
