166	    pub(crate) fn push(&mut self, ty: ValType, value: &str) -> Result<(), String> {
167	        if self.stack.len() >= self.stack_cap { return Err(self.error("validated operand stack exceeds allocation")); }
168	        self.store_slot(self.stack.len(), ty, value);
