216	            Instr::Br(depth) => self.branch_to_target(*depth as usize)?,
217	            Instr::BrIf(depth) => self.branch_if(*depth as usize)?,
218	            Instr::BrTable(targets, default) => self.branch_table(targets, *default)?,
219	            Instr::Return => {
220	                let results = self.ty.results.clone();
221	                let values = self.pop_values(&results)?;
222	                self.line("call void @w2l_depth_leave()");
223	                self.emit_return_values(&results, &values);
224	                self.current = false;
225	            }
226	            Instr::Call(index) => {
227	                let ty = self.module.types[self.module.functions[*index as usize].type_idx as usize].clone();
228	                let args = self.pop_values(&ty.params)?;
229	                let results = self.call_function(*index as usize, &ty, &args)?;
230	                for (result_ty, value) in ty.results.iter().zip(results) { self.push(*result_ty, &value)?; }
231	            }
232	            Instr::CallIndirect { ty, .. } => self.call_indirect(*ty as usize)?,
233	            Instr::Drop => { let _ = self.pop_any()?; }
234	            Instr::Select(_) => {
235	                let condition = self.pop(ValType::I32)?;
236	                let (ty_b, b) = self.pop_any()?;
237	                let (ty_a, a) = self.pop_any()?;
238	                if ty_a != ty_b { return Err(self.error("select operands have different types")); }
239	                let result = self.fresh();
