244	                let ty = *self.locals.get(*index as usize).ok_or_else(|| self.error("local index out of range"))?;
245	                let value = self.fresh();
246	                self.line(&format!("{value} = load {}, ptr %local{index}, align {}", ty.llvm(), ty.natural_align()));
