267	                let global = self.module.globals.get(*index as usize).ok_or_else(|| self.error("global index out of range"))?;
268	                let ty = global.ty;
269	                let value = self.pop(ty)?;
270	                self.line(&format!("store {} {value}, ptr @w2l_g{index}", ty.llvm()));
271	            }
272	            Instr::Load { op, align, offset } => crate::numeric::emit_load(self, *op, *align, *offset)?,
273	            Instr::Store { op, align, offset } => crate::numeric::emit_store(self, *op, *align, *offset)?,
274	            Instr::MemorySize(_) | Instr::MemoryGrow(_) => crate::numeric::emit_memory_size_grow(self, instr)?,
275	            Instr::Const(value) => self.emit_const(value)?,
276	            Instr::Numeric(op) => crate::numeric::emit_numeric(self, *op)?,
277	            Instr::SignExtend(op) => crate::numeric::emit_sign_extend(self, *op)?,
278	            Instr::Saturating(op) => crate::numeric::emit_saturating(self, *op)?,
279	            Instr::Bulk(op) => crate::numeric::emit_bulk(self, op)?,
280	            Instr::Simd { op, immediate } => crate::simd_codegen::emit_simd(self, *op, immediate)?,
281	        }
282	        Ok(())
283	    }
284	
285	    fn truthy(&mut self, value: &str) -> String {
286	        let result = self.fresh();
287	        self.line(&format!("{result} = icmp ne i32 {value}, 0"));
288	        result
289	    }
290	
291	    fn compile_block(&mut self, sig: &BlockSig, body: &[Instr]) -> Result<(), String> {
292	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("block parameters missing"))?;
293	        let exit = self.fresh_label("block_exit");
294	        self.controls.push(ControlTarget {
295	            kind: TargetKind::Block, height, params: sig.params.clone(), results: sig.results.clone(),
296	            exit: exit.clone(), loop_header: None, has_break: false,
297	        });
298	        self.compile_seq(body)?;
299	        let normal = self.current;
300	        if normal {
301	            self.copy_to_slot_base(height, &sig.results)?;
302	            self.branch(&exit);
303	        }
304	        let target = self.controls.pop().unwrap();
305	        self.stack.truncate(height);
306	        self.stack.extend_from_slice(&sig.results);
307	        if normal || target.has_break {
308	            self.start_label(&exit);
309	        }
310	        self.current = normal || target.has_break;
311	        Ok(())
312	    }
313	
314	    fn compile_loop(&mut self, sig: &BlockSig, body: &[Instr]) -> Result<(), String> {
315	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("loop parameters missing"))?;
316	        let header = self.fresh_label("loop_head");
317	        let exit = self.fresh_label("loop_exit");
318	        self.branch(&header);
319	        self.start_label(&header);
320	        self.controls.push(ControlTarget {
321	            kind: TargetKind::Loop, height, params: sig.params.clone(), results: sig.results.clone(),
322	            exit: exit.clone(), loop_header: Some(header), has_break: false,
323	        });
324	        self.compile_seq(body)?;
325	        let normal = self.current;
326	        if normal {
327	            self.copy_to_slot_base(height, &sig.results)?;
328	            self.branch(&exit);
329	        }
330	        let target = self.controls.pop().unwrap();
331	        self.stack.truncate(height);
332	        self.stack.extend_from_slice(&sig.results);
333	        if normal || target.has_break { self.start_label(&exit); }
334	        self.current = normal || target.has_break;
335	        Ok(())
336	    }
337	
338	    fn compile_if(&mut self, sig: &BlockSig, then_body: &[Instr], else_body: Option<&[Instr]>) -> Result<(), String> {
339	        let condition = self.pop(ValType::I32)?;
340	        let cond = self.truthy(&condition);
341	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("if parameters missing"))?;
342	        let starting_stack = self.stack.clone();
343	        let then_label = self.fresh_label("if_then");
344	        let else_label = self.fresh_label("if_else");
345	        let exit = self.fresh_label("if_exit");
346	        self.cond_branch(&cond, &then_label, &else_label);
347	        self.controls.push(ControlTarget {
348	            kind: TargetKind::If, height, params: sig.params.clone(), results: sig.results.clone(),
349	            exit: exit.clone(), loop_header: None, has_break: false,
350	        });
351	
352	        self.start_label(&then_label);
353	        self.compile_seq(then_body)?;
354	        let mut normal = self.current;
355	        if normal {
356	            self.copy_to_slot_base(height, &sig.results)?;
357	            self.branch(&exit);
358	        }
359	
360	        self.stack = starting_stack.clone();
361	        self.start_label(&else_label);
362	        if let Some(body) = else_body {
363	            self.compile_seq(body)?;
364	        }
365	        if self.current {
366	            self.copy_to_slot_base(height, &sig.results)?;
367	            self.branch(&exit);
368	            normal = true;
369	        }
370	        let target = self.controls.pop().unwrap();
371	        self.stack.truncate(height);
372	        self.stack.extend_from_slice(&sig.results);
373	        if normal || target.has_break { self.start_label(&exit); }
374	        self.current = normal || target.has_break;
375	        Ok(())
376	    }
377	
378	    fn target_info(&mut self, depth: usize) -> Result<(String, usize, Vec<ValType>, bool), String> {
379	        let index = self.controls.len().checked_sub(depth + 1).ok_or_else(|| self.error("branch depth out of bounds"))?;
380	        let target = &mut self.controls[index];
381	        let loop_target = target.kind == TargetKind::Loop;
382	        let label = if loop_target { target.loop_header.as_ref().unwrap().clone() } else { target.exit.clone() };
383	        let types = if loop_target { target.params.clone() } else { target.results.clone() };
384	        if !loop_target { target.has_break = true; }
385	        Ok((label, target.height, types, loop_target))
386	    }
387	
388	    fn copy_to_slot_base(&mut self, height: usize, types: &[ValType]) -> Result<(), String> {
389	        if self.stack.len() < types.len() { return Err(self.error("branch result values are missing")); }
390	        let source = self.stack.len() - types.len();
391	        for (i, &ty) in types.iter().enumerate() {
392	            let value = self.load_slot(source + i, ty);
393	            self.store_slot(height + i, ty, &value);
394	        }
395	        Ok(())
396	    }
397	
398	    fn branch_to_target(&mut self, depth: usize) -> Result<(), String> {
399	        let (label, height, types, _) = self.target_info(depth)?;
400	        self.copy_to_slot_base(height, &types)?;
401	        self.branch(&label);
402	        Ok(())
403	    }
404	
405	    fn branch_if(&mut self, depth: usize) -> Result<(), String> {
406	        let condition = self.pop(ValType::I32)?;
407	        let cond = self.truthy(&condition);
408	        let (target, height, types, _) = self.target_info(depth)?;
409	        let take = self.fresh_label("br_if_take");
410	        let fallthrough = self.fresh_label("br_if_next");
411	        self.cond_branch(&cond, &take, &fallthrough);
412	        self.start_label(&take);
413	        self.copy_to_slot_base(height, &types)?;
414	        self.branch(&target);
415	        self.start_label(&fallthrough);
416	        Ok(())
417	    }
418	
419	    fn branch_table(&mut self, targets: &[u32], default: u32) -> Result<(), String> {
420	        let selector = self.pop(ValType::I32)?;
421	        let mut branches = Vec::with_capacity(targets.len() + 1);
422	        for &depth in targets.iter().chain(std::iter::once(&default)) {
423	            let (target, height, types, _) = self.target_info(depth as usize)?;
424	            branches.push((target, height, types, self.fresh_label("br_table_case")));
425	        }
426	        let default_label = branches.last().unwrap().3.clone();
427	        let cases = branches.iter().enumerate().take(targets.len()).map(|(i, b)| format!("i32 {i}, label %{}", b.3)).collect::<Vec<_>>().join(" ");
428	        self.line(&format!("switch i32 {selector}, label %{default_label} [ {cases} ]"));
429	        self.current = false;
430	        for (target, height, types, case_label) in branches {
431	            self.start_label(&case_label);
432	            self.copy_to_slot_base(height, &types)?;
433	            self.branch(&target);
434	        }
435	        Ok(())
436	    }
437	
438	    fn call_indirect(&mut self, type_index: usize) -> Result<(), String> {
439	        let ty = self.module.types.get(type_index).ok_or_else(|| self.error("call_indirect type index out of range"))?.clone();
440	        let index = self.pop(ValType::I32)?;
441	        let args = self.pop_values(&ty.params)?;
442	        let base = self.stack.len();
443	        let size = self.fresh();
444	        self.line(&format!("{size} = load i32, ptr @w2l_table_size"));
445	        let oob = self.fresh();
446	        self.line(&format!("{oob} = icmp uge i32 {index}, {size}"));
447	        self.emit_trap_if(&oob, 5);
448	        let table = self.fresh();
449	        self.line(&format!("{table} = load ptr, ptr @w2l_table_base"));
450	        let index64 = self.fresh();
451	        self.line(&format!("{index64} = zext i32 {index} to i64"));
452	        let slot = self.fresh();
453	        self.line(&format!("{slot} = getelementptr i32, ptr {table}, i64 {index64}"));
454	        let function_index = self.fresh();
455	        self.line(&format!("{function_index} = load i32, ptr {slot}, align 4"));
456	        let is_null = self.fresh();
457	        self.line(&format!("{is_null} = icmp eq i32 {function_index}, -1"));
458	        self.emit_trap_if(&is_null, 6);
459	
460	        let mut cases = Vec::new();
461	        for (function_index, function) in self.module.functions.iter().enumerate() {
462	            let actual = &self.module.types[function.type_idx as usize];
463	            if actual == &ty { cases.push((function_index, self.fresh_label("indirect_case"))); }
464	        }
465	        let mismatch = self.fresh_label("indirect_mismatch");
466	        let merge = self.fresh_label("indirect_merge");
467	        let case_text = cases.iter().map(|(index, label)| format!("i32 {}, label %{label}", crate::codegen::i32_bits(*index as u32))).collect::<Vec<_>>().join(" ");
468	        self.line(&format!("switch i32 {function_index}, label %{mismatch} [ {case_text} ]"));
469	        self.current = false;
470	        for (function_index, label) in &cases {
471	            self.start_label(label);
472	            let values = self.call_function(*function_index, &ty, &args)?;
473	            for (slot, (result_ty, value)) in ty.results.iter().zip(values).enumerate() {
474	                self.store_slot(base + slot, *result_ty, &value);
475	            }
476	            self.branch(&merge);
477	        }
478	        self.start_label(&mismatch);
479	        self.line("call void @w2l_trap(i32 7)");
480	        self.terminate_unreachable();
481	        if cases.is_empty() {
482	            self.current = false;
483	            return Ok(());
484	        }
485	        self.start_label(&merge);
486	        for (slot, result_ty) in ty.results.iter().enumerate() {
487	            let value = self.load_slot(base + slot, *result_ty);
488	            self.push(*result_ty, &value)?;
489	        }
490	        Ok(())
491	    }
492	
493	    pub(crate) fn call_function(&mut self, index: usize, ty: &FuncType, args: &[String]) -> Result<Vec<String>, String> {
494	        if args.len() != ty.params.len() { return Err(self.error("internal call argument count mismatch")); }
495	        let ret = crate::codegen::return_type(&ty.results);
496	        let target = crate::codegen::fn_name(index);
497	        if ty.results.is_empty() {
498	            self.line(&format!("call void @{target}({})", crate::codegen::typed_args(&ty.params, args)));
499	            return Ok(Vec::new());
500	        }
501	        let call = self.fresh();
502	        self.line(&format!("{call} = call {ret} @{target}({})", crate::codegen::typed_args(&ty.params, args)));
503	        if ty.results.len() == 1 { return Ok(vec![call]); }
504	        let mut values = Vec::with_capacity(ty.results.len());
505	        for (i, ty) in ty.results.iter().enumerate() {
506	            let value = self.fresh();
507	            self.line(&format!("{value} = extractvalue {ret} {call}, {i}"));
508	            let _ = ty;
509	            values.push(value);
510	        }
511	        Ok(values)
512	    }
513	
514	    fn emit_return_from_stack(&mut self, results: &[ValType]) -> Result<(), String> {
515	        let values = results.iter().enumerate().map(|(i, ty)| self.load_slot(i, *ty)).collect::<Vec<_>>();
516	        self.line("call void @w2l_depth_leave()");
517	        self.emit_return_values(results, &values);
518	        self.current = false;
519	        Ok(())
520	    }
521	
522	    fn emit_return_values(&mut self, results: &[ValType], values: &[String]) {
523	        match results.len() {
524	            0 => self.line("ret void"),
525	            1 => self.line(&format!("ret {} {}", results[0].llvm(), values[0])),
526	            n => {
527	                let ty = crate::codegen::return_type(results);
528	                let mut current = "zeroinitializer".to_string();
529	                for (i, (result, value)) in results.iter().zip(values).enumerate() {
530	                    let agg = self.fresh();
531	                    self.line(&format!("{agg} = insertvalue {ty} {current}, {} {value}, {i}", result.llvm()));
532	                    current = agg;
533	                }
534	                let _ = n;
535	                self.line(&format!("ret {ty} {current}"));
536	            }
537	        }
538	    }
539	}
