6	pub fn emit_numeric(f: &mut FunctionEmitter<'_>, op: u8) -> Result<(), String> {
7	    match op {
8	        0x45 => {
9	            let a = f.pop(I32)?;
10	            let c = f.fresh();
11	            f.line(&format!("{c} = icmp eq i32 {a}, 0"));
12	            let r = f.fresh();
13	            f.line(&format!("{r} = zext i1 {c} to i32"));
14	            f.push(I32, &r)?;
15	        }
16	        0x46..=0x4f => emit_int_compare(f, op, I32, op - 0x46)?,
17	        0x50 => {
18	            let a = f.pop(I64)?;
19	            let c = f.fresh();
20	            f.line(&format!("{c} = icmp eq i64 {a}, 0"));
21	            let r = f.fresh();
22	            f.line(&format!("{r} = zext i1 {c} to i32"));
23	            f.push(I32, &r)?;
24	        }
25	        0x51..=0x5a => emit_int_compare(f, op, I64, op - 0x51)?,
26	        0x5b..=0x60 => emit_float_compare(f, op, F32, op - 0x5b)?,
27	        0x61..=0x66 => emit_float_compare(f, op, F64, op - 0x61)?,
28	        0x67..=0x69 => emit_integer_unary(f, op, I32)?,
29	        0x6a..=0x78 => emit_integer_binary(f, op, I32)?,
30	        0x79..=0x7b => emit_integer_unary(f, op, I64)?,
31	        0x7c..=0x8a => emit_integer_binary(f, op, I64)?,
32	        0x8b..=0x91 => emit_float_unary(f, op, F32)?,
33	        0x92..=0x98 => emit_float_binary(f, op, F32)?,
34	        0x99..=0x9f => emit_float_unary(f, op, F64)?,
35	        0xa0..=0xa6 => emit_float_binary(f, op, F64)?,
36	        0xa7..=0xbf => emit_conversion(f, op)?,
37	        _ => return Err(format!("unsupported numeric opcode 0x{op:02x}")),
38	    }
39	    Ok(())
40	}
