42	pub fn emit_sign_extend(f: &mut FunctionEmitter<'_>, op: u8) -> Result<(), String> {
43	    let (ty, narrow) = match op {
44	        0xc0 => (I32, "i8"), 0xc1 => (I32, "i16"), 0xc2 => (I64, "i8"),
45	        0xc3 => (I64, "i16"), 0xc4 => (I64, "i32"),
46	        _ => return Err("invalid sign-extension opcode".into()),
47	    };
48	    let value = f.pop(ty)?;
49	    let small = f.fresh();
50	    f.line(&format!("{small} = trunc {} {value} to {narrow}", ty.llvm()));
51	    let result = f.fresh();
52	    f.line(&format!("{result} = sext {narrow} {small} to {}", ty.llvm()));
53	    f.push(ty, &result)
54	}
