56	pub fn emit_saturating(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
57	    let (input, output, signed) = match op {
58	        0 => (F32, I32, true), 1 => (F32, I32, false),
59	        2 => (F64, I32, true), 3 => (F64, I32, false),
60	        4 => (F32, I64, true), 5 => (F32, I64, false),
61	        6 => (F64, I64, true), 7 => (F64, I64, false),
62	        _ => return Err("invalid saturating conversion opcode".into()),
63	    };
64	    let value = f.pop(input)?;
65	    let name = format!("@llvm.{}{}.sat.{}.{}",
66	        if signed { "fptosi" } else { "fptoui" },
67	        "", output.llvm(), if input == F32 { "f32" } else { "f64" });
68	    let result = f.fresh();
69	    f.line(&format!("{result} = call {} {name}({} {value})", output.llvm(), input.llvm()));
70	    f.push(output, &result)
71	}
