73	fn emit_int_compare(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType, pred: u8) -> Result<(), String> {
74	    let b = f.pop(ty)?;
75	    let a = f.pop(ty)?;
76	    let cond = match pred {
77	        0 => "eq", 1 => "ne", 2 => "slt", 3 => "ult", 4 => "sgt",
78	        5 => "ugt", 6 => "sle", 7 => "ule", 8 => "sge", _ => "uge",
79	    };
80	    let c = f.fresh();
81	    f.line(&format!("{c} = icmp {cond} {} {a}, {b}", ty.llvm()));
82	    let r = f.fresh();
83	    f.line(&format!("{r} = zext i1 {c} to i32"));
84	    let _ = op;
85	    f.push(I32, &r)
86	}
