88	fn emit_float_compare(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType, pred: u8) -> Result<(), String> {
89	    let b = f.pop(ty)?;
90	    let a = f.pop(ty)?;
91	    let cond = match pred { 0 => "oeq", 1 => "une", 2 => "olt", 3 => "ogt", 4 => "ole", _ => "oge" };
92	    let c = f.fresh();
93	    f.line(&format!("{c} = fcmp {cond} {} {a}, {b}", ty.llvm()));
94	    let r = f.fresh();
95	    f.line(&format!("{r} = zext i1 {c} to i32"));
96	    let _ = op;
97	    f.push(I32, &r)
98	}
