100	fn emit_integer_unary(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType) -> Result<(), String> {
101	    let a = f.pop(ty)?;
102	    let result = f.fresh();
103	    let intrinsic = match op {
104	        0x67 | 0x79 => "ctlz",
105	        0x68 | 0x7a => "cttz",
106	        0x69 | 0x7b => "ctpop",
107	        _ => return Err("invalid integer unary opcode".into()),
108	    };
109	    f.line(&format!("{result} = call {} @llvm.{intrinsic}.{}({} {a}{})", ty.llvm(), ty.llvm(), ty.llvm(), if intrinsic == "ctpop" { "" } else { ", i1 false" }));
110	    f.push(ty, &result)
111	}
