113	fn emit_integer_binary(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType) -> Result<(), String> {
114	    let b = f.pop(ty)?;
115	    let a = f.pop(ty)?;
116	    let bits = if ty == I32 { 32 } else { 64 };
117	    let word = ty.llvm();
118	    let result = match op {
119	        0x6a | 0x7c => binary(f, "add", ty, &a, &b),
120	        0x6b | 0x7d => binary(f, "sub", ty, &a, &b),
121	        0x6c | 0x7e => binary(f, "mul", ty, &a, &b),
122	        0x6d | 0x7f => {
123	            let zero = f.fresh();
124	            f.line(&format!("{zero} = icmp eq {word} {b}, 0"));
125	            f.emit_trap_if(&zero, 1);
126	            let min = if bits == 32 { i32::MIN.to_string() } else { i64::MIN.to_string() };
127	            let min_cmp = f.fresh();
128	            f.line(&format!("{min_cmp} = icmp eq {word} {a}, {min}"));
129	            let neg_one = f.fresh();
130	            f.line(&format!("{neg_one} = icmp eq {word} {b}, -1"));
131	            let overflow = f.fresh();
132	            f.line(&format!("{overflow} = and i1 {min_cmp}, {neg_one}"));
133	            f.emit_trap_if(&overflow, 2);
134	            binary(f, "sdiv", ty, &a, &b)
135	        }
136	        0x6e | 0x80 => {
137	            let zero = f.fresh();
138	            f.line(&format!("{zero} = icmp eq {word} {b}, 0"));
139	            f.emit_trap_if(&zero, 1);
140	            binary(f, "udiv", ty, &a, &b)
141	        }
142	        0x6f | 0x81 => emit_signed_remainder(f, ty, &a, &b)?,
143	        0x70 | 0x82 => {
144	            let zero = f.fresh();
145	            f.line(&format!("{zero} = icmp eq {word} {b}, 0"));
146	            f.emit_trap_if(&zero, 1);
147	            binary(f, "urem", ty, &a, &b)
148	        }
149	        0x71 | 0x83 => binary(f, "and", ty, &a, &b),
150	        0x72 | 0x84 => binary(f, "or", ty, &a, &b),
151	        0x73 | 0x85 => binary(f, "xor", ty, &a, &b),
152	        0x74 | 0x86 => emit_shift(f, ty, &a, &b, "shl", bits - 1),
153	        0x75 | 0x87 => emit_shift(f, ty, &a, &b, "ashr", bits - 1),
154	        0x76 | 0x88 => emit_shift(f, ty, &a, &b, "lshr", bits - 1),
155	        0x77 | 0x89 => emit_rotate(f, ty, &a, &b, bits, true),
156	        0x78 | 0x8a => emit_rotate(f, ty, &a, &b, bits, false),
157	        _ => return Err("invalid integer binary opcode".into()),
158	    };
159	    f.push(ty, &result)
160	}
