162	fn binary(f: &mut FunctionEmitter<'_>, op: &str, ty: ValType, a: &str, b: &str) -> String {
163	    let result = f.fresh();
164	    f.line(&format!("{result} = {op} {} {a}, {b}", ty.llvm()));
