168	fn emit_signed_remainder(f: &mut FunctionEmitter<'_>, ty: ValType, a: &str, b: &str) -> Result<String, String> {
169	    let word = ty.llvm();
170	    let zero = f.fresh();
171	    f.line(&format!("{zero} = icmp eq {word} {b}, 0"));
172	    f.emit_trap_if(&zero, 1);
173	    let negative_a = f.fresh();
174	    f.line(&format!("{negative_a} = icmp slt {word} {a}, 0"));
175	    let neg_a = f.fresh();
176	    f.line(&format!("{neg_a} = sub {word} 0, {a}"));
177	    let abs_a = f.fresh();
178	    f.line(&format!("{abs_a} = select i1 {negative_a}, {word} {neg_a}, {word} {a}"));
179	    let negative_b = f.fresh();
180	    f.line(&format!("{negative_b} = icmp slt {word} {b}, 0"));
181	    let neg_b = f.fresh();
182	    f.line(&format!("{neg_b} = sub {word} 0, {b}"));
183	    let abs_b = f.fresh();
184	    f.line(&format!("{abs_b} = select i1 {negative_b}, {word} {neg_b}, {word} {b}"));
185	    let rem = f.fresh();
186	    f.line(&format!("{rem} = urem {word} {abs_a}, {abs_b}"));
187	    let neg_rem = f.fresh();
188	    f.line(&format!("{neg_rem} = sub {word} 0, {rem}"));
189	    let result = f.fresh();
190	    f.line(&format!("{result} = select i1 {negative_a}, {word} {neg_rem}, {word} {rem}"));
191	    Ok(result)
192	}
