194	fn emit_shift(f: &mut FunctionEmitter<'_>, ty: ValType, a: &str, b: &str, op: &str, mask: u32) -> String {
195	    let count = f.fresh();
196	    f.line(&format!("{count} = and {} {b}, {mask}", ty.llvm()));
197	    let result = f.fresh();
198	    f.line(&format!("{result} = {op} {} {a}, {count}", ty.llvm()));
199	    result
200	}
