202	fn emit_rotate(f: &mut FunctionEmitter<'_>, ty: ValType, a: &str, b: &str, bits: u32, left: bool) -> String {
203	    let mask = bits - 1;
204	    let count = f.fresh();
205	    f.line(&format!("{count} = and {} {b}, {mask}", ty.llvm()));
206	    let neg = f.fresh();
207	    f.line(&format!("{neg} = sub {} 0, {count}", ty.llvm()));
208	    let rev = f.fresh();
209	    f.line(&format!("{rev} = and {} {neg}, {mask}", ty.llvm()));
210	    let (op1, op2) = if left { ("shl", "lshr") } else { ("lshr", "shl") };
211	    let x = f.fresh();
212	    f.line(&format!("{x} = {op1} {} {a}, {count}", ty.llvm()));
213	    let y = f.fresh();
214	    f.line(&format!("{y} = {op2} {} {a}, {rev}", ty.llvm()));
215	    let result = f.fresh();
216	    f.line(&format!("{result} = or {} {x}, {y}", ty.llvm()));
217	    result
218	}
