220	fn emit_float_unary(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType) -> Result<(), String> {
221	    let value = f.pop(ty)?;
222	    let bits = if ty == F32 { 32 } else { 64 };
223	    let intty = if bits == 32 { "i32" } else { "i64" };
224	    let sign = if bits == 32 { i32::MIN as i64 } else { i64::MIN };
225	    let result = match op {
226	        0x8b | 0x99 => {
227	            let int_value = f.fresh();
228	            f.line(&format!("{int_value} = bitcast {} {value} to {intty}", ty.llvm()));
229	            let abs = f.fresh();
230	            let mask = if bits == 32 { "2147483647" } else { "9223372036854775807" };
231	            f.line(&format!("{abs} = and {intty} {int_value}, {mask}"));
232	            let r = f.fresh();
233	            f.line(&format!("{r} = bitcast {intty} {abs} to {}", ty.llvm()));
234	            r
235	        }
236	        0x8c | 0x9a => {
237	            let int_value = f.fresh();
238	            f.line(&format!("{int_value} = bitcast {} {value} to {intty}", ty.llvm()));
239	            let neg = f.fresh();
240	            f.line(&format!("{neg} = xor {intty} {int_value}, {sign}"));
241	            let r = f.fresh();
242	            f.line(&format!("{r} = bitcast {intty} {neg} to {}", ty.llvm()));
243	            r
244	        }
245	        _ => {
246	            let intrinsic = match op {
247	                0x8d | 0x9b => "ceil", 0x8e | 0x9c => "floor",
248	                0x8f | 0x9d => "trunc", 0x90 | 0x9e => "roundeven",
249	                0x91 | 0x9f => "sqrt", _ => return Err("invalid float unary opcode".into()),
250	            };
251	            let result = f.fresh();
252	            f.line(&format!("{result} = call {} @llvm.{intrinsic}.{}({} {value})", ty.llvm(), if ty == F32 { "f32" } else { "f64" }, ty.llvm()));
253	            result
254	        }
255	    };
256	    f.push(ty, &result)
257	}
