259	fn emit_float_binary(f: &mut FunctionEmitter<'_>, op: u8, ty: ValType) -> Result<(), String> {
260	    let b = f.pop(ty)?;
261	    let a = f.pop(ty)?;
262	    let result = match op {
263	        0x92 | 0xa0 => binary(f, "fadd", ty, &a, &b),
264	        0x93 | 0xa1 => binary(f, "fsub", ty, &a, &b),
265	        0x94 | 0xa2 => binary(f, "fmul", ty, &a, &b),
266	        0x95 | 0xa3 => binary(f, "fdiv", ty, &a, &b),
267	        0x96 | 0xa4 => emit_float_minmax(f, ty, &a, &b, false),
268	        0x97 | 0xa5 => emit_float_minmax(f, ty, &a, &b, true),
269	        0x98 | 0xa6 => emit_copysign(f, ty, &a, &b),
270	        _ => return Err("invalid float binary opcode".into()),
271	    };
272	    f.push(ty, &result)
273	}
