275	fn emit_float_minmax(f: &mut FunctionEmitter<'_>, ty: ValType, a: &str, b: &str, maximum: bool) -> String {
276	    let (intty, suffix, sign, mag, canonical_nan) = if ty == F32 {
277	        ("i32", "float", i32::MIN, i32::MAX, 0x7fc0_0000u32 as i32)
278	    } else {
279	        ("i64", "double", i64::MIN, i64::MAX, 0x7ff8_0000_0000_0000u64 as i64)
280	    };
281	    let nan_a = f.fresh();
282	    let nan_b = f.fresh();
283	    f.line(&format!("{nan_a} = fcmp uno {suffix} {a}, {a}"));
284	    f.line(&format!("{nan_b} = fcmp uno {suffix} {b}, {b}"));
285	    let any_nan = f.fresh();
286	    f.line(&format!("{any_nan} = or i1 {nan_a}, {nan_b}"));
287	    let cmp = f.fresh();
288	    f.line(&format!("{cmp} = fcmp {} {suffix} {a}, {b}", if maximum { "ogt" } else { "olt" }));
289	    let ordered = f.fresh();
290	    f.line(&format!("{ordered} = select i1 {cmp}, {suffix} {a}, {suffix} {b}"));
291	    let a_zero = f.fresh();
292	    let b_zero = f.fresh();
293	    f.line(&format!("{a_zero} = fcmp oeq {suffix} {a}, 0.0"));
294	    f.line(&format!("{b_zero} = fcmp oeq {suffix} {b}, 0.0"));
295	    let both_zero = f.fresh();
296	    f.line(&format!("{both_zero} = and i1 {a_zero}, {b_zero}"));
297	    let a_bits = f.fresh();
298	    let b_bits = f.fresh();
299	    f.line(&format!("{a_bits} = bitcast {suffix} {a} to {intty}"));
300	    f.line(&format!("{b_bits} = bitcast {suffix} {b} to {intty}"));
301	    let a_sign = f.fresh();
302	    let b_sign = f.fresh();
303	    f.line(&format!("{a_sign} = and {intty} {a_bits}, {sign}"));
304	    f.line(&format!("{b_sign} = and {intty} {b_bits}, {sign}"));
305	    let zero_sign = f.fresh();
306	    f.line(&format!("{zero_sign} = {} {intty} {a_sign}, {b_sign}", if maximum { "and" } else { "or" }));
307	    let zero = f.fresh();
308	    f.line(&format!("{zero} = bitcast {intty} {zero_sign} to {suffix}"));
309	    let with_zero = f.fresh();
310	    f.line(&format!("{with_zero} = select i1 {both_zero}, {suffix} {zero}, {suffix} {ordered}"));
311	    let nan = f.fresh();
312	    f.line(&format!("{nan} = bitcast {intty} {canonical_nan} to {suffix}"));
313	    let result = f.fresh();
314	    f.line(&format!("{result} = select i1 {any_nan}, {suffix} {nan}, {suffix} {with_zero}"));
315	    let _ = mag;
316	    result
317	}
