319	fn emit_copysign(f: &mut FunctionEmitter<'_>, ty: ValType, magnitude: &str, sign_source: &str) -> String {
320	    let (intty, suffix, sign_mask, abs_mask) = if ty == F32 {
321	        ("i32", "float", i32::MIN as i64, i32::MAX as i64)
322	    } else {
323	        ("i64", "double", i64::MIN, i64::MAX)
324	    };
325	    let mag = f.fresh();
326	    let sign = f.fresh();
327	    f.line(&format!("{mag} = bitcast {suffix} {magnitude} to {intty}"));
328	    f.line(&format!("{sign} = bitcast {suffix} {sign_source} to {intty}"));
329	    let mag2 = f.fresh();
330	    let sign2 = f.fresh();
331	    f.line(&format!("{mag2} = and {intty} {mag}, {abs_mask}"));
332	    f.line(&format!("{sign2} = and {intty} {sign}, {sign_mask}"));
333	    let bits = f.fresh();
334	    f.line(&format!("{bits} = or {intty} {mag2}, {sign2}"));
335	    let result = f.fresh();
336	    f.line(&format!("{result} = bitcast {intty} {bits} to {suffix}"));
337	    result
338	}
