340	fn emit_conversion(f: &mut FunctionEmitter<'_>, op: u8) -> Result<(), String> {
341	    match op {
342	        0xa7 => { let value = f.pop(I64)?; let r = f.fresh(); f.line(&format!("{r} = trunc i64 {value} to i32")); f.push(I32, &r) }
343	        0xa8..=0xab | 0xae..=0xb1 => emit_trapping_float_to_int(f, op),
344	        0xac | 0xad => {
345	            let value = f.pop(I32)?; let r = f.fresh();
346	            f.line(&format!("{r} = {} i32 {value} to i64", if op == 0xac { "sext" } else { "zext" }));
347	            f.push(I64, &r)
348	        }
349	        0xb2..=0xb5 => {
350	            let (input, signed) = if op == 0xb2 || op == 0xb3 { (I32, op == 0xb2) } else { (I64, op == 0xb4) };
351	            let value = f.pop(input)?; let r = f.fresh();
352	            f.line(&format!("{r} = {} {} {value} to float", if signed { "sitofp" } else { "uitofp" }, input.llvm()));
353	            f.push(F32, &r)
354	        }
355	        0xb6 => {
356	            let value = f.pop(F64)?; let r = f.fresh(); f.line(&format!("{r} = fptrunc double {value} to float")); f.push(F32, &r)
357	        }
358	        0xb7..=0xba => {
359	            let (input, signed) = if op == 0xb7 || op == 0xb8 { (I32, op == 0xb7) } else { (I64, op == 0xb9) };
360	            let value = f.pop(input)?; let r = f.fresh();
361	            f.line(&format!("{r} = {} {} {value} to double", if signed { "sitofp" } else { "uitofp" }, input.llvm()));
362	            f.push(F64, &r)
363	        }
364	        0xbb => {
365	            let value = f.pop(F32)?; let r = f.fresh(); f.line(&format!("{r} = fpext float {value} to double")); f.push(F64, &r)
366	        }
367	        0xbc => bitcast(f, I32, F32),
368	        0xbd => bitcast(f, I64, F64),
369	        0xbe => bitcast(f, F32, I32),
370	        0xbf => bitcast(f, F64, I64),
371	        _ => Err("invalid numeric conversion opcode".into()),
372	    }
373	}
374	
375	fn bitcast(f: &mut FunctionEmitter<'_>, input: ValType, output: ValType) -> Result<(), String> {
376	    let value = f.pop(input)?;
377	    let result = f.fresh();
378	    f.line(&format!("{result} = bitcast {} {value} to {}", input.llvm(), output.llvm()));
379	    f.push(output, &result)
380	}
381	
382	fn emit_trapping_float_to_int(f: &mut FunctionEmitter<'_>, op: u8) -> Result<(), String> {
383	    let (input, output, signed) = match op {
384	        0xa8 => (F32, I32, true), 0xa9 => (F32, I32, false),
385	        0xaa => (F64, I32, true), 0xab => (F64, I32, false),
386	        0xae => (F32, I64, true), 0xaf => (F32, I64, false),
387	        0xb0 => (F64, I64, true), 0xb1 => (F64, I64, false),
388	        _ => return Err("invalid trapping conversion opcode".into()),
389	    };
390	    let value = f.pop(input)?;
391	    let is_nan = f.fresh();
392	    f.line(&format!("{is_nan} = fcmp uno {} {value}, {value}", input.llvm()));
393	    f.emit_trap_if(&is_nan, 3);
394	    let (lower_bits, upper_bits, lower_out) = float_range_bits(input, output, signed);
395	    let lower = bitcast_float_constant(f, input, lower_bits);
396	    let upper = bitcast_float_constant(f, input, upper_bits);
397	    let low_bad = f.fresh();
398	    let high_bad = f.fresh();
399	    f.line(&format!("{low_bad} = fcmp {} {} {value}, {lower}", if lower_out { "ole" } else { "olt" }, input.llvm()));
400	    f.line(&format!("{high_bad} = fcmp oge {} {value}, {upper}", input.llvm()));
401	    let bad = f.fresh();
402	    f.line(&format!("{bad} = or i1 {low_bad}, {high_bad}"));
403	    f.emit_trap_if(&bad, 2);
404	    let result = f.fresh();
405	    f.line(&format!("{result} = {} {} {value} to {}", if signed { "fptosi" } else { "fptoui" }, input.llvm(), output.llvm()));
406	    f.push(output, &result)
407	}
408	
409	fn float_range_bits(input: ValType, output: ValType, signed: bool) -> (u64, u64, bool) {
410	    match (input, output, signed) {
411	        (F32, I32, true) => (0xcf00_0000, 0x4f00_0000, false),
412	        (F32, I32, false) => (0xbf80_0000, 0x4f80_0000, true),
413	        (F32, I64, true) => (0xdf00_0000, 0x5f00_0000, false),
414	        (F32, I64, false) => (0xbf80_0000, 0x5f80_0000, true),
415	        (F64, I32, true) => (0xc1e0_0000_0000_0000, 0x41e0_0000_0000_0000, false),
416	        (F64, I32, false) => (0xbff0_0000_0000_0000, 0x41f0_0000_0000_0000, true),
417	        (F64, I64, true) => (0xc3e0_0000_0000_0000, 0x43e0_0000_0000_0000, false),
418	        (F64, I64, false) => (0xbff0_0000_0000_0000, 0x43f0_0000_0000_0000, true),
419	        _ => unreachable!(),
420	    }
421	}
422	
423	fn bitcast_float_constant(f: &mut FunctionEmitter<'_>, ty: ValType, bits: u64) -> String {
424	    let result = f.fresh();
425	    if ty == F32 {
426	        f.line(&format!("{result} = bitcast i32 {} to float", crate::codegen::i32_bits(bits as u32)));
427	    } else {
428	        f.line(&format!("{result} = bitcast i64 {} to double", crate::codegen::i64_bits(bits)));
429	    }
430	    result
431	}
