218	pub fn parse(bytes: &[u8]) -> Result<Module, String> {
219	    if bytes.len() < 8 || &bytes[..4] != b"\0asm" {
220	        return Err("invalid WebAssembly magic".into());
221	    }
222	    if bytes[4..8] != [1, 0, 0, 0] {
223	        return Err("unsupported WebAssembly version".into());
224	    }
225	
226	    let mut module = Module::default();
227	    let mut reader = Reader::new(&bytes[8..]);
228	    let mut last_rank = 0u8;
229	    let mut seen = [false; 13];
230	    let mut defined_type_indices = Vec::new();
231	
232	    while !reader.eof() {
233	        let id = reader.byte()?;
234	        let size = reader.u32()? as usize;
235	        let mut section = reader.subreader(size)?;
236	        if id == 0 {
237	            let _ = section.name()?;
238	            continue;
239	        }
240	        if id > 12 || id == 0 {
241	            return Err(format!("unknown section id {id}"));
242	        }
243	        let rank = match id {
244	            1..=9 => id,
245	            12 => 10,
246	            10 => 11,
247	            11 => 12,
248	            _ => unreachable!(),
249	        };
250	        if seen[id as usize] {
251	            return Err(format!("duplicate section id {id}"));
252	        }
253	        if rank <= last_rank {
254	            return Err(format!("section {id} is out of order"));
255	        }
256	        seen[id as usize] = true;
257	        last_rank = rank;
258	
259	        match id {
260	            1 => parse_types(&mut section, &mut module)?,
261	            2 => parse_imports(&mut section, &mut module)?,
262	            3 => parse_function_section(&mut section, &mut module, &mut defined_type_indices)?,
263	            4 => parse_tables(&mut section, &mut module)?,
264	            5 => parse_memories(&mut section, &mut module)?,
265	            6 => parse_globals(&mut section, &mut module)?,
266	            7 => parse_exports(&mut section, &mut module)?,
267	            8 => {
268	                let index = section.u32()?;
269	                module.start = Some(index);
270	            }
271	            9 => parse_elements(&mut section, &mut module)?,
272	            10 => parse_code(&mut section, &mut module)?,
273	            11 => parse_data(&mut section, &mut module)?,
274	            12 => module.declared_data_count = Some(section.u32()?),
275	            _ => unreachable!(),
276	        }
277	        section.finish()?;
278	    }
279	
280	    let defined_count = defined_type_indices.len();
281	    if module.functions.len() != module.imported_functions + defined_count {
282	        return Err("function and code section counts do not match".into());
283	    }
284	    if defined_count != 0 && !seen[10] {
285	        return Err("function section is missing code section".into());
286	    }
287	    if seen[10] && module.functions.len() != module.imported_functions + defined_count {
288	        return Err("function and code section counts do not match".into());
289	    }
290	    if let Some(n) = module.declared_data_count {
291	        if n as usize != module.data.len() {
292	            return Err("data count does not match data section".into());
293	        }
294	    }
295	    if module.saw_memory_init_or_drop && module.declared_data_count.is_none() {
296	        return Err("memory.init/data.drop requires a data-count section".into());
297	    }
298	
299	    validate_indices(&module)?;
300	    Ok(module)
301	}
