303	fn parse_types(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
304	    for _ in 0..r.count()? {
305	        if r.byte()? != 0x60 {
306	            return Err("unsupported type form".into());
307	        }
308	        let params = read_types(r)?;
309	        let results = read_types(r)?;
310	        module.types.push(FuncType { params, results });
311	    }
312	    Ok(())
313	}
