315	fn parse_imports(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
316	    for _ in 0..r.count()? {
317	        let module_name = r.name()?;
318	        let field_name = r.name()?;
319	        let kind = r.byte()?;
320	        match kind {
321	            0 => {
322	                let type_idx = r.u32()?;
323	                module.functions.push(Function {
324	                    type_idx,
325	                    import: Some((module_name, field_name)),
326	                    locals: Vec::new(),
327	                    body: Vec::new(),
328	                    max_stack: 0,
329	                });
330	                module.imported_functions += 1;
331	            }
332	            1 => return Err("imported tables are outside the supported ABI".into()),
333	            2 => return Err("imported memories are outside the supported ABI".into()),
334	            3 => return Err("imported globals are outside the supported ABI".into()),
335	            _ => return Err(format!("invalid import kind {kind}")),
336	        }
337	    }
338	    Ok(())
339	}
340	
341	fn parse_function_section(
342	    r: &mut Reader<'_>,
343	    module: &mut Module,
344	    defined_type_indices: &mut Vec<u32>,
345	) -> Result<(), String> {
346	    for _ in 0..r.count()? {
347	        let type_idx = r.u32()?;
348	        defined_type_indices.push(type_idx);
349	        module.functions.push(Function {
350	            type_idx,
351	            import: None,
352	            locals: Vec::new(),
353	            body: Vec::new(),
354	            max_stack: 0,
355	        });
356	    }
357	    Ok(())
358	}
