360	fn parse_tables(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
361	    let count = r.count()?;
362	    if count > 1 {
363	        return Err("multiple tables are outside the supported scope".into());
364	    }
365	    for _ in 0..count {
366	        if r.byte()? != 0x70 {
367	            return Err("only funcref tables are supported".into());
368	        }
369	        let limits = read_limits(r, false)?;
370	        module.tables.push(Table { limits });
371	    }
372	    Ok(())
373	}
374	
375	fn parse_memories(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
376	    let count = r.count()?;
377	    if count > 1 {
378	        return Err("multiple memories are outside the supported scope".into());
379	    }
380	    for _ in 0..count {
381	        let limits = read_limits(r, true)?;
382	        if limits.min > 65536 || limits.max.is_some_and(|m| m > 65536) {
383	            return Err("memory limits exceed the wasm32 page limit".into());
384	        }
385	        module.memories.push(Memory { limits });
386	    }
387	    Ok(())
