390	fn read_limits(r: &mut Reader<'_>, memory: bool) -> Result<Limits, String> {
391	    let flags = r.u32()?;
392	    if flags & !1 != 0 {
393	        return Err(if memory {
394	            "shared and memory64 memories are outside the supported scope".into()
395	        } else {
396	            "unsupported table limits flags".into()
397	        });
398	    }
399	    let min = r.u32()?;
400	    let max = if flags & 1 != 0 { Some(r.u32()?) } else { None };
401	    if max.is_some_and(|m| m < min) {
402	        return Err("limits maximum is smaller than minimum".into());
403	    }
404	    Ok(Limits { min, max })
405	}
