407	fn parse_globals(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
408	    for _ in 0..r.count()? {
409	        let ty = read_valtype(r.byte()?)?;
410	        let mutable = match r.byte()? {
411	            0 => false,
412	            1 => true,
413	            other => return Err(format!("invalid global mutability {other}")),
414	        };
415	        let init = read_const_expr(r)?;
416	        if init.ty() != ty {
417	            return Err(format!("global initializer has type {}, expected {ty}", init.ty()));
418	        }
419	        module.globals.push(Global { ty, mutable, init });
420	    }
421	    Ok(())
422	}
