424	fn parse_exports(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
425	    for _ in 0..r.count()? {
426	        let name = r.name()?;
427	        let kind = match r.byte()? {
428	            0 => ExportKind::Function(r.u32()?),
429	            1 => ExportKind::Table(r.u32()?),
430	            2 => ExportKind::Memory(r.u32()?),
431	            3 => ExportKind::Global(r.u32()?),
432	            other => return Err(format!("invalid export kind {other}")),
433	        };
434	        if module.exports.iter().any(|e| e.name == name) {
435	            return Err(format!("duplicate export name {name:?}"));
436	        }
437	        module.exports.push(Export { name, kind });
438	    }
439	    Ok(())
440	}
