442	fn parse_elements(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
443	    for _ in 0..r.count()? {
444	        let flags = r.u32()?;
445	        let (mode, has_elemkind) = match flags {
446	            0 => (SegmentMode::Active { index: 0, offset: read_const_expr(r)? }, false),
447	            1 => (SegmentMode::Passive, true),
448	            2 => {
449	                let table = r.u32()?;
450	                let offset = read_const_expr(r)?;
451	                (SegmentMode::Active { index: table, offset }, true)
452	            }
453	            3 => (SegmentMode::Declared, true),
454	            4..=7 => return Err("reference-type element expressions are outside the supported scope".into()),
455	            _ => return Err(format!("invalid element segment flags {flags}")),
456	        };
457	        if has_elemkind && r.byte()? != 0 {
458	            return Err("only funcref element segments are supported".into());
459	        }
460	        let mut functions = Vec::new();
461	        for _ in 0..r.count()? {
462	            functions.push(r.u32()?);
463	        }
464	        module.elements.push(ElementSegment { mode, functions });
465	    }
466	    Ok(())
467	}
