469	fn parse_data(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
470	    for _ in 0..r.count()? {
471	        let flags = r.u32()?;
472	        let mode = match flags {
473	            0 => SegmentMode::Active { index: 0, offset: read_const_expr(r)? },
474	            1 => SegmentMode::Passive,
475	            2 => {
476	                let memory = r.u32()?;
477	                let offset = read_const_expr(r)?;
478	                SegmentMode::Active { index: memory, offset }
479	            }
480	            _ => return Err(format!("invalid data segment flags {flags}")),
481	        };
482	        let len = r.count()?;
483	        let bytes = r.bytes(len)?.to_vec();
484	        module.data.push(DataSegment { mode, bytes });
485	    }
486	    Ok(())
487	}
