489	fn parse_code(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
490	    let count = r.count()?;
491	    let defined_count = module.functions.len().saturating_sub(module.imported_functions);
492	    if count != defined_count {
493	        return Err("function and code section counts do not match".into());
494	    }
495	    for body_index in 0..count {
496	        let size = r.count()?;
497	        let mut body = r.subreader(size)?;
498	        let mut locals = Vec::new();
499	        for _ in 0..body.count()? {
500	            let n = body.count()?;
501	            let ty = read_valtype(body.byte()?)?;
502	            if locals.len().saturating_add(n) > 10_000_000 {
503	                return Err("too many locals".into());
504	            }
505	            locals.resize(locals.len() + n, ty);
506	        }
507	        let types = &module.types;
508	        let (instructions, end) = parse_instr_seq(&mut body, types, false)?;
509	        if end != SeqEnd::End {
510	            return Err("unexpected else at function end".into());
511	        }
512	        body.finish()?;
513	        let function = &mut module.functions[module.imported_functions + body_index];
514	        function.locals = locals;
515	        function.body = instructions;
516	    }
517	    Ok(())
518	}
