520	#[derive(Clone, Copy, PartialEq, Eq)]
521	enum SeqEnd {
522	    End,
523	    Else,
524	}
525	
526	fn parse_instr_seq(
527	    r: &mut Reader<'_>,
528	    types: &[FuncType],
529	    allow_else: bool,
530	) -> Result<(Vec<Instr>, SeqEnd), String> {
531	    let mut out = Vec::new();
532	    loop {
533	        let op = r.byte()?;
534	        match op {
535	            0x0b => return Ok((out, SeqEnd::End)),
536	            0x05 if allow_else => return Ok((out, SeqEnd::Else)),
537	            0x05 => return Err("unexpected else instruction".into()),
538	            0x00 => out.push(Instr::Unreachable),
539	            0x01 => out.push(Instr::Nop),
540	            0x02..=0x04 => {
541	                let sig = resolve_blocktype(read_blocktype(r)?, types)?;
542	                if op == 0x04 {
543	                    let (then_body, ending) = parse_instr_seq(r, types, true)?;
544	                    let else_body = if ending == SeqEnd::Else {
545	                        let (body, end) = parse_instr_seq(r, types, false)?;
546	                        if end != SeqEnd::End {
547	                            return Err("unexpected else at if end".into());
548	                        }
549	                        Some(body)
550	                    } else {
551	                        None
552	                    };
553	                    out.push(Instr::If(sig, then_body, else_body));
554	                } else {
555	                    let (body, ending) = parse_instr_seq(r, types, false)?;
556	                    if ending != SeqEnd::End {
557	                        return Err("unexpected else in block".into());
558	                    }
559	                    if op == 0x02 {
560	                        out.push(Instr::Block(sig, body));
561	                    } else {
562	                        out.push(Instr::Loop(sig, body));
563	                    }
564	                }
565	            }
566	            0x0c => out.push(Instr::Br(r.u32()?)),
567	            0x0d => out.push(Instr::BrIf(r.u32()?)),
568	            0x0e => {
569	                let n = r.count()?;
570	                let mut targets = Vec::with_capacity(n);
571	                for _ in 0..n {
572	                    targets.push(r.u32()?);
573	                }
574	                out.push(Instr::BrTable(targets, r.u32()?));
575	            }
576	            0x0f => out.push(Instr::Return),
577	            0x10 => out.push(Instr::Call(r.u32()?)),
578	            0x11 => out.push(Instr::CallIndirect { ty: r.u32()?, table: r.u32()? }),
579	            0x1a => out.push(Instr::Drop),
580	            0x1b => out.push(Instr::Select(None)),
581	            0x1c => return Err("typed select is outside the supported scope".into()),
582	            0x20 => out.push(Instr::LocalGet(r.u32()?)),
583	            0x21 => out.push(Instr::LocalSet(r.u32()?)),
584	            0x22 => out.push(Instr::LocalTee(r.u32()?)),
585	            0x23 => out.push(Instr::GlobalGet(r.u32()?)),
586	            0x24 => out.push(Instr::GlobalSet(r.u32()?)),
587	            0x28..=0x35 => {
588	                let align = r.u32()?;
589	                let offset = r.u32()?;
590	                out.push(Instr::Load { op, align, offset });
591	            }
592	            0x36..=0x3e => {
593	                let align = r.u32()?;
594	                let offset = r.u32()?;
595	                out.push(Instr::Store { op, align, offset });
596	            }
597	            0x3f => out.push(Instr::MemorySize(r.u32()?)),
598	            0x40 => out.push(Instr::MemoryGrow(r.u32()?)),
599	            0x41 => out.push(Instr::Const(ConstExpr::I32(r.i32()?))),
600	            0x42 => out.push(Instr::Const(ConstExpr::I64(r.i64()?))),
601	            0x43 => out.push(Instr::Const(ConstExpr::F32(u32::from_le_bytes(r.bytes(4)?.try_into().unwrap())))),
602	            0x44 => out.push(Instr::Const(ConstExpr::F64(u64::from_le_bytes(r.bytes(8)?.try_into().unwrap())))),
603	            0x45..=0xbf => out.push(Instr::Numeric(op)),
604	            0xc0..=0xc4 => out.push(Instr::SignExtend(op)),
605	            0xfc => {
606	                let misc = r.u32()?;
607	                let instruction = match misc {
608	                    0..=7 => Instr::Saturating(misc),
609	                    8 => {
610	                        let data = r.u32()?;
611	                        let memory = r.u32()?;
612	                        module_note_memory_init();
613	                        Instr::Bulk(BulkOp::MemoryInit { data, memory })
614	                    }
615	                    9 => {
616	                        let data = r.u32()?;
617	                        module_note_memory_init();
