621	                    11 => Instr::Bulk(BulkOp::MemoryFill { memory: r.u32()? }),
622	                    12 => Instr::Bulk(BulkOp::TableInit { element: r.u32()?, table: r.u32()? }),
623	                    13 => Instr::Bulk(BulkOp::ElementDrop { element: r.u32()? }),
624	                    14 => Instr::Bulk(BulkOp::TableCopy { dst: r.u32()?, src: r.u32()? }),
625	                    15 => Instr::Bulk(BulkOp::TableGrow { table: r.u32()? }),
626	                    16 => Instr::Bulk(BulkOp::TableSize { table: r.u32()? }),
627	                    17 => Instr::Bulk(BulkOp::TableFill { table: r.u32()? }),
628	                    _ => return Err(format!("unsupported 0xfc opcode {misc}")),
629	                };
