251	                self.push(ty);
252	            }
253	            Instr::GlobalGet(index) => self.push(self.global(*index)?.ty),
254	            Instr::GlobalSet(index) => {
255	                let global = self.global(*index)?;
256	                if !global.mutable {
257	                    return Err(self.error("global.set targets an immutable global"));
258	                }
259	                self.pop_expect(global.ty)?;
260	            }
261	            Instr::Load { op, align, .. } => {
262	                let (ty, width) = load_type(*op).ok_or_else(|| self.error("invalid load opcode"))?;
263	                check_align(*align, width, self)?;
264	                self.require_memory()?;
265	                self.pop_expect(ValType::I32)?;
266	                self.push(ty);
267	            }
268	            Instr::Store { op, align, .. } => {
269	                let (ty, width) = store_type(*op).ok_or_else(|| self.error("invalid store opcode"))?;
270	                check_align(*align, width, self)?;
271	                self.require_memory()?;
272	                self.pop_expect(ty)?;
273	                self.pop_expect(ValType::I32)?;
274	            }
275	            Instr::MemorySize(index) | Instr::MemoryGrow(index) => {
276	                if *index != 0 || self.module.memories.is_empty() {
277	                    return Err(self.error("memory instruction requires memory 0"));
278	                }
279	                if matches!(instr, Instr::MemoryGrow(_)) {
280	                    self.pop_expect(ValType::I32)?;
281	                    self.push(ValType::I32);
282	                } else {
283	                    self.push(ValType::I32);
284	                }
285	            }
286	            Instr::Const(value) => self.push(value.ty()),
287	            Instr::Numeric(op) => {
288	                let (inputs, output) = numeric_signature(*op).ok_or_else(|| self.error("invalid numeric opcode"))?;
289	                self.pop_types(&inputs)?;
290	                if let Some(output) = output { self.push(output); }
291	            }
292	            Instr::SignExtend(op) => {
293	                let ty = match op {
294	                    0xc0 | 0xc1 => ValType::I32,
295	                    0xc2..=0xc4 => ValType::I64,
296	                    _ => return Err(self.error("invalid sign-extension opcode")),
297	                };
298	                self.pop_expect(ty)?;
299	                self.push(ty);
300	            }
301	            Instr::Saturating(op) => {
302	                let (input, output) = saturating_signature(*op).ok_or_else(|| self.error("invalid saturating conversion opcode"))?;
303	                self.pop_expect(input)?;
304	                self.push(output);
305	            }
306	            Instr::Bulk(op) => self.validate_bulk(op)?,
307	            Instr::Simd { op, immediate } => self.validate_simd(*op, immediate)?,
308	        }
309	        Ok(())
310	    }
311	
312	    fn validate_control(
313	        &mut self,
314	        sig: &BlockSig,
315	        kind: ControlKind,
316	        body: &[Instr],
317	        else_body: Option<&[Instr]>,
318	    ) -> Result<(), String> {
319	        self.pop_types(&sig.params)?;
320	        let height = self.stack.len();
321	        for &ty in &sig.params { self.push(ty); }
322	        self.controls.push(ControlFrame {
323	            kind,
324	            height,
325	            params: sig.params.clone(),
326	            results: sig.results.clone(),
327	            unreachable: false,
328	        });
329	        self.validate_seq(body)?;
330	        self.finish_current()?;
331	        if let Some(else_body) = else_body {
332	            let frame = self.controls.last_mut().expect("control frame");
333	            self.stack.truncate(frame.height);
334	            for &ty in &frame.params { self.stack.push(Some(ty)); }
335	            frame.unreachable = false;
336	            self.validate_seq(else_body)?;
337	            self.finish_current()?;
338	        }
339	        let frame = self.controls.pop().expect("control frame");
340	        for &ty in &frame.results { self.push(ty); }
341	        Ok(())
342	    }
