344	    fn finish_current(&mut self) -> Result<(), String> {
345	        let (height, results, kind) = {
346	            let frame = self.current();
347	            (frame.height, frame.results.clone(), frame.kind)
348	        };
349	        self.pop_types(&results)?;
350	        if self.stack.len() != height {
351	            return Err(self.error(match kind {
352	                ControlKind::Function => "function result stack has extra values",
353	                _ => "block result stack has extra values",
354	            }));
355	        }
356	        Ok(())
357	    }
