359	    fn label_types(&self, depth: u32) -> Result<Vec<ValType>, String> {
360	        let index = self.controls.len().checked_sub(depth as usize + 1)
361	            .ok_or_else(|| self.error("branch depth is out of bounds"))?;
362	        let frame = &self.controls[index];
363	        Ok(if frame.kind == ControlKind::Loop { frame.params.clone() } else { frame.results.clone() })
364	    }
