366	    fn function_type(&self, index: u32) -> Result<&FuncType, String> {
367	        let function = self.module.functions.get(index as usize)
368	            .ok_or_else(|| self.error("call function index is out of bounds"))?;
369	        self.module.types.get(function.type_idx as usize)
370	            .ok_or_else(|| self.error("function type index is out of bounds"))
371	    }
