387	    fn validate_bulk(&mut self, op: &BulkOp) -> Result<(), String> {
388	        match op {
389	            BulkOp::MemoryInit { data, memory } => {
390	                if *memory != 0 || self.module.memories.is_empty() || *data as usize >= self.module.data.len() {
391	                    return Err(self.error("memory.init index is out of bounds"));
392	                }
393	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
394	            }
395	            BulkOp::DataDrop { data } => {
396	                if *data as usize >= self.module.data.len() { return Err(self.error("data.drop index is out of bounds")); }
397	            }
398	            BulkOp::MemoryCopy { dst, src } => {
399	                if *dst != 0 || *src != 0 || self.module.memories.is_empty() { return Err(self.error("memory.copy index is out of bounds")); }
400	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
401	            }
402	            BulkOp::MemoryFill { memory } => {
403	                if *memory != 0 || self.module.memories.is_empty() { return Err(self.error("memory.fill index is out of bounds")); }
404	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
405	            }
406	            BulkOp::TableInit { element, table } => {
407	                if *table != 0 || self.module.tables.is_empty() || *element as usize >= self.module.elements.len() {
408	                    return Err(self.error("table.init index is out of bounds"));
409	                }
410	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
411	            }
412	            BulkOp::ElementDrop { element } => {
413	                if *element as usize >= self.module.elements.len() { return Err(self.error("elem.drop index is out of bounds")); }
414	            }
415	            BulkOp::TableCopy { dst, src } => {
416	                if *dst != 0 || *src != 0 || self.module.tables.is_empty() { return Err(self.error("table.copy index is out of bounds")); }
417	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
418	            }
419	            BulkOp::TableGrow { .. } | BulkOp::TableFill { .. } => {
420	                return Err(self.error("table.grow/fill require reference types, which are outside the supported scope"));
421	            }
422	            BulkOp::TableSize { .. } => {
423	                return Err(self.error("table.size requires reference types, which are outside the supported scope"));
424	            }
425	        }
426	        Ok(())
427	    }
