429	    fn validate_simd(&mut self, op: u32, immediate: &crate::wasm::SimdImmediate) -> Result<(), String> {
430	        if let Some((align, width)) = crate::simd::memory_access(op, immediate) {
431	            check_align(align, width, self)?;
432	            self.require_memory()?;
433	            match op {
434	                0x0b => self.pop_expect(ValType::V128)?,
435	                0x58..=0x5b => self.pop_expect(ValType::V128)?,
436	                _ => {}
437	            }
438	            self.pop_expect(ValType::I32)?;
439	            if matches!(op, 0x00..=0x0a | 0x5c..=0x5d) { self.push(ValType::V128); }
440	            else if matches!(op, 0x54..=0x57) { self.pop_expect(ValType::V128)?; self.push(ValType::V128); }
441	            return Ok(());
442	        }
443	        let (inputs, output) = crate::simd::signature(op)
444	            .ok_or_else(|| self.error(format!("unsupported SIMD opcode 0x{op:x}")))?;
445	        if let crate::wasm::SimdImmediate::Lane(lane) = immediate {
446	            if *lane >= crate::simd::lane_count(op) {
447	                return Err(self.error("SIMD lane index is out of bounds"));
448	            }
449	        }
450	        if let crate::wasm::SimdImmediate::Bytes(bytes) = immediate {
451	            if op == 0x0d && bytes.iter().any(|&lane| lane >= 32) {
452	                return Err(self.error("i8x16.shuffle lane index is out of bounds"));
453	            }
454	        }
455	        self.pop_types(&inputs)?;
456	        if let Some(output) = output { self.push(output); }
457	        Ok(())
458	    }
459	}
