152	fn emit_import_wrapper(out: &mut String, module: &Module, index: usize) -> Result<(), String> {
153	    let function = &module.functions[index];
154	    let (import_module, import_name) = function.import.as_ref().ok_or("not an import")?;
155	    let ty = module.types.get(function.type_idx as usize).ok_or("invalid import function type")?;
156	    let args = ty.params.iter().enumerate().map(|(i,t)| format!("{} %p{i}", t.llvm())).collect::<Vec<_>>().join(", ");
157	    let ret = return_type(&ty.results);
158	    let _ = writeln!(out, "define internal {ret} @{}({args}) {{\nentry:", fn_name(index));
159	    out.push_str("  call void @w2l_depth_enter()\n");
160	    let arg_slots = ty.params.len().max(1);
161	    let result_slots = ty.results.len().max(1);
162	    let _ = writeln!(out, "  %args = alloca [{arg_slots} x <16 x i8>], align 16");
163	    let _ = writeln!(out, "  %results = alloca [{result_slots} x <16 x i8>], align 16");
164	    for (i, param) in ty.params.iter().enumerate() {
165	        let _ = writeln!(out, "  %arg_slot_{i} = getelementptr [{arg_slots} x <16 x i8>], ptr %args, i32 0, i32 {i}");
166	        let _ = writeln!(out, "  store {} %p{i}, ptr %arg_slot_{i}, align 1", param.llvm());
167	    }
168	    for i in 0..ty.results.len() {
169	        let _ = writeln!(out, "  %result_slot_init_{i} = getelementptr [{result_slots} x <16 x i8>], ptr %results, i32 0, i32 {i}");
170	        let _ = writeln!(out, "  store <16 x i8> zeroinitializer, ptr %result_slot_init_{i}, align 16");
171	    }
172	    let m = hex(import_module.as_bytes());
173	    let n = hex(import_name.as_bytes());
174	    let _ = writeln!(out, "  call void @w2l_import_{m}_{n}(ptr %args, ptr %results)");
175	    let mut values = Vec::new();
176	    for (i, result) in ty.results.iter().enumerate() {
177	        let _ = writeln!(out, "  %result_slot_{i} = getelementptr [{result_slots} x <16 x i8>], ptr %results, i32 0, i32 {i}");
178	        let _ = writeln!(out, "  %result_{i} = load {}, ptr %result_slot_{i}, align 1", result.llvm());
179	        values.push(format!("%result_{i}"));
180	    }
181	    out.push_str("  call void @w2l_depth_leave()\n");
182	    emit_return(out, &ty.results, &values);
183	    out.push_str("}\n");
184	    Ok(())
185	}
