220	            let _ = writeln!(out, "  call void @llvm.memset.p0.i64(ptr %table, i8 -1, i64 {bytes}, i1 false)");
221	        }
222	        let _ = writeln!(out, "  store i32 {}, ptr @w2l_table_size", i32_bits(table.limits.min));
223	    }
224	    for (index, global) in module.globals.iter().enumerate() {
225	        match global.init {
226	            ConstExpr::I32(value) => { let _ = writeln!(out, "  store i32 {value}, ptr @w2l_g{index}"); }
227	            ConstExpr::I64(value) => { let _ = writeln!(out, "  store i64 {value}, ptr @w2l_g{index}"); }
228	            ConstExpr::F32(bits) => {
229	                let _ = writeln!(out, "  %global_init_{index} = bitcast i32 {} to float\n  store float %global_init_{index}, ptr @w2l_g{index}", i32_bits(bits));
230	            }
231	            ConstExpr::F64(bits) => {
232	                let _ = writeln!(out, "  %global_init_{index} = bitcast i64 {} to double\n  store double %global_init_{index}, ptr @w2l_g{index}", i64_bits(bits));
233	            }
234	        }
235	    }
236	    for (index, data) in module.data.iter().enumerate() {
237	        if let SegmentMode::Active { offset, .. } = &data.mode {
238	            if let ConstExpr::I32(offset) = offset {
239	                let _ = writeln!(out, "  %data_dst_{index} = call ptr @w2l_mem_ptr(i32 {offset}, i32 0, i64 {})", data.bytes.len());
240	                if !data.bytes.is_empty() {
241	                    let _ = writeln!(out, "  call void @llvm.memcpy.p0.p0.i64(ptr %data_dst_{index}, ptr @w2l_data_{index}, i64 {}, i1 false)", data.bytes.len());
242	                }
243	            }
244	        }
245	    }
246	    for (index, elem) in module.elements.iter().enumerate() {
247	        if let SegmentMode::Active { offset, .. } = &elem.mode {
248	            if let ConstExpr::I32(offset) = offset {
249	                emit_active_element_init(out, index, i32_bits(*offset), elem.functions.len());
250	                for (slot, func) in elem.functions.iter().enumerate() {
251	                    let _ = writeln!(out, "  %elem_dst_{index}_{slot} = getelementptr i32, ptr %elem_base_{index}, i64 %elem_index_{index}_{slot}\n  store i32 {}, ptr %elem_dst_{index}_{slot}, align 4", i32_bits(*func));
252	                }
253	            }
254	        }
255	    }
256	    if let Some(start) = module.start {
257	        let _ = writeln!(out, "  call void @{}()", fn_name(start as usize));
258	    }
259	    out.push_str("  ret void\n}\n\n");
260	}
261	
262	fn emit_active_element_init(out: &mut String, index: usize, offset: i32, count: usize) {
263	    let _ = writeln!(out, "  %elem_offset_{index} = zext i32 {offset} to i64\n  %elem_end_{index} = add i64 %elem_offset_{index}, {count}\n  %elem_size32_{index} = load i32, ptr @w2l_table_size\n  %elem_size_{index} = zext i32 %elem_size32_{index} to i64\n  %elem_oob_{index} = icmp ugt i64 %elem_end_{index}, %elem_size_{index}\n  br i1 %elem_oob_{index}, label %elem_trap_{index}, label %elem_ok_{index}\nelem_trap_{index}:\n  call void @w2l_trap(i32 5)\n  unreachable\nelem_ok_{index}:\n  %elem_base_{index} = load ptr, ptr @w2l_table_base");
264	    for slot in 0..count {
265	        let _ = writeln!(out, "  %elem_index_{index}_{slot} = add i64 %elem_offset_{index}, {slot}");
266	    }
267	}
268	
269	fn emit_exports(out: &mut String, module: &Module) -> Result<(), String> {
270	    for export in &module.exports {
271	        let name = hex(export.name.as_bytes());
272	        match export.kind {
273	            ExportKind::Function(index) => {
274	                let function = module.functions.get(index as usize).ok_or("invalid exported function")?;
275	                let ty = module.types.get(function.type_idx as usize).ok_or("invalid exported function type")?;
276	                let _ = writeln!(out, "define void @w2l_export_{name}(ptr %args, ptr %results) {{\nentry:\n  store i32 0, ptr @w2l_depth");
277	                let mut args = Vec::new();
278	                for (i, param) in ty.params.iter().enumerate() {
279	                    let _ = writeln!(out, "  %arg_ptr_{i} = getelementptr i8, ptr %args, i64 {}\n  %arg_{i} = load {}, ptr %arg_ptr_{i}, align 1", i * 16, param.llvm());
280	                    args.push(format!("%arg_{i}"));
281	                }
282	                let ret = return_type(&ty.results);
283	                if ty.results.is_empty() {
284	                    let _ = writeln!(out, "  call void @{}({})", fn_name(index as usize), typed_args(&ty.params, &args));
285	                } else {
286	                    let _ = writeln!(out, "  %call_result = call {ret} @{}({})", fn_name(index as usize), typed_args(&ty.params, &args));
287	                    for (i, result) in ty.results.iter().enumerate() {
288	                        let value = if ty.results.len() == 1 { "%call_result".to_string() } else {
289	                            let _ = writeln!(out, "  %result_{i} = extractvalue {ret} %call_result, {i}");
290	                            format!("%result_{i}")
291	                        };
292	                        let _ = writeln!(out, "  %result_ptr_{i} = getelementptr i8, ptr %results, i64 {}\n  store {} {value}, ptr %result_ptr_{i}, align 1", i * 16, result.llvm());
293	                    }
294	                }
295	                out.push_str("  ret void\n}\n\n");
296	            }
297	            ExportKind::Global(index) => {
298	                let global = module.globals.get(index as usize).ok_or("invalid exported global")?;
299	                let _ = writeln!(out, "define void @w2l_global_{name}(ptr %out) {{\nentry:\n  %value = load {}, ptr @w2l_g{index}\n  store {} %value, ptr %out, align 1\n  ret void\n}}\n", global.ty.llvm(), global.ty.llvm());
300	            }
301	            ExportKind::Memory(index) => {
302	                if index != 0 { return Err("only memory 0 can be exported".into()); }
303	                out.push_str(&format!("define ptr @w2l_memory_{name}(ptr %size_out) {{\nentry:\n  %size = load i64, ptr @w2l_mem_size\n  store i64 %size, ptr %size_out, align 1\n  %base = load ptr, ptr @w2l_mem_base\n  ret ptr %base\n}}\n\n"));
304	            }
305	            ExportKind::Table(_) => {}
306	        }
307	    }
308	    Ok(())
309	}
310	
311	fn typed_args(types: &[ValType], args: &[String]) -> String {
312	    types.iter().zip(args).map(|(ty, value)| format!("{} {value}", ty.llvm())).collect::<Vec<_>>().join(", ")
313	}
