100	            let [dst, value, len] = values.as_slice() else { unreachable!() };
101	            let length = zext_i32(f, len);
102	            check_memory_range(f, dst, &length)?;
103	            let dest = emit_mem_pointer(f, dst, 0, 0);
104	            let byte = f.fresh();
105	            f.line(&format!("{byte} = trunc i32 {value} to i8"));
