123	pub(crate) fn emit_mem_pointer(f: &mut FunctionEmitter<'_>, addr: &str, offset: u32, width: u64) -> String {
124	    let ptr = f.fresh();
125	    f.line(&format!("{ptr} = call ptr @w2l_mem_ptr(i32 {addr}, i32 {}, i64 {width})", crate::codegen::i32_bits(offset)));
