135	fn check_memory_range(f: &mut FunctionEmitter<'_>, addr: &str, len64: &str) -> Result<(), String> {
136	    let address = zext_i32(f, addr);
137	    let end = f.fresh();
138	    f.line(&format!("{end} = add i64 {address}, {len64}"));
139	    let size = f.fresh();
140	    f.line(&format!("{size} = load i64, ptr @w2l_mem_size"));
141	    let oob = f.fresh();
142	    f.line(&format!("{oob} = icmp ugt i64 {end}, {size}"));
143	    f.emit_trap_if(&oob, 4);
144	    Ok(())
145	}
