147	fn emit_memory_init(f: &mut FunctionEmitter<'_>, data: usize) -> Result<(), String> {
148	    let values = f.pop_values(&[ValType::I32, ValType::I32, ValType::I32])?;
149	    let [dst, src, len] = values.as_slice() else { unreachable!() };
150	    let src64 = zext_i32(f, src);
151	    let len64 = zext_i32(f, len);
152	    let src_end = f.fresh();
153	    f.line(&format!("{src_end} = add i64 {src64}, {len64}"));
154	    let segment_len = f.fresh();
155	    f.line(&format!("{segment_len} = load i64, ptr @w2l_data_len_{data}"));
156	    let src_oob = f.fresh();
157	    f.line(&format!("{src_oob} = icmp ugt i64 {src_end}, {segment_len}"));
158	    f.emit_trap_if(&src_oob, 4);
159	    let dest = emit_mem_pointer(f, dst, 0, 0);
160	    check_memory_range(f, dst, &len64)?;
161	    let source = f.fresh();
162	    f.line(&format!("{source} = getelementptr i8, ptr @w2l_data_{data}, i64 {src64}"));
163	    emit_if_nonzero(f, &len64, |f| {
164	        f.line(&format!("call void @llvm.memcpy.p0.p0.i64(ptr {dest}, ptr {source}, i64 {len64}, i1 false)"));
