174	    let source_end = f.fresh();
175	    f.line(&format!("{source_end} = add i64 {src64}, {len64}"));
176	    let elem_len = f.fresh();
177	    f.line(&format!("{elem_len} = load i64, ptr @w2l_elem_len_{element}"));
178	    let source_oob = f.fresh();
179	    f.line(&format!("{source_oob} = icmp ugt i64 {source_end}, {elem_len}"));
180	    f.emit_trap_if(&source_oob, 5);
181	    let dst64 = zext_i32(f, dst);
182	    let dest_end = f.fresh();
183	    f.line(&format!("{dest_end} = add i64 {dst64}, {len64}"));
184	    let table_size32 = f.fresh();
185	    f.line(&format!("{table_size32} = load i32, ptr @w2l_table_size"));
186	    let table_size = zext_i32(f, &table_size32);
187	    let dest_oob = f.fresh();
188	    f.line(&format!("{dest_oob} = icmp ugt i64 {dest_end}, {table_size}"));
189	    f.emit_trap_if(&dest_oob, 5);
190	    let table_base = f.fresh();
191	    f.line(&format!("{table_base} = load ptr, ptr @w2l_table_base"));
192	    let dest = f.fresh();
193	    f.line(&format!("{dest} = getelementptr i32, ptr {table_base}, i64 {dst64}"));
194	    let source = f.fresh();
195	    f.line(&format!("{source} = getelementptr i32, ptr @w2l_elem_{element}, i64 {src64}"));
196	    let bytes = f.fresh();
197	    f.line(&format!("{bytes} = shl i64 {len64}, 2"));
198	    emit_if_nonzero(f, &bytes, |f| {
199	        f.line(&format!("call void @llvm.memcpy.p0.p0.i64(ptr {dest}, ptr {source}, i64 {bytes}, i1 false)"));
200	        Ok(())
201	    })
202	}
