204	fn emit_table_copy(f: &mut FunctionEmitter<'_>) -> Result<(), String> {
205	    let values = f.pop_values(&[ValType::I32, ValType::I32, ValType::I32])?;
206	    let [dst, src, len] = values.as_slice() else { unreachable!() };
207	    let dst64 = zext_i32(f, dst);
208	    let src64 = zext_i32(f, src);
209	    let len64 = zext_i32(f, len);
210	    let dst_end = f.fresh();
211	    let src_end = f.fresh();
212	    f.line(&format!("{dst_end} = add i64 {dst64}, {len64}"));
213	    f.line(&format!("{src_end} = add i64 {src64}, {len64}"));
214	    let size32 = f.fresh();
215	    f.line(&format!("{size32} = load i32, ptr @w2l_table_size"));
216	    let size = zext_i32(f, &size32);
217	    let src_oob = f.fresh();
218	    f.line(&format!("{src_oob} = icmp ugt i64 {src_end}, {size}"));
219	    f.emit_trap_if(&src_oob, 5);
220	    let dst_oob = f.fresh();
221	    f.line(&format!("{dst_oob} = icmp ugt i64 {dst_end}, {size}"));
222	    f.emit_trap_if(&dst_oob, 5);
223	    let base = f.fresh();
224	    f.line(&format!("{base} = load ptr, ptr @w2l_table_base"));
225	    let source = f.fresh();
226	    let dest = f.fresh();
227	    f.line(&format!("{source} = getelementptr i32, ptr {base}, i64 {src64}"));
228	    f.line(&format!("{dest} = getelementptr i32, ptr {base}, i64 {dst64}"));
229	    let bytes = f.fresh();
230	    f.line(&format!("{bytes} = shl i64 {len64}, 2"));
231	    emit_if_nonzero(f, &bytes, |f| {
232	        f.line(&format!("call void @llvm.memmove.p0.p0.i64(ptr {dest}, ptr {source}, i64 {bytes}, i1 false)"));
233	        Ok(())
234	    })
235	}
236	
237	fn emit_if_nonzero(
238	    f: &mut FunctionEmitter<'_>,
239	    length: &str,
240	    body: impl FnOnce(&mut FunctionEmitter<'_>) -> Result<(), String>,
241	) -> Result<(), String> {
242	    let zero = f.fresh();
243	    f.line(&format!("{zero} = icmp eq i64 {length}, 0"));
244	    let done = f.fresh_label("bulk_done");
245	    let copy = f.fresh_label("bulk_nonzero");
246	    f.cond_branch(&zero, &done, &copy);
247	    f.start_label(&copy);
248	    body(f)?;
249	    f.branch(&done);
250	    f.start_label(&done);
251	    Ok(())
252	}
