28	pub fn validate_module(module: &mut Module) -> Result<(), String> {
29	    for (index, function) in module.functions.iter_mut().enumerate() {
30	        let ty = module.types.get(function.type_idx as usize)
31	            .ok_or_else(|| format!("function {index} has an invalid type index"))?;
32	        if function.import.is_some() {
33	            continue;
34	        }
35	        let mut locals = ty.params.clone();
36	        locals.extend_from_slice(&function.locals);
37	        let mut validator = Validator {
38	            module,
39	            function_index: index,
40	            locals,
41	            stack: Vec::new(),
42	            controls: vec![ControlFrame {
43	                kind: ControlKind::Function,
44	                height: 0,
45	                params: Vec::new(),
46	                results: ty.results.clone(),
47	                unreachable: false,
48	            }],
49	            max_stack: 0,
50	        };
51	        validator.validate_seq(&function.body)?;
52	        validator.finish_current()?;
53	        if validator.controls.len() != 1 || !validator.stack.is_empty() {
54	            return Err(validator.error("function body has an invalid final stack"));
55	        }
56	        function.max_stack = validator.max_stack.max(1);
57	    }
58	
59	    if uses_memory_init_or_drop(module.functions.iter().filter(|f| f.import.is_none()).map(|f| &f.body))
60	        && module.declared_data_count.is_none()
61	    {
62	        return Err("memory.init/data.drop requires a data-count section".into());
63	    }
64	    if let Some(count) = module.declared_data_count {
65	        if count as usize != module.data.len() {
66	            return Err("data count does not match data section".into());
67	        }
68	    }
69	    validate_segments(module)?;
70	    Ok(())
71	}
72	
73	fn validate_segments(module: &Module) -> Result<(), String> {
74	    for (index, segment) in module.elements.iter().enumerate() {
75	        if let SegmentMode::Active { index: table, offset } = &segment.mode {
76	            if *table != 0 || module.tables.is_empty() {
77	                return Err(format!("element segment {index} uses an invalid table"));
78	            }
79	            if offset.ty() != ValType::I32 {
