247	    let integer = lane_info(if lane.bits == 32 { "i32" } else { "i64" });
248	    let bits = as_lane(f, &args[0], integer);
249	    let result_bits = f.fresh();
250	    if op == 0xe0 || op == 0xec {
251	        let mask = if lane.bits == 32 { i32::MAX as i64 } else { i64::MAX };
252	        f.line(&format!("{result_bits} = and {} {bits}, splat ({} {mask})", integer.vector, integer.scalar));
253	    } else {
254	        let sign = if lane.bits == 32 { i32::MIN as i64 } else { i64::MIN };
255	        f.line(&format!("{result_bits} = xor {} {bits}, splat ({} {sign})", integer.vector, integer.scalar));
256	    }
257	    let result = cast_vector(f, &result_bits, integer.vector, lane.vector);
258	    let _ = value;
259	    push_lane(f, &result, lane)
260	}
