262	fn emit_float_binary(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
263	    let lane = lane_info(if op < 0xec { "f32" } else { "f64" });
264	    let args = vector_args(f, 2)?;
265	    let a = as_lane(f, &args[0], lane);
266	    let b = as_lane(f, &args[1], lane);
267	    let instruction = match op {
268	        0xe4 | 0xf0 => "fadd", 0xe5 | 0xf1 => "fsub", 0xe6 | 0xf2 => "fmul", _ => "fdiv",
269	    };
270	    let result = f.fresh();
271	    f.line(&format!("{result} = {instruction} {} {a}, {b}", lane.vector));
272	    push_lane(f, &result, lane)
273	}
