275	fn emit_float_minmax(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
276	    let lane = lane_info(if op < 0xec { "f32" } else { "f64" });
277	    let args = vector_args(f, 2)?;
278	    let a = as_lane(f, &args[0], lane);
279	    let b = as_lane(f, &args[1], lane);
280	    let pseudo = op == 0xea || op == 0xeb || op == 0xf6 || op == 0xf7;
281	    let maximum = op == 0xe9 || op == 0xeb || op == 0xf5 || op == 0xf7;
282	    if pseudo {
283	        let cmp = f.fresh();
284	        f.line(&format!("{cmp} = fcmp {} {} {a}, {b}", if maximum { "ogt" } else { "olt" }, lane.vector));
285	        let result = f.fresh();
286	        f.line(&format!("{result} = select <{} x i1> {cmp}, {} {a}, {} {b}", lane.lanes, lane.vector, lane.vector));
287	        return push_lane(f, &result, lane);
288	    }
289	    let int_lane = lane_info(if lane.bits == 32 { "i32" } else { "i64" });
290	    let a_nan = f.fresh();
291	    let b_nan = f.fresh();
292	    f.line(&format!("{a_nan} = fcmp uno {} {a}, {a}", lane.vector));
293	    f.line(&format!("{b_nan} = fcmp uno {} {b}, {b}", lane.vector));
294	    let any_nan = f.fresh();
295	    f.line(&format!("{any_nan} = or <{} x i1> {a_nan}, {b_nan}", lane.lanes));
296	    let cmp = f.fresh();
297	    f.line(&format!("{cmp} = fcmp {} {} {a}, {b}", if maximum { "ogt" } else { "olt" }, lane.vector));
298	    let ordered = f.fresh();
299	    f.line(&format!("{ordered} = select <{} x i1> {cmp}, {} {a}, {} {b}", lane.lanes, lane.vector, lane.vector));
300	    let a_zero = f.fresh();
301	    let b_zero = f.fresh();
302	    f.line(&format!("{a_zero} = fcmp oeq {} {a}, zeroinitializer", lane.vector));
303	    f.line(&format!("{b_zero} = fcmp oeq {} {b}, zeroinitializer", lane.vector));
304	    let both_zero = f.fresh();
305	    f.line(&format!("{both_zero} = and <{} x i1> {a_zero}, {b_zero}", lane.lanes));
306	    let a_bits = as_lane(f, &args[0], int_lane);
307	    let b_bits = as_lane(f, &args[1], int_lane);
308	    let sign_mask = if lane.bits == 32 { i32::MIN as i64 } else { i64::MIN };
309	    let a_sign = f.fresh();
310	    let b_sign = f.fresh();
311	    f.line(&format!("{a_sign} = and {} {a_bits}, splat ({} {sign_mask})", int_lane.vector, int_lane.scalar));
312	    f.line(&format!("{b_sign} = and {} {b_bits}, splat ({} {sign_mask})", int_lane.vector, int_lane.scalar));
313	    let zero_sign = f.fresh();
314	    f.line(&format!("{zero_sign} = {} {} {a_sign}, {b_sign}", if maximum { "and" } else { "or" }, int_lane.vector));
315	    let zero = cast_vector(f, &zero_sign, int_lane.vector, lane.vector);
316	    let with_zero = f.fresh();
317	    f.line(&format!("{with_zero} = select <{} x i1> {both_zero}, {} {zero}, {} {ordered}", lane.lanes, lane.vector, lane.vector));
318	    let nan_bits_value = if lane.bits == 32 { 0x7fc0_0000i64 } else { 0x7ff8_0000_0000_0000i64 };
319	    let nan_bits = splat_vector(f, int_lane, &nan_bits_value.to_string(), int_lane.scalar);
320	    let nan = cast_vector(f, &nan_bits, int_lane.vector, lane.vector);
321	    let result = f.fresh();
322	    f.line(&format!("{result} = select <{} x i1> {any_nan}, {} {nan}, {} {with_zero}", lane.lanes, lane.vector, lane.vector));
323	    push_lane(f, &result, lane)
324	}
