326	fn emit_average(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
327	    let lane = lane_info(if op == 0x7b { "i8" } else { "i16" });
328	    let wide = lane_info(if lane.bits == 8 { "i16" } else { "i32" });
329	    let args = vector_args(f, 2)?;
330	    let a = as_lane(f, &args[0], lane);
331	    let b = as_lane(f, &args[1], lane);
332	    let aw = f.fresh();
333	    let bw = f.fresh();
334	    f.line(&format!("{aw} = zext {} {a} to {}", lane.vector, wide.vector));
335	    f.line(&format!("{bw} = zext {} {b} to {}", lane.vector, wide.vector));
336	    let sum = f.fresh();
337	    f.line(&format!("{sum} = add {} {aw}, {bw}", wide.vector));
338	    let plus = f.fresh();
339	    f.line(&format!("{plus} = add {} {sum}, splat ({} 1)", wide.vector, wide.scalar));
340	    let avg = f.fresh();
341	    f.line(&format!("{avg} = lshr {} {plus}, splat ({} 1)", wide.vector, wide.scalar));
342	    let result = f.fresh();
343	    f.line(&format!("{result} = trunc {} {avg} to {}", wide.vector, lane.vector));
344	    push_lane(f, &result, lane)
345	}
