347	fn emit_q15mulr(f: &mut FunctionEmitter<'_>) -> Result<(), String> {
348	    let lane = lane_info("i16");
349	    let wide = lane_info("i32");
350	    let args = vector_args(f, 2)?;
351	    let a = as_lane(f, &args[0], lane);
352	    let b = as_lane(f, &args[1], lane);
353	    let aw = f.fresh();
354	    let bw = f.fresh();
355	    f.line(&format!("{aw} = sext <8 x i16> {a} to <8 x i32>"));
356	    f.line(&format!("{bw} = sext <8 x i16> {b} to <8 x i32>"));
357	    let product = f.fresh();
358	    f.line(&format!("{product} = mul <8 x i32> {aw}, {bw}"));
359	    let rounded = f.fresh();
360	    f.line(&format!("{rounded} = add <8 x i32> {product}, splat (<8 x i32> 16384)"));
361	    let shifted = f.fresh();
362	    f.line(&format!("{shifted} = ashr <8 x i32> {rounded}, splat (<8 x i32> 15)"));
363	    let below = f.fresh();
364	    f.line(&format!("{below} = icmp slt <8 x i32> {shifted}, splat (<8 x i32> -32768)"));
365	    let low = f.fresh();
366	    f.line(&format!("{low} = select <8 x i1> {below}, <8 x i32> splat (<8 x i32> -32768), <8 x i32> {shifted}"));
367	    let above = f.fresh();
368	    f.line(&format!("{above} = icmp sgt <8 x i32> {low}, splat (<8 x i32> 32767)"));
369	    let clamped = f.fresh();
370	    f.line(&format!("{clamped} = select <8 x i1> {above}, <8 x i32> splat (<8 x i32> 32767), <8 x i32> {low}"));
371	    let result = f.fresh();
372	    f.line(&format!("{result} = trunc <8 x i32> {clamped} to <8 x i16>"));
373	    let _ = wide;
374	    push_lane(f, &result, lane)
375	}
