377	fn emit_pairwise_add(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
378	    let (source, dest, signed) = match op {
379	        0x7c => (lane_info("i8"), lane_info("i16"), true),
380	        0x7d => (lane_info("i8"), lane_info("i16"), false),
381	        0x7e => (lane_info("i16"), lane_info("i32"), true),
382	        _ => (lane_info("i16"), lane_info("i32"), false),
383	    };
384	    let args = vector_args(f, 1)?;
385	    let value = as_lane(f, &args[0], source);
386	    let even_mask = (0..dest.lanes).map(|i| format!("i32 {}", i * 2)).collect::<Vec<_>>().join(", ");
387	    let odd_mask = (0..dest.lanes).map(|i| format!("i32 {}", i * 2 + 1)).collect::<Vec<_>>().join(", ");
388	    let even = f.fresh();
389	    let odd = f.fresh();
390	    f.line(&format!("{even} = shufflevector {} {value}, {} zeroinitializer, <{} x i32> <{even_mask}>", source.vector, source.vector, dest.lanes));
391	    f.line(&format!("{odd} = shufflevector {} {value}, {} zeroinitializer, <{} x i32> <{odd_mask}>", source.vector, source.vector, dest.lanes));
392	    let wide_even = f.fresh();
393	    let wide_odd = f.fresh();
394	    let extension = if signed { "sext" } else { "zext" };
395	    f.line(&format!("{wide_even} = {extension} {} {even} to {}", source.vector, dest.vector));
396	    f.line(&format!("{wide_odd} = {extension} {} {odd} to {}", source.vector, dest.vector));
397	    let sum = f.fresh();
398	    f.line(&format!("{sum} = add {} {wide_even}, {wide_odd}", dest.vector));
399	    push_lane(f, &sum, dest)
400	}
