432	fn emit_extmul(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
433	    let (source, dest, high, signed) = match op {
434	        0x9c => (lane_info("i8"), lane_info("i16"), false, true),
435	        0x9d => (lane_info("i8"), lane_info("i16"), true, true),
436	        0x9e => (lane_info("i8"), lane_info("i16"), false, false),
437	        0x9f => (lane_info("i8"), lane_info("i16"), true, false),
438	        0xbc => (lane_info("i16"), lane_info("i32"), false, true),
439	        0xbd => (lane_info("i16"), lane_info("i32"), true, true),
440	        0xbe => (lane_info("i16"), lane_info("i32"), false, false),
