442	        0xdc => (lane_info("i32"), lane_info("i64"), false, true),
443	        0xdd => (lane_info("i32"), lane_info("i64"), true, true),
444	        0xde => (lane_info("i32"), lane_info("i64"), false, false),
445	        _ => (lane_info("i32"), lane_info("i64"), true, false),
