447	    let args = vector_args(f, 2)?;
448	    let start = if high { source.lanes } else { 0 };
449	    let mask = (0..dest.lanes).map(|i| format!("i32 {}", start + i)).collect::<Vec<_>>().join(", ");
450	    let mut wide = Vec::new();
451	    for arg in args {
452	        let value = as_lane(f, &arg, source);
