313	fn emit_memory(f: &mut FunctionEmitter<'_>, op: u32, immediate: &SimdImmediate) -> Result<(), String> {
314	    let (_, width) = memory_access(op, immediate).ok_or("invalid SIMD memory instruction")?;
315	    let (offset, lane_index) = match immediate {
316	        SimdImmediate::MemArg { offset, .. } => (*offset, None),
317	        SimdImmediate::MemLane { offset, lane, .. } => (*offset, Some(*lane)),
318	        _ => return Err("malformed SIMD memory immediate".into()),
319	    };
320	    match op {
321	        0x0b => {
322	            let value = f.pop(ValType::V128)?;
323	            let address = f.pop(ValType::I32)?;
324	            let ptr = emit_mem_pointer(f, &address, offset, width as u64);
325	            f.line(&format!("store <16 x i8> {value}, ptr {ptr}, align 1"));
326	            Ok(())
327	        }
328	        0x58..=0x5b => {
329	            let address = f.pop(ValType::I32)?;
330	            let value = f.pop(ValType::V128)?;
331	            let lane = lane_info(match op { 0x58 => "i8", 0x59 => "i16", 0x5a => "i32", _ => "i64" });
332	            let vector = cast_vector(f, &value, "<16 x i8>", lane.vector);
333	            let scalar = f.fresh();
334	            f.line(&format!("{scalar} = extractelement {} {vector}, i32 {}", lane.vector, lane_index.unwrap()));
335	            let ptr = emit_mem_pointer(f, &address, offset, width as u64);
336	            f.line(&format!("store {} {scalar}, ptr {ptr}, align 1", lane.scalar));
337	            Ok(())
338	        }
339	        0x54..=0x57 => {
340	            let address = f.pop(ValType::I32)?;
341	            let value = f.pop(ValType::V128)?;
342	            let lane = lane_info(match op { 0x54 => "i8", 0x55 => "i16", 0x56 => "i32", _ => "i64" });
343	            let vector = cast_vector(f, &value, "<16 x i8>", lane.vector);
344	            let ptr = emit_mem_pointer(f, &address, offset, width as u64);
345	            let scalar = f.fresh();
346	            f.line(&format!("{scalar} = load {}, ptr {ptr}, align 1", lane.scalar));
347	            let updated = f.fresh();
348	            f.line(&format!("{updated} = insertelement {} {vector}, {} {scalar}, i32 {}", lane.vector, lane.scalar, lane_index.unwrap()));
349	            let result = cast_vector(f, &updated, lane.vector, "<16 x i8>");
350	            f.push(ValType::V128, &result)
351	        }
352	        _ => {
353	            let address = f.pop(ValType::I32)?;
354	            let ptr = emit_mem_pointer(f, &address, offset, width as u64);
355	            let result = match op {
356	                0x00 => {
357	                    let value = f.fresh(); f.line(&format!("{value} = load <16 x i8>, ptr {ptr}, align 1")); value
358	                }
359	                0x01..=0x06 => {
360	                    let (small, wide, sign) = match op {
361	                        0x01 | 0x02 => ("<8 x i8>", "<8 x i16>", op == 0x01),
362	                        0x03 | 0x04 => ("<4 x i16>", "<4 x i32>", op == 0x03),
363	                        _ => ("<2 x i32>", "<2 x i64>", op == 0x05),
364	                    };

