5	pub fn emit(module: &Module) -> Result<String, String> {
6	    let mut out = String::new();
7	    out.push_str("source_filename = \"wasm2llvm\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n\n");
8	    emit_declarations(&mut out, module);
9	    emit_globals(&mut out, module);
10	    emit_runtime(&mut out, module);
11	    for index in 0..module.functions.len() {
12	        if module.functions[index].import.is_some() {
13	            emit_import_wrapper(&mut out, module, index)?;
14	        } else {
15	            out.push_str(&crate::function::emit_function(module, index)?);
16	        }
17	        out.push('\n');
18	    }
19	    emit_init(&mut out, module);
20	    emit_exports(&mut out, module)?;
21	    Ok(out)
22	}
