24	fn emit_declarations(out: &mut String, module: &Module) {
25	    out.push_str("declare void @w2l_trap(i32) noreturn nounwind\n");
26	    out.push_str("declare ptr @calloc(i64, i64)\n");
27	    out.push_str("declare ptr @realloc(ptr, i64)\n");
28	    out.push_str("declare void @llvm.memcpy.p0.p0.i64(ptr, ptr, i64, i1)\n");
29	    out.push_str("declare void @llvm.memmove.p0.p0.i64(ptr, ptr, i64, i1)\n");
30	    out.push_str("declare void @llvm.memset.p0.i64(ptr, i8, i64, i1)\n");
31	    out.push_str("declare i32 @llvm.ctlz.i32(i32, i1 immarg)\n");
32	    out.push_str("declare i32 @llvm.cttz.i32(i32, i1 immarg)\n");
33	    out.push_str("declare i32 @llvm.ctpop.i32(i32)\n");
34	    out.push_str("declare i64 @llvm.ctlz.i64(i64, i1 immarg)\n");
35	    out.push_str("declare i64 @llvm.cttz.i64(i64, i1 immarg)\n");
36	    out.push_str("declare i64 @llvm.ctpop.i64(i64)\n");
37	    for (suffix, ty) in [("v16i8", "<16 x i8>"), ("v8i16", "<8 x i16>"), ("v4i32", "<4 x i32>"), ("v2i64", "<2 x i64>")] {
38	        let _ = writeln!(out, "declare {ty} @llvm.ctpop.{suffix}({ty})");
39	    }
40	    for ty in ["f32", "f64", "v4f32", "v2f64"] {
41	        let llty = match ty {
42	            "f32" => "float", "f64" => "double", "v4f32" => "<4 x float>", _ => "<2 x double>",
43	        };
44	        for op in ["ceil", "floor", "trunc", "roundeven", "sqrt"] {
45	            let _ = writeln!(out, "declare {llty} @llvm.{op}.{ty}({llty})");
46	        }
47	    }
48	    for (int_suffix, int_ty, float_suffix, float_ty) in [
49	        ("i32", "i32", "f32", "float"), ("i32", "i32", "f64", "double"),
50	        ("i64", "i64", "f32", "float"), ("i64", "i64", "f64", "double"),
51	        ("v4i32", "<4 x i32>", "v4f32", "<4 x float>"),
52	        ("v2i32", "<2 x i32>", "v2f64", "<2 x double>"),
53	    ] {
54	        let _ = writeln!(out, "declare {int_ty} @llvm.fptosi.sat.{int_suffix}.{float_suffix}({float_ty})");
55	        let _ = writeln!(out, "declare {int_ty} @llvm.fptoui.sat.{int_suffix}.{float_suffix}({float_ty})");
56	    }
57	    for (suffix, ty) in [("v16i8", "<16 x i8>"), ("v8i16", "<8 x i16>")] {
58	        for op in ["sadd.sat", "uadd.sat", "ssub.sat", "usub.sat"] {
59	            let _ = writeln!(out, "declare {ty} @llvm.{op}.{suffix}({ty}, {ty})");
60	        }
61	    }
62	    let mut imports = std::collections::BTreeSet::new();
63	    for f in &module.functions {
64	        if let Some((m, n)) = &f.import { imports.insert((hex(m.as_bytes()), hex(n.as_bytes()))); }
65	    }
66	    for (m, n) in imports {
67	        let _ = writeln!(out, "declare void @w2l_import_{m}_{n}(ptr, ptr)");
68	    }
69	    out.push('\n');
70	}
