72	fn emit_globals(out: &mut String, module: &Module) {
73	    out.push_str("@w2l_mem_base = internal global ptr null\n");
74	    out.push_str("@w2l_mem_size = internal global i64 0\n");
75	    let mem_max = module.memories.first().map(|m| m.limits.max.unwrap_or(65536)).unwrap_or(0);
76	    let _ = writeln!(out, "@w2l_mem_max_pages = internal constant i64 {mem_max}");
77	    out.push_str("@w2l_table_base = internal global ptr null\n");
78	    out.push_str("@w2l_table_size = internal global i32 0\n");
79	    let table_max = module.tables.first().map(|t| t.limits.max.unwrap_or(u32::MAX)).unwrap_or(0);
80	    let _ = writeln!(out, "@w2l_table_max = internal constant i64 {table_max}");
81	    out.push_str("@w2l_depth = internal global i32 0\n");
82	    for (index, g) in module.globals.iter().enumerate() {
83	        let _ = writeln!(out, "@w2l_g{index} = internal global {} {}", g.ty.llvm(), const_initializer(&g.init));
84	    }
85	    for (index, data) in module.data.iter().enumerate() {
86	        emit_byte_constant(out, &format!("w2l_data_{index}"), &data.bytes);
87	        let len = if matches!(data.mode, SegmentMode::Passive) { data.bytes.len() } else { 0 };
88	        let _ = writeln!(out, "@w2l_data_len_{index} = internal global i64 {len}");
89	    }
90	    for (index, elem) in module.elements.iter().enumerate() {
91	        if elem.functions.is_empty() {
92	            let _ = writeln!(out, "@w2l_elem_{index} = private constant [0 x i32] zeroinitializer");
93	        } else {
94	            let values = elem.functions.iter().map(|v| format!("i32 {}", i32_bits(*v))).collect::<Vec<_>>().join(", ");
95	            let _ = writeln!(out, "@w2l_elem_{index} = private constant [{} x i32] [{}]", elem.functions.len(), values);
96	        }
97	        let len = if matches!(elem.mode, SegmentMode::Passive) { elem.functions.len() } else { 0 };
98	        let _ = writeln!(out, "@w2l_elem_len_{index} = internal global i64 {len}");
99	    }
100	    out.push('\n');
101	}
