116	pub(crate) fn const_initializer(value: &ConstExpr) -> String {
117	    match value {
118	        ConstExpr::I32(v) => format!("i32 {v}"),
119	        ConstExpr::I64(v) => format!("i64 {v}"),
120	        ConstExpr::F32(bits) => format!("bitcast (i32 {} to float)", i32_bits(*bits)),
121	        ConstExpr::F64(bits) => format!("bitcast (i64 {} to double)", i64_bits(*bits)),
122	    }
123	}
