142	fn emit_runtime(out: &mut String, module: &Module) {
143	    out.push_str("define internal ptr @w2l_mem_ptr(i32 %addr, i32 %offset, i64 %length) {\nentry:\n");
144	    out.push_str("  %addr64 = zext i32 %addr to i64\n  %off64 = zext i32 %offset to i64\n  %start = add i64 %addr64, %off64\n  %end = add i64 %start, %length\n  %size = load i64, ptr @w2l_mem_size\n  %oob = icmp ugt i64 %end, %size\n  br i1 %oob, label %trap, label %ok\ntrap:\n  call void @w2l_trap(i32 4)\n  unreachable\nok:\n  %base = load ptr, ptr @w2l_mem_base\n  %ptr = getelementptr i8, ptr %base, i64 %start\n  ret ptr %ptr\n}\n\n");
145	    out.push_str("define internal i32 @w2l_memory_grow(i32 %delta) {\nentry:\n");
146	    out.push_str("  %old_size = load i64, ptr @w2l_mem_size\n  %old_pages = lshr i64 %old_size, 16\n  %zero = icmp eq i32 %delta, 0\n  br i1 %zero, label %same, label %grow\nsame:\n  %old_page_result = trunc i64 %old_pages to i32\n  ret i32 %old_page_result\ngrow:\n  %delta64 = zext i32 %delta to i64\n  %new_pages = add i64 %old_pages, %delta64\n  %max_pages = load i64, ptr @w2l_mem_max_pages\n  %too_many = icmp ugt i64 %new_pages, %max_pages\n  br i1 %too_many, label %fail, label %alloc\nalloc:\n  %new_size = shl i64 %new_pages, 16\n  %base = load ptr, ptr @w2l_mem_base\n  %new_base = call ptr @realloc(ptr %base, i64 %new_size)\n  %no_memory = icmp eq ptr %new_base, null\n  br i1 %no_memory, label %fail, label %zero_new\nzero_new:\n  %growth = sub i64 %new_size, %old_size\n  %zero_ptr = getelementptr i8, ptr %new_base, i64 %old_size\n  call void @llvm.memset.p0.i64(ptr %zero_ptr, i8 0, i64 %growth, i1 false)\n  store ptr %new_base, ptr @w2l_mem_base\n  store i64 %new_size, ptr @w2l_mem_size\n  %result = trunc i64 %old_pages to i32\n  ret i32 %result\nfail:\n  ret i32 -1\n}\n\n");
147	    out.push_str("define internal void @w2l_depth_enter() {\nentry:\n  %depth = load i32, ptr @w2l_depth\n  %next = add i32 %depth, 1\n  store i32 %next, ptr @w2l_depth\n  %too_deep = icmp ugt i32 %next, 16384\n  br i1 %too_deep, label %trap, label %ok\ntrap:\n  call void @w2l_trap(i32 8)\n  unreachable\nok:\n  ret void\n}\n\n");
148	    out.push_str("define internal void @w2l_depth_leave() {\nentry:\n  %depth = load i32, ptr @w2l_depth\n  %next = sub i32 %depth, 1\n  store i32 %next, ptr @w2l_depth\n  ret void\n}\n\n");
149	    let _ = module;
150	}
