1	use std::fmt;
2	
3	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
4	pub enum ValType {
5	    I32,
6	    I64,
7	    F32,
8	    F64,
9	    V128,
10	}
11	
12	impl ValType {
13	    pub fn llvm(self) -> &'static str {
14	        match self {
15	            Self::I32 => "i32",
16	            Self::I64 => "i64",
17	            Self::F32 => "float",
18	            Self::F64 => "double",
19	            Self::V128 => "<16 x i8>",
20	        }
21	    }
22	
23	    pub fn natural_align(self) -> usize {
24	        match self {
25	            Self::I32 | Self::F32 => 4,
26	            Self::I64 | Self::F64 => 8,
27	            Self::V128 => 16,
28	        }
29	    }
30	}
31	
32	impl fmt::Display for ValType {
33	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
34	        f.write_str(match self {
35	            Self::I32 => "i32",
36	            Self::I64 => "i64",
37	            Self::F32 => "f32",
38	            Self::F64 => "f64",
39	            Self::V128 => "v128",
40	        })
41	    }
42	}
43	
44	#[derive(Clone, Debug, PartialEq, Eq)]
45	pub struct FuncType {
46	    pub params: Vec<ValType>,
47	    pub results: Vec<ValType>,
48	}
49	
50	#[derive(Clone, Debug)]
51	pub enum ConstExpr {
52	    I32(i32),
53	    I64(i64),
54	    F32(u32),
55	    F64(u64),
56	}
57	
58	impl ConstExpr {
59	    pub fn ty(&self) -> ValType {
60	        match self {
61	            Self::I32(_) => ValType::I32,
62	            Self::I64(_) => ValType::I64,
63	            Self::F32(_) => ValType::F32,
64	            Self::F64(_) => ValType::F64,
65	        }
66	    }
67	}
68	
69	#[derive(Clone, Debug)]
70	pub enum BlockType {
71	    Empty,
72	    Value(ValType),
73	    TypeIndex(u32),
