use std::fmt;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ValType {
    I32,
    I64,
    F32,
    F64,
    V128,
}

impl ValType {
    pub fn llvm(self) -> &'static str {
        match self {
            Self::I32 => "i32",
            Self::I64 => "i64",
            Self::F32 => "float",
            Self::F64 => "double",
            Self::V128 => "<16 x i8>",
        }
    }

    pub fn natural_align(self) -> usize {
        match self {
            Self::I32 | Self::F32 => 4,
            Self::I64 | Self::F64 => 8,
            Self::V128 => 16,
        }
    }
}

impl fmt::Display for ValType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::I32 => "i32",
            Self::I64 => "i64",
            Self::F32 => "f32",
            Self::F64 => "f64",
            Self::V128 => "v128",
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FuncType {
    pub params: Vec<ValType>,
    pub results: Vec<ValType>,
}

#[derive(Clone, Debug)]
pub enum ConstExpr {
    I32(i32),
    I64(i64),
    F32(u32),
    F64(u64),
}

impl ConstExpr {
    pub fn ty(&self) -> ValType {
        match self {
            Self::I32(_) => ValType::I32,
            Self::I64(_) => ValType::I64,
            Self::F32(_) => ValType::F32,
            Self::F64(_) => ValType::F64,
        }
    }
}

#[derive(Clone, Debug)]
pub enum BlockType {
    Empty,
    Value(ValType),
    TypeIndex(u32),
}

#[derive(Clone, Debug)]
pub struct BlockSig {
    pub params: Vec<ValType>,
    pub results: Vec<ValType>,
}

#[derive(Clone, Debug)]
pub enum SimdImmediate {
    None,
    MemArg { align: u32, offset: u32 },
    Bytes([u8; 16]),
    Lane(u8),
    MemLane { align: u32, offset: u32, lane: u8 },
}

#[derive(Clone, Debug)]
pub enum BulkOp {
    MemoryInit { data: u32, memory: u32 },
    DataDrop { data: u32 },
    MemoryCopy { dst: u32, src: u32 },
    MemoryFill { memory: u32 },
    TableInit { element: u32, table: u32 },
    ElementDrop { element: u32 },
    TableCopy { dst: u32, src: u32 },
    TableGrow { table: u32 },
    TableSize { table: u32 },
    TableFill { table: u32 },
}

#[derive(Clone, Debug)]
pub enum Instr {
    Unreachable,
    Nop,
    Block(BlockSig, Vec<Instr>),
    Loop(BlockSig, Vec<Instr>),
    If(BlockSig, Vec<Instr>, Option<Vec<Instr>>),
    Br(u32),
    BrIf(u32),
    BrTable(Vec<u32>, u32),
    Return,
    Call(u32),
    CallIndirect { ty: u32, table: u32 },
    Drop,
    Select(Option<ValType>),
    LocalGet(u32),
    LocalSet(u32),
    LocalTee(u32),
    GlobalGet(u32),
    GlobalSet(u32),
    Load { op: u8, align: u32, offset: u32 },
    Store { op: u8, align: u32, offset: u32 },
    MemorySize(u32),
    MemoryGrow(u32),
    Const(ConstExpr),
    Numeric(u8),
    SignExtend(u8),
    Saturating(u32),
    Bulk(BulkOp),
    Simd { op: u32, immediate: SimdImmediate },
}

#[derive(Clone, Debug)]
pub struct Function {
    pub type_idx: u32,
    pub import: Option<(String, String)>,
    pub locals: Vec<ValType>,
    pub body: Vec<Instr>,
    pub max_stack: usize,
}

#[derive(Clone, Debug)]
pub struct Limits {
    pub min: u32,
    pub max: Option<u32>,
}

#[derive(Clone, Debug)]
pub struct Memory {
    pub limits: Limits,
}

#[derive(Clone, Debug)]
pub struct Table {
    pub limits: Limits,
}

#[derive(Clone, Debug)]
pub struct Global {
    pub ty: ValType,
    pub mutable: bool,
    pub init: ConstExpr,
}

#[derive(Clone, Debug)]
pub enum SegmentMode {
    Active { index: u32, offset: ConstExpr },
    Passive,
    Declared,
}

#[derive(Clone, Debug)]
pub struct DataSegment {
    pub mode: SegmentMode,
    pub bytes: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct ElementSegment {
    pub mode: SegmentMode,
    pub functions: Vec<u32>,
}

#[derive(Clone, Debug)]
pub enum ExportKind {
    Function(u32),
    Table(u32),
    Memory(u32),
    Global(u32),
}

#[derive(Clone, Debug)]
pub struct Export {
    pub name: String,
    pub kind: ExportKind,
}

#[derive(Clone, Debug, Default)]
pub struct Module {
    pub types: Vec<FuncType>,
    pub functions: Vec<Function>,
    pub imported_functions: usize,
    pub memories: Vec<Memory>,
    pub tables: Vec<Table>,
    pub globals: Vec<Global>,
    pub exports: Vec<Export>,
    pub start: Option<u32>,
    pub elements: Vec<ElementSegment>,
    pub data: Vec<DataSegment>,
    pub declared_data_count: Option<u32>,
}

pub fn parse(bytes: &[u8]) -> Result<Module, String> {
    if bytes.len() < 8 || &bytes[..4] != b"\0asm" {
        return Err("invalid WebAssembly magic".into());
    }
    if bytes[4..8] != [1, 0, 0, 0] {
        return Err("unsupported WebAssembly version".into());
    }

    let mut module = Module::default();
    let mut reader = Reader::new(&bytes[8..]);
    let mut last_rank = 0u8;
    let mut seen = [false; 13];
    let mut defined_type_indices = Vec::new();

    while !reader.eof() {
        let id = reader.byte()?;
        let size = reader.u32()? as usize;
        let mut section = reader.subreader(size)?;
        if id == 0 {
            let _ = section.name()?;
            continue;
        }
        if id > 12 || id == 0 {
            return Err(format!("unknown section id {id}"));

