3	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
4	enum ControlKind {
5	    Function,
6	    Block,
7	    Loop,
8	    If,
9	}
10	
11	struct ControlFrame {
12	    kind: ControlKind,
13	    height: usize,
14	    params: Vec<ValType>,
15	    results: Vec<ValType>,
16	    unreachable: bool,
17	}
18	
19	struct Validator<'a> {
20	    module: &'a Module,
21	    function_index: usize,
22	    locals: Vec<ValType>,
23	    stack: Vec<Option<ValType>>,
24	    controls: Vec<ControlFrame>,
25	    max_stack: usize,
26	}
27	
28	pub fn validate_module(module: &mut Module) -> Result<(), String> {
29	    for index in 0..module.functions.len() {
30	        let function = &module.functions[index];
31	        if function.import.is_some() {
32	            continue;
33	        }
34	        let type_idx = function.type_idx as usize;
35	        let function_body = function.body.clone();
36	        let mut locals = module.types.get(type_idx)
37	            .ok_or_else(|| format!("function {index} has an invalid type index"))?
38	            .params.clone();
39	        locals.extend_from_slice(&function.locals);
40	        let max_stack = {
41	            let ty = &module.types[type_idx];
42	            let mut validator = Validator {
43	                module,
44	                function_index: index,
45	                locals,
46	                stack: Vec::new(),
47	                controls: vec![ControlFrame {
48	                    kind: ControlKind::Function,
49	                    height: 0,
50	                    params: Vec::new(),
51	                    results: ty.results.clone(),
52	                    unreachable: false,
53	                }],
54	                max_stack: 0,
55	            };
56	            validator.validate_seq(&function_body)?;
57	            validator.finish_current()?;
58	            if validator.controls.len() != 1 || !validator.stack.is_empty() {
59	                return Err(validator.error("function body has an invalid final stack"));
60	            }
61	            validator.max_stack.max(1)
62	        };
63	        module.functions[index].max_stack = max_stack;
64	    }
65	
66	    if uses_memory_init_or_drop(module.functions.iter().filter(|f| f.import.is_none()).map(|f| &f.body))
67	        && module.declared_data_count.is_none()
68	    {
69	        return Err("memory.init/data.drop requires a data-count section".into());
70	    }
71	    if let Some(count) = module.declared_data_count {
72	        if count as usize != module.data.len() {
73	            return Err("data count does not match data section".into());
74	        }
75	    }
76	    validate_segments(module)?;
77	    Ok(())
78	}
79	
80	fn validate_segments(module: &Module) -> Result<(), String> {
81	    for (index, segment) in module.elements.iter().enumerate() {
82	        if let SegmentMode::Active { index: table, offset } = &segment.mode {
83	            if *table != 0 || module.tables.is_empty() {
84	                return Err(format!("element segment {index} uses an invalid table"));
85	            }
86	            if offset.ty() != ValType::I32 {
87	                return Err(format!("element segment {index} offset is not i32"));
88	            }
89	        }
90	        for &func in &segment.functions {
91	            if func as usize >= module.functions.len() {
92	                return Err(format!("element segment {index} function index is out of bounds"));
93	            }
94	        }
95	    }
96	    for (index, segment) in module.data.iter().enumerate() {
97	        if let SegmentMode::Active { index: memory, offset } = &segment.mode {
98	            if *memory != 0 || module.memories.is_empty() {
99	                return Err(format!("data segment {index} uses an invalid memory"));
100	            }
101	            if offset.ty() != ValType::I32 {
102	                return Err(format!("data segment {index} offset is not i32"));
103	            }
104	        }
105	    }
106	    Ok(())
107	}
108	
109	fn uses_memory_init_or_drop<'a>(mut bodies: impl Iterator<Item = &'a Vec<Instr>>) -> bool {
110	    fn in_seq(seq: &[Instr]) -> bool {
111	        seq.iter().any(|instr| match instr {
112	            Instr::Bulk(BulkOp::MemoryInit { .. } | BulkOp::DataDrop { .. }) => true,
113	            Instr::Block(_, body) | Instr::Loop(_, body) => in_seq(body),
114	            Instr::If(_, then_body, else_body) => in_seq(then_body) || else_body.as_deref().is_some_and(in_seq),
115	            _ => false,
116	        })
117	    }
118	    bodies.any(|body| in_seq(body))
119	}
120	
121	impl Validator<'_> {
122	    fn error(&self, message: impl AsRef<str>) -> String {
123	        format!("function {}: {}", self.function_index, message.as_ref())
124	    }
125	
126	    fn current(&self) -> &ControlFrame {
127	        self.controls.last().expect("function control frame")
128	    }
129	
130	    fn current_mut(&mut self) -> &mut ControlFrame {
131	        self.controls.last_mut().expect("function control frame")
132	    }
133	
134	    fn push(&mut self, ty: ValType) {
135	        self.stack.push(Some(ty));
136	        self.max_stack = self.max_stack.max(self.stack.len());
137	    }
138	
139	    fn pop_any(&mut self) -> Result<Option<ValType>, String> {
140	        let frame = self.current();
141	        if self.stack.len() == frame.height && frame.unreachable {
142	            return Ok(None);
143	        }
144	        self.stack.pop().ok_or_else(|| self.error("operand stack underflow"))
145	    }
146	
147	    fn pop_expect(&mut self, expected: ValType) -> Result<(), String> {
148	        if self.pop_any()?.is_some_and(|actual| actual != expected) {
149	            return Err(self.error(format!("type mismatch, expected {expected}")));
150	        }
151	        Ok(())
152	    }
153	
154	    fn pop_types(&mut self, types: &[ValType]) -> Result<(), String> {
155	        for &ty in types.iter().rev() {
156	            self.pop_expect(ty)?;
157	        }
158	        Ok(())
159	    }
160	
161	    fn make_unreachable(&mut self) {
162	        let height = self.current().height;
163	        self.stack.truncate(height);
164	        self.current_mut().unreachable = true;
165	    }
166	
167	    fn validate_seq(&mut self, seq: &[Instr]) -> Result<(), String> {
168	        for instruction in seq {
169	            self.validate_instr(instruction)?;
170	        }
171	        Ok(())
172	    }
173	
174	    fn validate_instr(&mut self, instr: &Instr) -> Result<(), String> {
175	        match instr {
176	            Instr::Unreachable => self.make_unreachable(),
177	            Instr::Nop => {}
178	            Instr::Block(sig, body) => self.validate_control(sig, ControlKind::Block, body, None)?,
179	            Instr::Loop(sig, body) => self.validate_control(sig, ControlKind::Loop, body, None)?,
180	            Instr::If(sig, then_body, else_body) => {
181	                self.pop_expect(ValType::I32)?;
182	                if else_body.is_none() && sig.params != sig.results {
183	                    return Err(self.error("if without else must have identical parameter and result types"));
184	                }
185	                self.validate_control(sig, ControlKind::If, then_body, else_body.as_deref())?;
186	            }
187	            Instr::Br(depth) => {
188	                let labels = self.label_types(*depth)?;
189	                self.pop_types(&labels)?;
190	                self.make_unreachable();
191	            }
192	            Instr::BrIf(depth) => {
193	                self.pop_expect(ValType::I32)?;
194	                let labels = self.label_types(*depth)?;
195	                self.pop_types(&labels)?;
196	                for ty in labels {
197	                    self.push(ty);
198	                }
199	            }
200	            Instr::BrTable(targets, default) => {
201	                self.pop_expect(ValType::I32)?;
202	                let expected = self.label_types(*default)?;
203	                for &depth in targets {
204	                    if self.label_types(depth)? != expected {
205	                        return Err(self.error("br_table target label types do not match"));
206	                    }
207	                }
208	                self.pop_types(&expected)?;
209	                self.make_unreachable();
210	            }
211	            Instr::Return => {
212	                let results = self.controls[0].results.clone();
213	                self.pop_types(&results)?;
214	                self.make_unreachable();
215	            }
216	            Instr::Call(index) => {
217	                let ty = self.function_type(*index)?.clone();
218	                self.pop_types(&ty.params)?;
219	                for result in ty.results {
220	                    self.push(result);
221	                }
222	            }
223	            Instr::CallIndirect { ty, table } => {
224	                if *table != 0 || self.module.tables.is_empty() {
225	                    return Err(self.error("call_indirect requires table 0"));
226	                }
227	                let ty = self.module.types.get(*ty as usize)
228	                    .ok_or_else(|| self.error("call_indirect type index is out of bounds"))?.clone();
229	                self.pop_expect(ValType::I32)?;
230	                self.pop_types(&ty.params)?;
231	                for result in ty.results {
232	                    self.push(result);
233	                }
234	            }
235	            Instr::Drop => { let _ = self.pop_any()?; }
236	            Instr::Select(ty) => {
237	                self.pop_expect(ValType::I32)?;
238	                let b = self.pop_any()?;
239	                let a = self.pop_any()?;
240	                if let (Some(a), Some(b)) = (a, b) {
241	                    if a != b {
242	                        return Err(self.error("select operands have different types"));
243	                    }
244	                }
245	                self.push(a.or(b).unwrap_or(ValType::I32));
246	                if ty.is_some() {
247	                    return Err(self.error("typed select is unsupported"));
248	                }
249	            }
250	            Instr::LocalGet(index) => self.push(self.local_type(*index)?),
251	            Instr::LocalSet(index) => {
252	                let ty = self.local_type(*index)?;
