271	                self.require_memory()?;
272	                self.pop_expect(ValType::I32)?;
273	                self.push(ty);
274	            }
275	            Instr::Store { op, align, .. } => {
276	                let (ty, width) = store_type(*op).ok_or_else(|| self.error("invalid store opcode"))?;
