301	                    0xc0 | 0xc1 => ValType::I32,
302	                    0xc2..=0xc4 => ValType::I64,
303	                    _ => return Err(self.error("invalid sign-extension opcode")),
304	                };
305	                self.pop_expect(ty)?;
306	                self.push(ty);
307	            }
308	            Instr::Saturating(op) => {
309	                let (input, output) = saturating_signature(*op).ok_or_else(|| self.error("invalid saturating conversion opcode"))?;
310	                self.pop_expect(input)?;
311	                self.push(output);
312	            }
313	            Instr::Bulk(op) => self.validate_bulk(op)?,
314	            Instr::Simd { op, immediate } => self.validate_simd(*op, immediate)?,
315	        }
316	        Ok(())
317	    }
318	
319	    fn validate_control(
320	        &mut self,
321	        sig: &BlockSig,
322	        kind: ControlKind,
323	        body: &[Instr],
324	        else_body: Option<&[Instr]>,
325	    ) -> Result<(), String> {
326	        self.pop_types(&sig.params)?;
327	        let height = self.stack.len();
328	        for &ty in &sig.params { self.push(ty); }
329	        self.controls.push(ControlFrame {
330	            kind,
331	            height,
332	            params: sig.params.clone(),
333	            results: sig.results.clone(),
334	            unreachable: false,
335	        });
336	        self.validate_seq(body)?;
337	        self.finish_current()?;
338	        if let Some(else_body) = else_body {
339	            let frame = self.controls.last_mut().expect("control frame");
340	            self.stack.truncate(frame.height);
341	            for &ty in &frame.params { self.stack.push(Some(ty)); }
342	            frame.unreachable = false;
343	            self.validate_seq(else_body)?;
344	            self.finish_current()?;
345	        }
346	        let frame = self.controls.pop().expect("control frame");
347	        for &ty in &frame.results { self.push(ty); }
348	        Ok(())
349	    }
350	
351	    fn finish_current(&mut self) -> Result<(), String> {
352	        let (height, results, kind) = {
353	            let frame = self.current();
354	            (frame.height, frame.results.clone(), frame.kind)
355	        };
356	        self.pop_types(&results)?;
357	        if self.stack.len() != height {
358	            return Err(self.error(match kind {
359	                ControlKind::Function => "function result stack has extra values",
360	                _ => "block result stack has extra values",
361	            }));
362	        }
363	        Ok(())
364	    }
365	
366	    fn label_types(&self, depth: u32) -> Result<Vec<ValType>, String> {
367	        let index = self.controls.len().checked_sub(depth as usize + 1)
368	            .ok_or_else(|| self.error("branch depth is out of bounds"))?;
369	        let frame = &self.controls[index];
370	        Ok(if frame.kind == ControlKind::Loop { frame.params.clone() } else { frame.results.clone() })
371	    }
372	
373	    fn function_type(&self, index: u32) -> Result<&FuncType, String> {
374	        let function = self.module.functions.get(index as usize)
375	            .ok_or_else(|| self.error("call function index is out of bounds"))?;
376	        self.module.types.get(function.type_idx as usize)
377	            .ok_or_else(|| self.error("function type index is out of bounds"))
378	    }
379	
380	    fn local_type(&self, index: u32) -> Result<ValType, String> {
381	        self.locals.get(index as usize).copied()
382	            .ok_or_else(|| self.error("local index is out of bounds"))
383	    }
384	
385	    fn global(&self, index: u32) -> Result<&crate::wasm::Global, String> {
386	        self.module.globals.get(index as usize)
387	            .ok_or_else(|| self.error("global index is out of bounds"))
388	    }
389	
390	    fn require_memory(&self) -> Result<(), String> {
391	        if self.module.memories.is_empty() { Err(self.error("memory instruction requires a memory")) } else { Ok(()) }
392	    }
393	
394	    fn validate_bulk(&mut self, op: &BulkOp) -> Result<(), String> {
395	        match op {
396	            BulkOp::MemoryInit { data, memory } => {
397	                if *memory != 0 || self.module.memories.is_empty() || *data as usize >= self.module.data.len() {
398	                    return Err(self.error("memory.init index is out of bounds"));
399	                }
400	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
401	            }
402	            BulkOp::DataDrop { data } => {
403	                if *data as usize >= self.module.data.len() { return Err(self.error("data.drop index is out of bounds")); }
404	            }
405	            BulkOp::MemoryCopy { dst, src } => {
406	                if *dst != 0 || *src != 0 || self.module.memories.is_empty() { return Err(self.error("memory.copy index is out of bounds")); }
407	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
408	            }
409	            BulkOp::MemoryFill { memory } => {
410	                if *memory != 0 || self.module.memories.is_empty() { return Err(self.error("memory.fill index is out of bounds")); }
411	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
412	            }
413	            BulkOp::TableInit { element, table } => {
414	                if *table != 0 || self.module.tables.is_empty() || *element as usize >= self.module.elements.len() {
415	                    return Err(self.error("table.init index is out of bounds"));
416	                }
417	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
418	            }
419	            BulkOp::ElementDrop { element } => {
420	                if *element as usize >= self.module.elements.len() { return Err(self.error("elem.drop index is out of bounds")); }
421	            }
422	            BulkOp::TableCopy { dst, src } => {
423	                if *dst != 0 || *src != 0 || self.module.tables.is_empty() { return Err(self.error("table.copy index is out of bounds")); }
424	                self.pop_types(&[ValType::I32, ValType::I32, ValType::I32])?;
425	            }
426	            BulkOp::TableGrow { .. } | BulkOp::TableFill { .. } => {
427	                return Err(self.error("table.grow/fill require reference types, which are outside the supported scope"));
428	            }
429	            BulkOp::TableSize { .. } => {
430	                return Err(self.error("table.size requires reference types, which are outside the supported scope"));
431	            }
432	        }
433	        Ok(())
434	    }
435	
436	    fn validate_simd(&mut self, op: u32, immediate: &crate::wasm::SimdImmediate) -> Result<(), String> {
437	        if let Some((align, width)) = crate::simd::memory_access(op, immediate) {
438	            check_align(align, width, self)?;
439	            self.require_memory()?;
440	            match op {
441	                0x0b => self.pop_expect(ValType::V128)?,
442	                0x58..=0x5b => self.pop_expect(ValType::V128)?,
443	                _ => {}
444	            }
445	            self.pop_expect(ValType::I32)?;
446	            if matches!(op, 0x00..=0x0a | 0x5c..=0x5d) { self.push(ValType::V128); }
447	            else if matches!(op, 0x54..=0x57) { self.pop_expect(ValType::V128)?; self.push(ValType::V128); }
448	            return Ok(());
449	        }
450	        let (inputs, output) = crate::simd::signature(op)
451	            .ok_or_else(|| self.error(format!("unsupported SIMD opcode 0x{op:x}")))?;
452	        if let crate::wasm::SimdImmediate::Lane(lane) = immediate {
453	            if *lane >= crate::simd::lane_count(op) {
454	                return Err(self.error("SIMD lane index is out of bounds"));
455	            }
456	        }
457	        if let crate::wasm::SimdImmediate::Bytes(bytes) = immediate {
458	            if op == 0x0d && bytes.iter().any(|&lane| lane >= 32) {
459	                return Err(self.error("i8x16.shuffle lane index is out of bounds"));
460	            }
461	        }
462	        self.pop_types(&inputs)?;
463	        if let Some(output) = output { self.push(output); }
464	        Ok(())
465	    }
466	}
467	
468	fn check_align(align: u32, width: u32, validator: &Validator<'_>) -> Result<(), String> {
469	    let maximum = width.trailing_zeros();
470	    if align > maximum {
471	        Err(validator.error("memory alignment is larger than the natural alignment"))
472	    } else {
473	        Ok(())
474	    }
475	}
476	
477	pub fn load_type(op: u8) -> Option<(ValType, u32)> {
478	    Some(match op {
479	        0x28 => (ValType::I32, 4),
480	        0x29 => (ValType::I64, 8),
481	        0x2a => (ValType::F32, 4),
482	        0x2b => (ValType::F64, 8),
483	        0x2c | 0x2d => (ValType::I32, 1),
484	        0x2e | 0x2f => (ValType::I32, 2),
485	        0x30 | 0x31 => (ValType::I64, 1),
486	        0x32 | 0x33 => (ValType::I64, 2),
487	        0x34 | 0x35 => (ValType::I64, 4),
488	        _ => return None,
489	    })
490	}
491	
492	pub fn store_type(op: u8) -> Option<(ValType, u32)> {
493	    Some(match op {
494	        0x36 => (ValType::I32, 4),
495	        0x37 => (ValType::I64, 8),
496	        0x38 => (ValType::F32, 4),
497	        0x39 => (ValType::F64, 8),
498	        0x3a => (ValType::I32, 1),
499	        0x3b => (ValType::I32, 2),
500	        0x3c => (ValType::I64, 1),
501	        0x3d => (ValType::I64, 2),
502	        0x3e => (ValType::I64, 4),
503	        _ => return None,
504	    })
505	}
506	
507	fn numeric_signature(op: u8) -> Option<(Vec<ValType>, Option<ValType>)> {
508	    use ValType::*;
509	    let unary = |input, output| Some((vec![input], Some(output)));
510	    let binary = |input, output| Some((vec![input, input], Some(output)));
511	    match op {
512	        0x45 => unary(I32, I32),
513	        0x46..=0x4f => Some((vec![I32, I32], Some(I32))),
514	        0x50 => unary(I64, I32),
515	        0x51..=0x5a => Some((vec![I64, I64], Some(I32))),
516	        0x5b..=0x60 => Some((vec![F32, F32], Some(I32))),
517	        0x61..=0x66 => Some((vec![F64, F64], Some(I32))),
518	        0x67..=0x69 => unary(I32, I32),
519	        0x6a..=0x78 => binary(I32, I32),
520	        0x79..=0x7b => unary(I64, I64),
521	        0x7c..=0x8a => binary(I64, I64),
522	        0x8b..=0x91 => unary(F32, F32),
523	        0x92..=0x98 => binary(F32, F32),
524	        0x99..=0x9f => unary(F64, F64),
525	        0xa0..=0xa6 => binary(F64, F64),
526	        0xa7 => unary(I64, I32),
527	        0xa8..=0xab => Some((vec![if op < 0xaa { F32 } else { F64 }], Some(I32))),
528	        0xac..=0xad => unary(I32, I64),
529	        0xae..=0xb1 => Some((vec![if op < 0xb0 { F32 } else { F64 }], Some(I64))),
530	        0xb2..=0xb5 => Some((vec![if op == 0xb2 || op == 0xb3 { I32 } else { I64 }], Some(F32))),
531	        0xb6 => unary(F64, F32),
532	        0xb7..=0xba => Some((vec![if op == 0xb7 || op == 0xb8 { I32 } else { I64 }], Some(F64))),
533	        0xbb => unary(F32, F64),
534	        0xbc => unary(I32, F32),
535	        0xbd => unary(I64, F64),
536	        0xbe => unary(F32, I32),
537	        0xbf => unary(F64, I64),
538	        _ => None,
539	    }
540	}
541	
542	fn saturating_signature(op: u32) -> Option<(ValType, ValType)> {
543	    use ValType::*;
544	    Some(match op {
545	        0 => (F32, I32), 1 => (F32, I32),
546	        2 => (F64, I32), 3 => (F64, I32),
547	        4 => (F32, I64), 5 => (F32, I64),
548	        6 => (F64, I64), 7 => (F64, I64),
549	        _ => return None,
550	    })
551	}
