30	    out.push_str("declare void @llvm.memset.p0.i64(ptr, i8, i64, i1)\n");
31	    out.push_str("declare i32 @llvm.ctlz.i32(i32, i1 immarg)\n");
32	    out.push_str("declare i32 @llvm.cttz.i32(i32, i1 immarg)\n");
33	    out.push_str("declare i32 @llvm.ctpop.i32(i32)\n");
