103	fn emit_byte_constant(out: &mut String, name: &str, bytes: &[u8]) {
104	    if bytes.is_empty() {
105	        let _ = writeln!(out, "@{name} = private constant [0 x i8] zeroinitializer, align 1");
106	        return;
107	    }
108	    let mut literal = String::with_capacity(bytes.len() * 3 + 2);
109	    literal.push('c');
110	    literal.push('"');
111	    for b in bytes { let _ = write!(literal, "\\{b:02X}"); }
112	    literal.push('"');
113	    let _ = writeln!(out, "@{name} = private unnamed_addr constant [{} x i8] {literal}, align 1", bytes.len());
114	}
