152	fn emit_import_wrapper(out: &mut String, module: &Module, index: usize) -> Result<(), String> {
153	    let function = &module.functions[index];
154	    let (import_module, import_name) = function.import.as_ref().ok_or("not an import")?;
155	    let ty = module.types.get(function.type_idx as usize).ok_or("invalid import function type")?;
156	    let args = ty.params.iter().enumerate().map(|(i,t)| format!("{} %p{i}", t.llvm())).collect::<Vec<_>>().join(", ");
157	    let ret = return_type(&ty.results);
158	    let _ = writeln!(out, "define internal {ret} @{}({args}) {{\nentry:", fn_name(index));
159	    out.push_str("  call void @w2l_depth_enter()\n");
160	    let arg_slots = ty.params.len().max(1);
161	    let result_slots = ty.results.len().max(1);
162	    let _ = writeln!(out, "  %args = alloca [{arg_slots} x <16 x i8>], align 16");
163	    let _ = writeln!(out, "  %results = alloca [{result_slots} x <16 x i8>], align 16");
164	    for (i, param) in ty.params.iter().enumerate() {
165	        let _ = writeln!(out, "  %arg_slot_{i} = getelementptr [{arg_slots} x <16 x i8>], ptr %args, i32 0, i32 {i}");
166	        let _ = writeln!(out, "  store {} %p{i}, ptr %arg_slot_{i}, align 1", param.llvm());
167	    }
168	    for i in 0..ty.results.len() {
169	        let _ = writeln!(out, "  %result_slot_init_{i} = getelementptr [{result_slots} x <16 x i8>], ptr %results, i32 0, i32 {i}");
170	        let _ = writeln!(out, "  store <16 x i8> zeroinitializer, ptr %result_slot_init_{i}, align 16");
171	    }
172	    let m = hex(import_module.as_bytes());
173	    let n = hex(import_name.as_bytes());
174	    let _ = writeln!(out, "  call void @w2l_import_{m}_{n}(ptr %args, ptr %results)");
175	    let mut values = Vec::new();
176	    for (i, result) in ty.results.iter().enumerate() {
177	        let _ = writeln!(out, "  %result_slot_{i} = getelementptr [{result_slots} x <16 x i8>], ptr %results, i32 0, i32 {i}");
178	        let _ = writeln!(out, "  %result_{i} = load {}, ptr %result_slot_{i}, align 1", result.llvm());
179	        values.push(format!("%result_{i}"));
180	    }
181	    out.push_str("  call void @w2l_depth_leave()\n");
182	    emit_return(out, &ty.results, &values);
183	    out.push_str("}\n");
184	    Ok(())
185	}
186	
187	pub(crate) fn emit_return(out: &mut String, results: &[ValType], values: &[String]) {
188	    match results.len() {
189	        0 => out.push_str("  ret void\n"),
190	        1 => { let _ = writeln!(out, "  ret {} {}", results[0].llvm(), values[0]); }
191	        n => {
192	            let ty = return_type(results);
193	            let mut current = "zeroinitializer".to_string();
194	            for (i, (result, value)) in results.iter().zip(values).enumerate() {
195	                let name = format!("%ret_agg_{i}");
196	                let _ = writeln!(out, "  {name} = insertvalue {ty} {current}, {} {value}, {i}", result.llvm());
197	                current = name;
198	            }
199	            let _ = writeln!(out, "  ret {ty} {current}");
200	        }
201	    }
202	}
203	
204	fn emit_init(out: &mut String, module: &Module) {
205	    out.push_str("define void @w2l_init() {\nentry:\n  store i32 0, ptr @w2l_depth\n");
206	    if let Some(memory) = module.memories.first() {
207	        let bytes = (memory.limits.min as u64) * 65536;
208	        if bytes != 0 {
209	            let _ = writeln!(out, "  %mem = call ptr @calloc(i64 1, i64 {bytes})\n  %mem_failed = icmp eq ptr %mem, null\n  br i1 %mem_failed, label %mem_trap, label %mem_ok\nmem_trap:\n  call void @w2l_trap(i32 4)\n  unreachable\nmem_ok:");
210	            out.push_str("  store ptr %mem, ptr @w2l_mem_base\n");
211	        }
212	        let _ = writeln!(out, "  store i64 {bytes}, ptr @w2l_mem_size");
213	    }
214	    if let Some(table) = module.tables.first() {
215	        let entries = table.limits.min as u64;
216	        let bytes = entries * 4;
217	        if bytes != 0 {
218	            let _ = writeln!(out, "  %table = call ptr @calloc(i64 1, i64 {bytes})\n  %table_failed = icmp eq ptr %table, null\n  br i1 %table_failed, label %table_trap, label %table_ok\ntable_trap:\n  call void @w2l_trap(i32 5)\n  unreachable\ntable_ok:");
219	            out.push_str("  store ptr %table, ptr @w2l_table_base\n");
220	            let _ = writeln!(out, "  call void @llvm.memset.p0.i64(ptr %table, i8 -1, i64 {bytes}, i1 false)");
221	        }
222	        let _ = writeln!(out, "  store i32 {}, ptr @w2l_table_size", i32_bits(table.limits.min));
223	    }
224	    for (index, global) in module.globals.iter().enumerate() {
225	        match global.init {
226	            ConstExpr::I32(value) => { let _ = writeln!(out, "  store i32 {value}, ptr @w2l_g{index}"); }
227	            ConstExpr::I64(value) => { let _ = writeln!(out, "  store i64 {value}, ptr @w2l_g{index}"); }
228	            ConstExpr::F32(bits) => {
229	                let _ = writeln!(out, "  %global_init_{index} = bitcast i32 {} to float\n  store float %global_init_{index}, ptr @w2l_g{index}", i32_bits(bits));
230	            }
231	            ConstExpr::F64(bits) => {
232	                let _ = writeln!(out, "  %global_init_{index} = bitcast i64 {} to double\n  store double %global_init_{index}, ptr @w2l_g{index}", i64_bits(bits));
233	            }
234	        }
235	    }
236	    for (index, data) in module.data.iter().enumerate() {
237	        if let SegmentMode::Active { offset, .. } = &data.mode {
238	            if let ConstExpr::I32(offset) = offset {
239	                let _ = writeln!(out, "  %data_dst_{index} = call ptr @w2l_mem_ptr(i32 {offset}, i32 0, i64 {})", data.bytes.len());
240	                if !data.bytes.is_empty() {
241	                    let _ = writeln!(out, "  call void @llvm.memcpy.p0.p0.i64(ptr %data_dst_{index}, ptr @w2l_data_{index}, i64 {}, i1 false)", data.bytes.len());
242	                }
243	            }
244	        }
245	    }
246	    for (index, elem) in module.elements.iter().enumerate() {
247	        if let SegmentMode::Active { offset, .. } = &elem.mode {
248	            if let ConstExpr::I32(offset) = offset {
249	                emit_active_element_init(out, index, *offset, elem.functions.len());
250	                for (slot, func) in elem.functions.iter().enumerate() {
251	                    let _ = writeln!(out, "  %elem_dst_{index}_{slot} = getelementptr i32, ptr %elem_base_{index}, i64 %elem_index_{index}_{slot}\n  store i32 {}, ptr %elem_dst_{index}_{slot}, align 4", i32_bits(*func));
252	                }
253	            }
254	        }
255	    }
256	    if let Some(start) = module.start {
257	        let _ = writeln!(out, "  call void @{}()", fn_name(start as usize));
258	    }
259	    out.push_str("  ret void\n}\n\n");
260	}

