251	            Instr::LocalSet(index) => {
252	                let ty = self.local_type(*index)?;
253	                self.pop_expect(ty)?;
254	            }
255	            Instr::LocalTee(index) => {
256	                let ty = self.local_type(*index)?;
257	                self.pop_expect(ty)?;
258	                self.push(ty);
259	            }
260	            Instr::GlobalGet(index) => self.push(self.global(*index)?.ty),
261	            Instr::GlobalSet(index) => {
262	                let global = self.global(*index)?;
263	                if !global.mutable {
264	                    return Err(self.error("global.set targets an immutable global"));
265	                }
266	                self.pop_expect(global.ty)?;
