320	        &mut self,
321	        sig: &BlockSig,
322	        kind: ControlKind,
323	        body: &[Instr],
324	        else_body: Option<&[Instr]>,
325	    ) -> Result<(), String> {
326	        self.pop_types(&sig.params)?;
