436	    fn validate_simd(&mut self, op: u32, immediate: &crate::wasm::SimdImmediate) -> Result<(), String> {
437	        if let Some((align, width)) = crate::simd::memory_access(op, immediate) {
438	            check_align(align, width, self)?;
439	            self.require_memory()?;
440	            match op {
441	                0x0b => self.pop_expect(ValType::V128)?,
442	                0x58..=0x5b => self.pop_expect(ValType::V128)?,
443	                _ => {}
444	            }
445	            self.pop_expect(ValType::I32)?;
446	            if matches!(op, 0x00..=0x0a | 0x5c..=0x5d) { self.push(ValType::V128); }
447	            else if matches!(op, 0x54..=0x57) { self.pop_expect(ValType::V128)?; self.push(ValType::V128); }
448	            return Ok(());
449	        }
450	        let (inputs, output) = crate::simd::signature(op)
451	            .ok_or_else(|| self.error(format!("unsupported SIMD opcode 0x{op:x}")))?;
452	        if let crate::wasm::SimdImmediate::Lane(lane) = immediate {
453	            if *lane >= crate::simd::lane_count(op) {
454	                return Err(self.error("SIMD lane index is out of bounds"));
455	            }
456	        }
457	        if let crate::wasm::SimdImmediate::Bytes(bytes) = immediate {
458	            if op == 0x0d && bytes.iter().any(|&lane| lane >= 32) {
459	                return Err(self.error("i8x16.shuffle lane index is out of bounds"));
460	            }
461	        }
462	        self.pop_types(&inputs)?;
463	        if let Some(output) = output { self.push(output); }
464	        Ok(())
465	    }
