def global_i32(name):
    result = ctypes.create_string_buffer(16)
    function = getattr(module, "w2l_global_" + export_name(name))
    function.argtypes = (ctypes.c_void_p,)
    function.restype = None
    function(ctypes.addressof(result))
    return struct.unpack_from("<i", result.raw)[0]

def memory_info():
    size = ctypes.c_uint64()
    function = getattr(module, "w2l_memory_" + MEMORY_HEX)
    function.argtypes = (ctypes.POINTER(ctypes.c_uint64),)
    function.restype = ctypes.c_void_p
    base = function(ctypes.byref(size))
    return int(base), size.value

base, memory_size = memory_info()
reference = subprocess.Popen(["w2l-ref"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1)

def ref(command):
    reference.stdin.write(command + "\n")
    reference.stdin.flush()
    reply = reference.stdout.readline()
    if not reply:
        raise SystemExit("w2l-ref exited without a reply")
    reply = reply.rstrip("\n")
    if reply.startswith("error ") or reply.startswith("trap "):
        raise SystemExit(f"reference {command!r}: {reply}")
    return reply

def ref_invoke(name, values=(), result_count=0):
    fields = ["invoke", "a", export_name(name), str(result_count)]
    fields.extend(slot_i32(value) for value in values)
    reply = ref(" ".join(fields))
    if reply == "ok":
        return []
    if not reply.startswith("ok "):
        raise SystemExit(f"unexpected reference reply: {reply}")
    slots = reply[3:].split()
    return [struct.unpack("<i", bytes.fromhex(slot[:8]))[0] for slot in slots]

def write_memory(offset, data):
    if offset < 0 or offset + len(data) > memory_size:
        raise SystemExit("generated memory write is out of bounds")
    ctypes.memmove(base + offset, data, len(data))
    reply = ref(f"memwrite a {MEMORY_HEX} {offset} {data.hex()}")
    if reply != "ok":
        raise SystemExit(f"unexpected memwrite reply: {reply}")

def read_memory(offset, length):
    actual = ctypes.string_at(base + offset, length)
    reply = ref(f"memread a {MEMORY_HEX} {offset} {length}")
    if not reply.startswith("ok "):
        raise SystemExit(f"unexpected memread reply: {reply}")
    expected = bytes.fromhex(reply[3:])
    if actual != expected:
        mismatch = next((i for i, (a, b) in enumerate(zip(actual, expected)) if a != b), min(len(actual), len(expected)))
        raise SystemExit(f"memory mismatch at offset {offset + mismatch}: generated={actual[mismatch:mismatch+16].hex()} reference={expected[mismatch:mismatch+16].hex()}")

def check_equal(label, actual, expected):
    if actual != expected:
        raise SystemExit(f"{label}: generated {actual}, reference {expected}")

def start_reference():
    ref(f"load a {os.path.abspath(wasm_path)}")
    check_equal("reference init", ref("init a"), "ok")

def audio_run(init_name, init_values, input_ptr_name, output_ptr_name, encode_name, sample_count, sample_format):
    generated_init = invoke(init_name, init_values, 1)
    reference_init = ref_invoke(init_name, init_values, 1)
    check_equal(init_name, generated_init, reference_init)
    input_ptr = invoke(input_ptr_name, (), 1)[0]
    output_ptr = invoke(output_ptr_name, (), 1)[0]
    if sample_format == "i16":
        samples = [((index * 197 + index * index * 3) % 24001) - 12000 for index in range(sample_count)]
        data = b"".join(struct.pack("<h", value) for value in samples)
        encode = encode_name + "_i16"
    else:
        samples = [((index % 101) - 50) / 100.0 for index in range(sample_count)]
        data = b"".join(struct.pack("<f", value) for value in samples)
        encode = encode_name
    write_memory(input_ptr, data)
    generated_length = invoke(encode, (), 1)[0]
    reference_length = ref_invoke(encode, (), 1)[0]
    check_equal(encode, generated_length, reference_length)
    if generated_length > 0:
        read_memory(output_ptr, generated_length)
    return generated_length

