14	        0x62 => emit_popcnt(f),
15	        0x63 | 0x83 | 0xa3 | 0xc3 => emit_all_true(f, op),
16	        0x64 | 0x84 | 0xa4 | 0xc4 => emit_bitmask(f, op),
17	        0x65 | 0x66 | 0x85 | 0x86 => emit_narrow(f, op),
18	        0x67..=0x6a | 0x74..=0x75 | 0x7a | 0x94 => emit_float_round(f, op),
19	        0x6b..=0x6d | 0x8b..=0x8d | 0xab..=0xad | 0xcb..=0xcd => emit_shift(f, op),
20	        0x6f | 0x70 | 0x72 | 0x73 | 0x8f | 0x90 | 0x92 | 0x93 => emit_saturating_add_sub(f, op),
21	        0x82 => emit_q15mulr(f),
22	        0x7b | 0x9b => emit_average(f, op),
23	        0x7c..=0x7f => emit_pairwise_add(f, op),
24	        0x87..=0x8a | 0xa7..=0xaa | 0xc7..=0xca => emit_extend(f, op),
25	        0x9c..=0x9f | 0xbc..=0xbf | 0xdc..=0xdf => emit_extmul(f, op),
26	        0xba => emit_dot(f),
27	        0xd6..=0xdb => emit_i64_compare(f, op),
28	        0x76..=0x79 | 0x96..=0x99 | 0xb6..=0xb9 => emit_int_minmax(f, op),
29	        0xe8..=0xeb | 0xf4..=0xf7 => emit_float_minmax(f, op),
30	        0xe0 | 0xe1 | 0xec | 0xed => emit_float_abs_neg(f, op),
31	        0xe3 | 0xef => emit_float_round(f, op),
32	        0xe4..=0xe7 | 0xf0..=0xf3 => emit_float_binary(f, op),
33	        0x6e | 0x71 | 0x8e | 0x91 | 0x95 | 0xae | 0xb1 | 0xb5 | 0xce | 0xd1 | 0xd5 => emit_int_binary(f, op),
34	        _ => Err(format!("unsupported SIMD arithmetic opcode 0x{op:x}")),
35	    }
36	}
