38	fn lane_kind(op: u32) -> &'static str {
39	    match op {
40	        0x67..=0x6a | 0xe0..=0xeb => "f32",
41	        0x74..=0x75 | 0x7a | 0x94 | 0xec..=0xf7 => "f64",
42	        0x60..=0x7d => "i8",
43	        0x7e..=0x9f => "i16",
44	        0xa0..=0xbf => "i32",
45	        0xc0..=0xdf => "i64",
46	        _ => unreachable!(),
47	    }
48	}
