68	fn emit_int_abs_neg(f: &mut FunctionEmitter<'_>, op: u32, lane: LaneInfo) -> Result<(), String> {
69	    let args = vector_args(f, 1)?;
70	    let value = as_lane(f, &args[0], lane);
71	    let result = f.fresh();
72	    if op & 1 == 1 {
73	        f.line(&format!("{result} = sub {} zeroinitializer, {value}", lane.vector));
74	    } else {
75	        let negative = f.fresh();
76	        f.line(&format!("{negative} = icmp slt {} {value}, zeroinitializer", lane.vector));
77	        let negated = f.fresh();
78	        f.line(&format!("{negated} = sub {} zeroinitializer, {value}", lane.vector));
79	        f.line(&format!("{result} = select <{} x i1> {negative}, {} {negated}, {} {value}", lane.lanes, lane.vector, lane.vector));
80	    }
81	    push_lane(f, &result, lane)
82	}
