97	fn emit_all_true(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
98	    let args = vector_args(f, 1)?;
99	    let lane = reduction_lane(op);
100	    let value = as_lane(f, &args[0], lane);
101	    let nonzero = f.fresh();
102	    f.line(&format!("{nonzero} = icmp ne {} {value}, zeroinitializer", lane.vector));
103	    let mut combined = "true".to_string();
104	    for index in 0..lane.lanes {
105	        let part = f.fresh();
106	        f.line(&format!("{part} = extractelement <{} x i1> {nonzero}, i32 {index}", lane.lanes));
107	        let next = f.fresh();
108	        f.line(&format!("{next} = and i1 {combined}, {part}"));
109	        combined = next;
110	    }
111	    let result = f.fresh();
112	    f.line(&format!("{result} = zext i1 {combined} to i32"));
113	    f.push(ValType::I32, &result)
114	}
