116	fn emit_bitmask(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
117	    let args = vector_args(f, 1)?;
118	    let lane = reduction_lane(op);
119	    let value = as_lane(f, &args[0], lane);
120	    let negative = f.fresh();
121	    f.line(&format!("{negative} = icmp slt {} {value}, zeroinitializer", lane.vector));
122	    let mut combined = "0".to_string();
123	    for index in 0..lane.lanes {
124	        let bit = f.fresh();
125	        f.line(&format!("{bit} = extractelement <{} x i1> {negative}, i32 {index}", lane.lanes));
126	        let extended = f.fresh();
127	        f.line(&format!("{extended} = zext i1 {bit} to i32"));
128	        let shifted = if index == 0 { extended } else {
129	            let value = f.fresh();
130	            f.line(&format!("{value} = shl i32 {extended}, {index}"));
131	            value
132	        };
133	        let next = f.fresh();
134	        f.line(&format!("{next} = or i32 {combined}, {shifted}"));
135	        combined = next;
136	    }
137	    f.push(ValType::I32, &combined)
138	}
