141	    let source = if op == 0x65 || op == 0x66 { lane_info("i16") } else { lane_info("i32") };
142	    let dest = if source.bits == 16 { lane_info("i8") } else { lane_info("i16") };
143	    let intermediate = format!("<{} x {}>", source.lanes, dest.scalar);
144	    let args = vector_args(f, 2)?;
145	    let mut narrowed = Vec::new();
146	    for arg in args {
147	        let value = as_lane(f, &arg, source);
148	        let is_signed = op == 0x65 || op == 0x85;
149	        let minimum = if is_signed { -(1i64 << (dest.bits - 1)) } else { 0 };
150	        let maximum = if is_signed { (1i64 << (dest.bits - 1)) - 1 } else { (1i64 << dest.bits) - 1 };

185	    };
186	    let result = f.fresh();
187	    f.line(&format!("{result} = {instruction} {} {value}, {splat}", lane.vector));
188	    push_lane(f, &result, lane)
189	}
