191	fn emit_saturating_add_sub(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
192	    let lane = lane_info(lane_kind(op));
193	    let args = vector_args(f, 2)?;
194	    let a = as_lane(f, &args[0], lane);
195	    let b = as_lane(f, &args[1], lane);
196	    let name = match op {
197	        0x6f | 0x8f => "sadd.sat", 0x70 | 0x90 => "uadd.sat",
198	        0x72 | 0x92 => "ssub.sat", _ => "usub.sat",
199	    };
200	    let suffix = if lane.bits == 8 { "v16i8" } else { "v8i16" };
201	    let result = f.fresh();
202	    f.line(&format!("{result} = call {} @llvm.{name}.{suffix}({} {a}, {} {b})", lane.vector, lane.vector, lane.vector));
203	    push_lane(f, &result, lane)
204	}
