209	    let a = as_lane(f, &args[0], lane);
210	    let b = as_lane(f, &args[1], lane);
211	    let instruction = match op {
212	        0x6e | 0x8e | 0xae | 0xce => "add",
213	        0x71 | 0x91 | 0xb1 | 0xd1 => "sub",
214	        _ => "mul",
215	    };
216	    let result = f.fresh();
217	    f.line(&format!("{result} = {instruction} {} {a}, {b}", lane.vector));
218	    push_lane(f, &result, lane)
