221	fn emit_int_minmax(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
222	    let lane = lane_info(lane_kind(op));
223	    let args = vector_args(f, 2)?;
224	    let a = as_lane(f, &args[0], lane);
225	    let b = as_lane(f, &args[1], lane);
226	    let (predicate, choose_a) = match op {
227	        0x76 => ("slt", true), 0x77 => ("ult", true), 0x78 => ("sgt", true), 0x79 => ("ugt", true),
228	        0x96 => ("slt", true), 0x97 => ("ult", true), 0x98 => ("sgt", true), 0x99 => ("ugt", true),
229	        0xb6 => ("slt", true), 0xb7 => ("ult", true), 0xb8 => ("sgt", true), _ => ("ugt", true),
230	    };
231	    let cmp = f.fresh();
232	    f.line(&format!("{cmp} = icmp {predicate} {} {a}, {b}", lane.vector));
233	    let result = f.fresh();
234	    f.line(&format!("{result} = select <{} x i1> {cmp}, {} {}, {} {}", lane.lanes, lane.vector, if choose_a { &a } else { &b }, lane.vector, if choose_a { &b } else { &a }));
235	    push_lane(f, &result, lane)
236	}
