238	fn emit_float_round(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
239	    let kind = lane_kind(op);
240	    let lane = lane_info(kind);
241	    let args = vector_args(f, 1)?;
242	    let value = as_lane(f, &args[0], lane);
243	    let intrinsic = match op {
244	        0x67 | 0x74 => "ceil", 0x68 | 0x75 => "floor", 0x69 | 0x7a => "trunc",
245	        0x6a | 0x94 => "roundeven", 0xe3 | 0xef => "sqrt", _ => return Err("invalid vector float unary opcode".into()),
246	    };
247	    let suffix = if kind == "f32" { "v4f32" } else { "v2f64" };
248	    let result = f.fresh();
249	    f.line(&format!("{result} = call {} @llvm.{intrinsic}.{suffix}({} {value})", lane.vector, lane.vector));
250	    push_lane(f, &result, lane)
251	}
