253	fn emit_float_abs_neg(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
254	    let lane = lane_info(if op < 0xec { "f32" } else { "f64" });
255	    let args = vector_args(f, 1)?;
256	    let integer = lane_info(if lane.bits == 32 { "i32" } else { "i64" });
257	    let bits = as_lane(f, &args[0], integer);
258	    let result_bits = f.fresh();
259	    if op == 0xe0 || op == 0xec {
260	        let mask = if lane.bits == 32 { i32::MAX as i64 } else { i64::MAX };
261	        f.line(&format!("{result_bits} = and {} {bits}, {}", integer.vector, splat_constant(integer, mask)));
262	    } else {
263	        let sign = if lane.bits == 32 { i32::MIN as i64 } else { i64::MIN };
264	        f.line(&format!("{result_bits} = xor {} {bits}, {}", integer.vector, splat_constant(integer, sign)));
265	    }
266	    let result = cast_vector(f, &result_bits, integer.vector, lane.vector);
267	    push_lane(f, &result, lane)
268	}
