270	fn emit_float_binary(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
271	    let lane = lane_info(if op < 0xec { "f32" } else { "f64" });
272	    let args = vector_args(f, 2)?;
273	    let a = as_lane(f, &args[0], lane);
274	    let b = as_lane(f, &args[1], lane);
275	    let instruction = match op {
276	        0xe4 | 0xf0 => "fadd", 0xe5 | 0xf1 => "fsub", 0xe6 | 0xf2 => "fmul", _ => "fdiv",
277	    };
278	    let result = f.fresh();
279	    f.line(&format!("{result} = {instruction} {} {a}, {b}", lane.vector));
280	    push_lane(f, &result, lane)
281	}
