283	fn emit_float_minmax(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
284	    let lane = lane_info(if op < 0xec { "f32" } else { "f64" });
285	    let args = vector_args(f, 2)?;
286	    let a = as_lane(f, &args[0], lane);
287	    let b = as_lane(f, &args[1], lane);
288	    let pseudo = op == 0xea || op == 0xeb || op == 0xf6 || op == 0xf7;
289	    let maximum = op == 0xe9 || op == 0xeb || op == 0xf5 || op == 0xf7;
290	    if pseudo {
291	        let cmp = f.fresh();
292	        f.line(&format!("{cmp} = fcmp {} {} {a}, {b}", if maximum { "ogt" } else { "olt" }, lane.vector));
293	        let result = f.fresh();
294	        f.line(&format!("{result} = select <{} x i1> {cmp}, {} {a}, {} {b}", lane.lanes, lane.vector, lane.vector));
295	        return push_lane(f, &result, lane);
296	    }
297	    let int_lane = lane_info(if lane.bits == 32 { "i32" } else { "i64" });
298	    let a_nan = f.fresh();
299	    let b_nan = f.fresh();
300	    f.line(&format!("{a_nan} = fcmp uno {} {a}, {a}", lane.vector));
301	    f.line(&format!("{b_nan} = fcmp uno {} {b}, {b}", lane.vector));
302	    let any_nan = f.fresh();
303	    f.line(&format!("{any_nan} = or <{} x i1> {a_nan}, {b_nan}", lane.lanes));
304	    let cmp = f.fresh();
305	    f.line(&format!("{cmp} = fcmp {} {} {a}, {b}", if maximum { "ogt" } else { "olt" }, lane.vector));
306	    let ordered = f.fresh();
307	    f.line(&format!("{ordered} = select <{} x i1> {cmp}, {} {a}, {} {b}", lane.lanes, lane.vector, lane.vector));
308	    let a_zero = f.fresh();
309	    let b_zero = f.fresh();
310	    f.line(&format!("{a_zero} = fcmp oeq {} {a}, zeroinitializer", lane.vector));
311	    f.line(&format!("{b_zero} = fcmp oeq {} {b}, zeroinitializer", lane.vector));
312	    let both_zero = f.fresh();
313	    f.line(&format!("{both_zero} = and <{} x i1> {a_zero}, {b_zero}", lane.lanes));
314	    let a_bits = as_lane(f, &args[0], int_lane);
315	    let b_bits = as_lane(f, &args[1], int_lane);
316	    let sign_mask = if lane.bits == 32 { i32::MIN as i64 } else { i64::MIN };
317	    let a_sign = f.fresh();
318	    let b_sign = f.fresh();
319	    f.line(&format!("{a_sign} = and {} {a_bits}, {}", int_lane.vector, splat_constant(int_lane, sign_mask)));
320	    f.line(&format!("{b_sign} = and {} {b_bits}, {}", int_lane.vector, splat_constant(int_lane, sign_mask)));
321	    let zero_sign = f.fresh();
322	    f.line(&format!("{zero_sign} = {} {} {a_sign}, {b_sign}", if maximum { "and" } else { "or" }, int_lane.vector));
323	    let zero = cast_vector(f, &zero_sign, int_lane.vector, lane.vector);
324	    let with_zero = f.fresh();
325	    f.line(&format!("{with_zero} = select <{} x i1> {both_zero}, {} {zero}, {} {ordered}", lane.lanes, lane.vector, lane.vector));
326	    let nan_bits_value = if lane.bits == 32 { 0x7fc0_0000i64 } else { 0x7ff8_0000_0000_0000i64 };
327	    let nan_bits = splat_vector(f, int_lane, &nan_bits_value.to_string(), int_lane.scalar);
328	    let nan = cast_vector(f, &nan_bits, int_lane.vector, lane.vector);
329	    let result = f.fresh();
330	    f.line(&format!("{result} = select <{} x i1> {any_nan}, {} {nan}, {} {with_zero}", lane.lanes, lane.vector, lane.vector));
331	    push_lane(f, &result, lane)
332	}
