334	fn emit_average(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
335	    let lane = lane_info(if op == 0x7b { "i8" } else { "i16" });
336	    let wide = lane_info(if lane.bits == 8 { "i16" } else { "i32" });
337	    let args = vector_args(f, 2)?;
338	    let a = as_lane(f, &args[0], lane);
339	    let b = as_lane(f, &args[1], lane);
340	    let aw = f.fresh();
341	    let bw = f.fresh();
342	    f.line(&format!("{aw} = zext {} {a} to {}", lane.vector, wide.vector));
343	    f.line(&format!("{bw} = zext {} {b} to {}", lane.vector, wide.vector));
344	    let sum = f.fresh();
345	    f.line(&format!("{sum} = add {} {aw}, {bw}", wide.vector));
346	    let plus = f.fresh();
347	    f.line(&format!("{plus} = add {} {sum}, {}", wide.vector, splat_constant(wide, 1)));
348	    let avg = f.fresh();
349	    f.line(&format!("{avg} = lshr {} {plus}, {}", wide.vector, splat_constant(wide, 1)));
350	    let result = f.fresh();
351	    f.line(&format!("{result} = trunc {} {avg} to {}", wide.vector, lane.vector));
352	    push_lane(f, &result, lane)
353	}
