355	fn emit_q15mulr(f: &mut FunctionEmitter<'_>) -> Result<(), String> {
356	    let lane = lane_info("i16");
357	    let wide = lane_info("i32");
358	    let args = vector_args(f, 2)?;
359	    let a = as_lane(f, &args[0], lane);
360	    let b = as_lane(f, &args[1], lane);
361	    let aw = f.fresh();
362	    let bw = f.fresh();
363	    f.line(&format!("{aw} = sext <8 x i16> {a} to <8 x i32>"));
364	    f.line(&format!("{bw} = sext <8 x i16> {b} to <8 x i32>"));

360	    let b = as_lane(f, &args[1], lane);
361	    let aw = f.fresh();
362	    let bw = f.fresh();
363	    f.line(&format!("{aw} = sext <8 x i16> {a} to <8 x i32>"));
364	    f.line(&format!("{bw} = sext <8 x i16> {b} to <8 x i32>"));
365	    let product = f.fresh();
366	    f.line(&format!("{product} = mul <8 x i32> {aw}, {bw}"));
367	    let rounded = f.fresh();
368	    f.line(&format!("{rounded} = add <8 x i32> {product}, {}", splat_constant(wide, 16384)));
369	    let shifted = f.fresh();
370	    f.line(&format!("{shifted} = ashr <8 x i32> {rounded}, {}", splat_constant(wide, 15)));
371	    let minimum = splat_constant(wide, -32768);
372	    let maximum = splat_constant(wide, 32767);
373	    let below = f.fresh();
374	    f.line(&format!("{below} = icmp slt <8 x i32> {shifted}, {minimum}"));
375	    let low = f.fresh();
376	    f.line(&format!("{low} = select <8 x i1> {below}, <8 x i32> {minimum}, <8 x i32> {shifted}"));
377	    let above = f.fresh();
378	    f.line(&format!("{above} = icmp sgt <8 x i32> {low}, {maximum}"));
379	    let clamped = f.fresh();
380	    f.line(&format!("{clamped} = select <8 x i1> {above}, <8 x i32> {maximum}, <8 x i32> {low}"));
381	    let result = f.fresh();
382	    f.line(&format!("{result} = trunc <8 x i32> {clamped} to <8 x i16>"));
383	    let _ = wide;
384	    push_lane(f, &result, lane)
385	}
