387	fn emit_pairwise_add(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
388	    let (source, dest, signed) = match op {
389	        0x7c => (lane_info("i8"), lane_info("i16"), true),
390	        0x7d => (lane_info("i8"), lane_info("i16"), false),
391	        0x7e => (lane_info("i16"), lane_info("i32"), true),
392	        _ => (lane_info("i16"), lane_info("i32"), false),
393	    };
394	    let args = vector_args(f, 1)?;
395	    let value = as_lane(f, &args[0], source);
396	    let even_mask = (0..dest.lanes).map(|i| format!("i32 {}", i * 2)).collect::<Vec<_>>().join(", ");
397	    let odd_mask = (0..dest.lanes).map(|i| format!("i32 {}", i * 2 + 1)).collect::<Vec<_>>().join(", ");
398	    let even = f.fresh();
399	    let odd = f.fresh();
400	    f.line(&format!("{even} = shufflevector {} {value}, {} zeroinitializer, <{} x i32> <{even_mask}>", source.vector, source.vector, dest.lanes));
401	    f.line(&format!("{odd} = shufflevector {} {value}, {} zeroinitializer, <{} x i32> <{odd_mask}>", source.vector, source.vector, dest.lanes));
402	    let wide_even = f.fresh();
403	    let wide_odd = f.fresh();
404	    let extension = if signed { "sext" } else { "zext" };
405	    f.line(&format!("{wide_even} = {extension} {} {even} to {}", source.vector, dest.vector));
406	    f.line(&format!("{wide_odd} = {extension} {} {odd} to {}", source.vector, dest.vector));
407	    let sum = f.fresh();
408	    f.line(&format!("{sum} = add {} {wide_even}, {wide_odd}", dest.vector));
409	    push_lane(f, &sum, dest)
410	}
