412	fn emit_extend(f: &mut FunctionEmitter<'_>, op: u32) -> Result<(), String> {
413	    let (source, dest, high, signed) = match op {
414	        0x87 => (lane_info("i8"), lane_info("i16"), false, true),
415	        0x88 => (lane_info("i8"), lane_info("i16"), true, true),
