293	    fn compile_block(&mut self, sig: &BlockSig, body: &[Instr]) -> Result<(), String> {
294	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("block parameters missing"))?;
295	        let exit = self.fresh_label("block_exit");
296	        self.controls.push(ControlTarget {
297	            kind: TargetKind::Block, height, params: sig.params.clone(), results: sig.results.clone(),
298	            exit: exit.clone(), loop_header: None, has_break: false,
299	        });
300	        self.compile_seq(body)?;
301	        let normal = self.current;
302	        if normal {
303	            self.copy_to_slot_base(height, &sig.results)?;
304	            self.branch(&exit);
305	        }
306	        let target = self.controls.pop().unwrap();
307	        self.stack.truncate(height);
308	        self.stack.extend_from_slice(&sig.results);
309	        if normal || target.has_break {
310	            self.start_label(&exit);
311	        }
312	        self.current = normal || target.has_break;
313	        Ok(())
314	    }
