317	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("loop parameters missing"))?;
318	        let header = self.fresh_label("loop_head");
319	        let exit = self.fresh_label("loop_exit");
320	        self.branch(&header);
321	        self.start_label(&header);
322	        self.controls.push(ControlTarget {
323	            kind: TargetKind::Loop, height, params: sig.params.clone(), results: sig.results.clone(),
324	            exit: exit.clone(), loop_header: Some(header), has_break: false,
325	        });
326	        self.compile_seq(body)?;
327	        let normal = self.current;
328	        if normal {
329	            self.copy_to_slot_base(height, &sig.results)?;
330	            self.branch(&exit);
331	        }
332	        let target = self.controls.pop().unwrap();
333	        self.stack.truncate(height);
334	        self.stack.extend_from_slice(&sig.results);
335	        if normal || target.has_break { self.start_label(&exit); }
336	        self.current = normal || target.has_break;
337	        Ok(())
338	    }
