340	    fn compile_if(&mut self, sig: &BlockSig, then_body: &[Instr], else_body: Option<&[Instr]>) -> Result<(), String> {
341	        let condition = self.pop(ValType::I32)?;
342	        let cond = self.truthy(&condition);
343	        let height = self.stack.len().checked_sub(sig.params.len()).ok_or_else(|| self.error("if parameters missing"))?;
344	        let starting_stack = self.stack.clone();
345	        let then_label = self.fresh_label("if_then");
346	        let else_label = self.fresh_label("if_else");
347	        let exit = self.fresh_label("if_exit");
348	        self.cond_branch(&cond, &then_label, &else_label);
349	        self.controls.push(ControlTarget {
350	            kind: TargetKind::If, height, params: sig.params.clone(), results: sig.results.clone(),
351	            exit: exit.clone(), loop_header: None, has_break: false,
352	        });
353	
354	        self.start_label(&then_label);
355	        self.compile_seq(then_body)?;
356	        let mut normal = self.current;
357	        if normal {
358	            self.copy_to_slot_base(height, &sig.results)?;
359	            self.branch(&exit);
360	        }
361	
362	        self.stack = starting_stack.clone();
363	        self.start_label(&else_label);
364	        if let Some(body) = else_body {
365	            self.compile_seq(body)?;
366	        }
367	        if self.current {
368	            self.copy_to_slot_base(height, &sig.results)?;
369	            self.branch(&exit);
370	            normal = true;
371	        }
372	        let target = self.controls.pop().unwrap();
373	        self.stack.truncate(height);
374	        self.stack.extend_from_slice(&sig.results);
375	        if normal || target.has_break { self.start_label(&exit); }
376	        self.current = normal || target.has_break;
377	        Ok(())
378	    }
