380	    fn target_info(&mut self, depth: usize) -> Result<(String, usize, Vec<ValType>, bool), String> {
381	        let index = self.controls.len().checked_sub(depth + 1).ok_or_else(|| self.error("branch depth out of bounds"))?;
382	        let target = &mut self.controls[index];
383	        let loop_target = target.kind == TargetKind::Loop;
384	        let label = if loop_target { target.loop_header.as_ref().unwrap().clone() } else { target.exit.clone() };
385	        let types = if loop_target { target.params.clone() } else { target.results.clone() };
386	        if !loop_target { target.has_break = true; }
387	        Ok((label, target.height, types, loop_target))
388	    }
