390	    fn copy_to_slot_base(&mut self, height: usize, types: &[ValType]) -> Result<(), String> {
391	        if self.stack.len() < types.len() { return Err(self.error("branch result values are missing")); }
392	        let source = self.stack.len() - types.len();
393	        for (i, &ty) in types.iter().enumerate() {
394	            let value = self.load_slot(source + i, ty);
395	            self.store_slot(height + i, ty, &value);
396	        }
397	        Ok(())
398	    }
