407	    fn branch_if(&mut self, depth: usize) -> Result<(), String> {
408	        let condition = self.pop(ValType::I32)?;
409	        let cond = self.truthy(&condition);
410	        let (target, height, types, _) = self.target_info(depth)?;
411	        let take = self.fresh_label("br_if_take");
412	        let fallthrough = self.fresh_label("br_if_next");
413	        self.cond_branch(&cond, &take, &fallthrough);
414	        self.start_label(&take);
415	        self.copy_to_slot_base(height, &types)?;
416	        self.branch(&target);
417	        self.start_label(&fallthrough);
418	        Ok(())
