421	    fn branch_table(&mut self, targets: &[u32], default: u32) -> Result<(), String> {
422	        let selector = self.pop(ValType::I32)?;
423	        let mut branches = Vec::with_capacity(targets.len() + 1);
424	        for &depth in targets.iter().chain(std::iter::once(&default)) {
425	            let (target, height, types, _) = self.target_info(depth as usize)?;
426	            branches.push((target, height, types, self.fresh_label("br_table_case")));
427	        }
428	        let default_label = branches.last().unwrap().3.clone();
429	        let cases = branches.iter().enumerate().take(targets.len()).map(|(i, b)| format!("i32 {i}, label %{}", b.3)).collect::<Vec<_>>().join(" ");
430	        self.line(&format!("switch i32 {selector}, label %{default_label} [ {cases} ]"));
431	        self.current = false;
432	        for (target, height, types, case_label) in branches {
433	            self.start_label(&case_label);
434	            self.copy_to_slot_base(height, &types)?;
435	            self.branch(&target);
436	        }
437	        Ok(())
438	    }
