440	    fn call_indirect(&mut self, type_index: usize) -> Result<(), String> {
441	        let ty = self.module.types.get(type_index).ok_or_else(|| self.error("call_indirect type index out of range"))?.clone();
442	        let index = self.pop(ValType::I32)?;
443	        let args = self.pop_values(&ty.params)?;
444	        let base = self.stack.len();
445	        let size = self.fresh();
446	        self.line(&format!("{size} = load i32, ptr @w2l_table_size"));
447	        let oob = self.fresh();
448	        self.line(&format!("{oob} = icmp uge i32 {index}, {size}"));
