452	        let index64 = self.fresh();
453	        self.line(&format!("{index64} = zext i32 {index} to i64"));
454	        let slot = self.fresh();
455	        self.line(&format!("{slot} = getelementptr i32, ptr {table}, i64 {index64}"));
