457	        self.line(&format!("{function_index} = load i32, ptr {slot}, align 4"));
458	        let is_null = self.fresh();
459	        self.line(&format!("{is_null} = icmp eq i32 {function_index}, -1"));
460	        self.emit_trap_if(&is_null, 6);
461	
462	        let mut cases = Vec::new();
463	        for (function_index, function) in self.module.functions.iter().enumerate() {
464	            let actual = &self.module.types[function.type_idx as usize];
465	            if actual == &ty { cases.push((function_index, self.fresh_label("indirect_case"))); }
466	        }
467	        let mismatch = self.fresh_label("indirect_mismatch");
468	        let merge = self.fresh_label("indirect_merge");
469	        let case_text = cases.iter().map(|(index, label)| format!("i32 {}, label %{label}", crate::codegen::i32_bits(*index as u32))).collect::<Vec<_>>().join(" ");
470	        self.line(&format!("switch i32 {function_index}, label %{mismatch} [ {case_text} ]"));
471	        self.current = false;
