486	        }
487	        self.start_label(&merge);
488	        for (slot, result_ty) in ty.results.iter().enumerate() {
489	            let value = self.load_slot(base + slot, *result_ty);
490	            self.push(*result_ty, &value)?;
491	        }
492	        Ok(())
