495	    pub(crate) fn call_function(&mut self, index: usize, ty: &FuncType, args: &[String]) -> Result<Vec<String>, String> {
496	        if args.len() != ty.params.len() { return Err(self.error("internal call argument count mismatch")); }
497	        let ret = crate::codegen::return_type(&ty.results);
498	        let target = crate::codegen::fn_name(index);
499	        if ty.results.is_empty() {
500	            self.line(&format!("call void @{target}({})", crate::codegen::typed_args(&ty.params, args)));
501	            return Ok(Vec::new());
502	        }
503	        let call = self.fresh();
504	        self.line(&format!("{call} = call {ret} @{target}({})", crate::codegen::typed_args(&ty.params, args)));
505	        if ty.results.len() == 1 { return Ok(vec![call]); }
506	        let mut values = Vec::with_capacity(ty.results.len());
507	        for (i, ty) in ty.results.iter().enumerate() {
508	            let value = self.fresh();
509	            self.line(&format!("{value} = extractvalue {ret} {call}, {i}"));
510	            let _ = ty;
511	            values.push(value);
512	        }
513	        Ok(values)
514	    }
