516	    fn emit_return_from_stack(&mut self, results: &[ValType]) -> Result<(), String> {
517	        let values = results.iter().enumerate().map(|(i, ty)| self.load_slot(i, *ty)).collect::<Vec<_>>();
518	        self.line("call void @w2l_depth_leave()");
519	        self.emit_return_values(results, &values);
520	        self.current = false;
521	        Ok(())
522	    }
