524	    fn emit_return_values(&mut self, results: &[ValType], values: &[String]) {
525	        match results.len() {
526	            0 => self.line("ret void"),
527	            1 => self.line(&format!("ret {} {}", results[0].llvm(), values[0])),
528	            n => {
529	                let ty = crate::codegen::return_type(results);
530	                let mut current = "zeroinitializer".to_string();
531	                for (i, (result, value)) in results.iter().zip(values).enumerate() {
532	                    let agg = self.fresh();
533	                    self.line(&format!("{agg} = insertvalue {ty} {current}, {} {value}, {i}", result.llvm()));
534	                    current = agg;
535	                }
536	                let _ = n;
537	                self.line(&format!("ret {ty} {current}"));
538	            }
539	        }
540	    }
