75	pub fn emit_bulk(f: &mut FunctionEmitter<'_>, op: &BulkOp) -> Result<(), String> {
76	    match op {
77	        BulkOp::MemoryInit { data, .. } => emit_memory_init(f, *data as usize),
78	        BulkOp::DataDrop { data } => {
79	            f.line(&format!("store i64 0, ptr @w2l_data_len_{data}"));
