81	        }
82	        BulkOp::MemoryCopy { .. } => {
83	            let values = f.pop_values(&[ValType::I32, ValType::I32, ValType::I32])?;
84	            let [dst, src, len] = values.as_slice() else { unreachable!() };
85	            let length = zext_i32(f, len);
86	            // The complete ranges are checked before either side is modified.
87	            check_memory_range(f, src, &length)?;
88	            check_memory_range(f, dst, &length)?;
89	            let source = emit_mem_pointer(f, src, 0, 0);
