217	pub fn parse(bytes: &[u8]) -> Result<Module, String> {
218	    if bytes.len() < 8 || &bytes[..4] != b"\0asm" {
219	        return Err("invalid WebAssembly magic".into());
220	    }
221	    if bytes[4..8] != [1, 0, 0, 0] {
222	        return Err("unsupported WebAssembly version".into());
223	    }
224	
225	    let mut module = Module::default();
226	    let mut reader = Reader::new(&bytes[8..]);
227	    let mut last_rank = 0u8;
228	    let mut seen = [false; 13];
229	    let mut defined_type_indices = Vec::new();
230	
231	    while !reader.eof() {
232	        let id = reader.byte()?;
233	        let size = reader.u32()? as usize;
234	        let mut section = reader.subreader(size)?;
235	        if id == 0 {
236	            let _ = section.name()?;
237	            continue;
238	        }
239	        if id > 12 || id == 0 {
240	            return Err(format!("unknown section id {id}"));
241	        }
242	        let rank = match id {
243	            1..=9 => id,
244	            12 => 10,
245	            10 => 11,
246	            11 => 12,
247	            _ => unreachable!(),
248	        };
249	        if seen[id as usize] {
250	            return Err(format!("duplicate section id {id}"));
251	        }
252	        if rank <= last_rank {
253	            return Err(format!("section {id} is out of order"));
254	        }
255	        seen[id as usize] = true;
256	        last_rank = rank;
257	
258	        match id {
259	            1 => parse_types(&mut section, &mut module)?,
260	            2 => parse_imports(&mut section, &mut module)?,
261	            3 => parse_function_section(&mut section, &mut module, &mut defined_type_indices)?,
262	            4 => parse_tables(&mut section, &mut module)?,
263	            5 => parse_memories(&mut section, &mut module)?,
264	            6 => parse_globals(&mut section, &mut module)?,
265	            7 => parse_exports(&mut section, &mut module)?,
266	            8 => {
267	                let index = section.u32()?;
268	                module.start = Some(index);
269	            }
270	            9 => parse_elements(&mut section, &mut module)?,
271	            10 => parse_code(&mut section, &mut module)?,
272	            11 => parse_data(&mut section, &mut module)?,
273	            12 => module.declared_data_count = Some(section.u32()?),
274	            _ => unreachable!(),
275	        }
276	        section.finish()?;
277	    }
278	
279	    let defined_count = defined_type_indices.len();
280	    if module.functions.len() != module.imported_functions + defined_count {
281	        return Err("function and code section counts do not match".into());
282	    }
283	    if defined_count != 0 && !seen[10] {
284	        return Err("function section is missing code section".into());
285	    }
286	    if seen[10] && module.functions.len() != module.imported_functions + defined_count {
287	        return Err("function and code section counts do not match".into());
288	    }
289	    if let Some(n) = module.declared_data_count {
290	        if n as usize != module.data.len() {
291	            return Err("data count does not match data section".into());
292	        }
293	    }
294	    validate_indices(&module)?;
295	    Ok(module)
296	}
