298	fn parse_types(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
299	    for _ in 0..r.count()? {
300	        if r.byte()? != 0x60 {
301	            return Err("unsupported type form".into());
302	        }
303	        let params = read_types(r)?;
304	        let results = read_types(r)?;
305	        module.types.push(FuncType { params, results });
306	    }
