310	fn parse_imports(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
311	    for _ in 0..r.count()? {
312	        let module_name = r.name()?;
313	        let field_name = r.name()?;
314	        let kind = r.byte()?;
315	        match kind {
316	            0 => {
317	                let type_idx = r.u32()?;
318	                module.functions.push(Function {
319	                    type_idx,
320	                    import: Some((module_name, field_name)),
321	                    locals: Vec::new(),
322	                    body: Vec::new(),
323	                    max_stack: 0,
324	                });
325	                module.imported_functions += 1;
326	            }
327	            1 => return Err("imported tables are outside the supported ABI".into()),
328	            2 => return Err("imported memories are outside the supported ABI".into()),
329	            3 => return Err("imported globals are outside the supported ABI".into()),
330	            _ => return Err(format!("invalid import kind {kind}")),
331	        }
332	    }
333	    Ok(())
334	}
