337	    r: &mut Reader<'_>,
338	    module: &mut Module,
339	    defined_type_indices: &mut Vec<u32>,
340	) -> Result<(), String> {
341	    for _ in 0..r.count()? {
342	        let type_idx = r.u32()?;
343	        defined_type_indices.push(type_idx);
344	        module.functions.push(Function {
345	            type_idx,
346	            import: None,
347	            locals: Vec::new(),
348	            body: Vec::new(),
349	            max_stack: 0,
350	        });
351	    }
