355	fn parse_tables(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
356	    let count = r.count()?;
357	    if count > 1 {
358	        return Err("multiple tables are outside the supported scope".into());
359	    }
360	    for _ in 0..count {
361	        if r.byte()? != 0x70 {
362	            return Err("only funcref tables are supported".into());
363	        }
364	        let limits = read_limits(r, false)?;
365	        module.tables.push(Table { limits });
