370	fn parse_memories(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
371	    let count = r.count()?;
372	    if count > 1 {
373	        return Err("multiple memories are outside the supported scope".into());
374	    }
375	    for _ in 0..count {
376	        let limits = read_limits(r, true)?;
377	        if limits.min > 65536 || limits.max.is_some_and(|m| m > 65536) {
378	            return Err("memory limits exceed the wasm32 page limit".into());
379	        }
