385	fn read_limits(r: &mut Reader<'_>, memory: bool) -> Result<Limits, String> {
386	    let flags = r.u32()?;
387	    if flags & !1 != 0 {
388	        return Err(if memory {
389	            "shared and memory64 memories are outside the supported scope".into()
390	        } else {
391	            "unsupported table limits flags".into()
392	        });
393	    }
394	    let min = r.u32()?;
395	    let max = if flags & 1 != 0 { Some(r.u32()?) } else { None };
396	    if max.is_some_and(|m| m < min) {
397	        return Err("limits maximum is smaller than minimum".into());
398	    }
399	    Ok(Limits { min, max })
400	}
