402	fn parse_globals(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
403	    for _ in 0..r.count()? {
404	        let ty = read_valtype(r.byte()?)?;
405	        let mutable = match r.byte()? {
406	            0 => false,
407	            1 => true,
408	            other => return Err(format!("invalid global mutability {other}")),
409	        };
