419	fn parse_exports(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
420	    for _ in 0..r.count()? {
421	        let name = r.name()?;
422	        let kind = match r.byte()? {
423	            0 => ExportKind::Function(r.u32()?),
424	            1 => ExportKind::Table(r.u32()?),
425	            2 => ExportKind::Memory(r.u32()?),
426	            3 => ExportKind::Global(r.u32()?),
