437	fn parse_elements(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
438	    for _ in 0..r.count()? {
439	        let flags = r.u32()?;
440	        let (mode, has_elemkind) = match flags {
441	            0 => (SegmentMode::Active { index: 0, offset: read_const_expr(r)? }, false),
442	            1 => (SegmentMode::Passive, true),
443	            2 => {
444	                let table = r.u32()?;
445	                let offset = read_const_expr(r)?;
446	                (SegmentMode::Active { index: table, offset }, true)
447	            }
448	            3 => (SegmentMode::Declared, true),
449	            4..=7 => return Err("reference-type element expressions are outside the supported scope".into()),
450	            _ => return Err(format!("invalid element segment flags {flags}")),
451	        };
452	        if has_elemkind && r.byte()? != 0 {
453	            return Err("only funcref element segments are supported".into());
454	        }
455	        let mut functions = Vec::new();
456	        for _ in 0..r.count()? {
457	            functions.push(r.u32()?);
458	        }
459	        module.elements.push(ElementSegment { mode, functions });
460	    }
461	    Ok(())
462	}
