464	fn parse_data(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
465	    for _ in 0..r.count()? {
466	        let flags = r.u32()?;
467	        let mode = match flags {
468	            0 => SegmentMode::Active { index: 0, offset: read_const_expr(r)? },
469	            1 => SegmentMode::Passive,
470	            2 => {
471	                let memory = r.u32()?;
472	                let offset = read_const_expr(r)?;
473	                SegmentMode::Active { index: memory, offset }
474	            }
475	            _ => return Err(format!("invalid data segment flags {flags}")),
476	        };
477	        let len = r.count()?;
478	        let bytes = r.bytes(len)?.to_vec();
479	        module.data.push(DataSegment { mode, bytes });
480	    }
481	    Ok(())
482	}
