484	fn parse_code(r: &mut Reader<'_>, module: &mut Module) -> Result<(), String> {
485	    let count = r.count()?;
486	    let defined_count = module.functions.len().saturating_sub(module.imported_functions);
487	    if count != defined_count {
488	        return Err("function and code section counts do not match".into());
489	    }
490	    for body_index in 0..count {
491	        let size = r.count()?;
492	        let mut body = r.subreader(size)?;
493	        let mut locals = Vec::new();
494	        for _ in 0..body.count()? {
495	            let n = body.count()?;
496	            let ty = read_valtype(body.byte()?)?;
497	            if locals.len().saturating_add(n) > 10_000_000 {
498	                return Err("too many locals".into());
499	            }
500	            locals.resize(locals.len() + n, ty);
501	        }
502	        let types = &module.types;
503	        let (instructions, end) = parse_instr_seq(&mut body, types, false)?;
504	        if end != SeqEnd::End {
505	            return Err("unexpected else at function end".into());
506	        }
507	        body.finish()?;
508	        let function = &mut module.functions[module.imported_functions + body_index];
509	        function.locals = locals;
510	        function.body = instructions;
511	    }
512	    Ok(())
513	}
