516	enum SeqEnd {
517	    End,
518	    Else,
519	}
520	
521	fn parse_instr_seq(
522	    r: &mut Reader<'_>,
523	    types: &[FuncType],
524	    allow_else: bool,
525	) -> Result<(Vec<Instr>, SeqEnd), String> {
526	    let mut out = Vec::new();
527	    loop {
528	        let op = r.byte()?;
529	        match op {
530	            0x0b => return Ok((out, SeqEnd::End)),
531	            0x05 if allow_else => return Ok((out, SeqEnd::Else)),
532	            0x05 => return Err("unexpected else instruction".into()),
533	            0x00 => out.push(Instr::Unreachable),
534	            0x01 => out.push(Instr::Nop),
535	            0x02..=0x04 => {
536	                let sig = resolve_blocktype(read_blocktype(r)?, types)?;
537	                if op == 0x04 {
538	                    let (then_body, ending) = parse_instr_seq(r, types, true)?;
539	                    let else_body = if ending == SeqEnd::Else {
540	                        let (body, end) = parse_instr_seq(r, types, false)?;
541	                        if end != SeqEnd::End {
542	                            return Err("unexpected else at if end".into());
543	                        }
544	                        Some(body)
545	                    } else {
546	                        None
547	                    };
548	                    out.push(Instr::If(sig, then_body, else_body));
549	                } else {
550	                    let (body, ending) = parse_instr_seq(r, types, false)?;
551	                    if ending != SeqEnd::End {
552	                        return Err("unexpected else in block".into());
553	                    }
554	                    if op == 0x02 {
555	                        out.push(Instr::Block(sig, body));
556	                    } else {
557	                        out.push(Instr::Loop(sig, body));
558	                    }
559	                }
560	            }
561	            0x0c => out.push(Instr::Br(r.u32()?)),
562	            0x0d => out.push(Instr::BrIf(r.u32()?)),
563	            0x0e => {
564	                let n = r.count()?;
565	                let mut targets = Vec::with_capacity(n);
566	                for _ in 0..n {
567	                    targets.push(r.u32()?);
568	                }
569	                out.push(Instr::BrTable(targets, r.u32()?));
570	            }
571	            0x0f => out.push(Instr::Return),
572	            0x10 => out.push(Instr::Call(r.u32()?)),
573	            0x11 => out.push(Instr::CallIndirect { ty: r.u32()?, table: r.u32()? }),
574	            0x1a => out.push(Instr::Drop),
575	            0x1b => out.push(Instr::Select(None)),
576	            0x1c => return Err("typed select is outside the supported scope".into()),
577	            0x20 => out.push(Instr::LocalGet(r.u32()?)),
578	            0x21 => out.push(Instr::LocalSet(r.u32()?)),
579	            0x22 => out.push(Instr::LocalTee(r.u32()?)),
580	            0x23 => out.push(Instr::GlobalGet(r.u32()?)),
581	            0x24 => out.push(Instr::GlobalSet(r.u32()?)),
582	            0x28..=0x35 => {
583	                let align = r.u32()?;
584	                let offset = r.u32()?;
585	                out.push(Instr::Load { op, align, offset });
586	            }
587	            0x36..=0x3e => {
588	                let align = r.u32()?;
589	                let offset = r.u32()?;
590	                out.push(Instr::Store { op, align, offset });
591	            }
592	            0x3f => out.push(Instr::MemorySize(r.u32()?)),
593	            0x40 => out.push(Instr::MemoryGrow(r.u32()?)),
594	            0x41 => out.push(Instr::Const(ConstExpr::I32(r.i32()?))),
595	            0x42 => out.push(Instr::Const(ConstExpr::I64(r.i64()?))),
596	            0x43 => out.push(Instr::Const(ConstExpr::F32(u32::from_le_bytes(r.bytes(4)?.try_into().unwrap())))),
597	            0x44 => out.push(Instr::Const(ConstExpr::F64(u64::from_le_bytes(r.bytes(8)?.try_into().unwrap())))),
598	            0x45..=0xbf => out.push(Instr::Numeric(op)),
599	            0xc0..=0xc4 => out.push(Instr::SignExtend(op)),
600	            0xfc => {
601	                let misc = r.u32()?;
602	                let instruction = match misc {
603	                    0..=7 => Instr::Saturating(misc),
604	                    8 => {
605	                        let data = r.u32()?;
606	                        let memory = r.u32()?;
607	                        Instr::Bulk(BulkOp::MemoryInit { data, memory })
608	                    }
609	                    9 => {
610	                        let data = r.u32()?;
611	                        Instr::Bulk(BulkOp::DataDrop { data })
612	                    }
613	                    10 => Instr::Bulk(BulkOp::MemoryCopy { dst: r.u32()?, src: r.u32()? }),
614	                    11 => Instr::Bulk(BulkOp::MemoryFill { memory: r.u32()? }),
615	                    12 => Instr::Bulk(BulkOp::TableInit { element: r.u32()?, table: r.u32()? }),
616	                    13 => Instr::Bulk(BulkOp::ElementDrop { element: r.u32()? }),
617	                    14 => Instr::Bulk(BulkOp::TableCopy { dst: r.u32()?, src: r.u32()? }),
618	                    15 => Instr::Bulk(BulkOp::TableGrow { table: r.u32()? }),
619	                    16 => Instr::Bulk(BulkOp::TableSize { table: r.u32()? }),
620	                    17 => Instr::Bulk(BulkOp::TableFill { table: r.u32()? }),
621	                    _ => return Err(format!("unsupported 0xfc opcode {misc}")),
622	                };
623	                out.push(instruction);
624	            }
625	            0xfd => {
626	                let sub = r.u32()?;
627	                let immediate = parse_simd_immediate(r, sub)?;
628	                out.push(Instr::Simd { op: sub, immediate });
629	            }
630	            _ => return Err(format!("unsupported opcode 0x{op:02x}")),
631	        }
632	    }
633	}
