635	fn parse_simd_immediate(r: &mut Reader<'_>, op: u32) -> Result<SimdImmediate, String> {
636	    match op {
637	        0x00..=0x0b | 0x54..=0x5d => {
638	            let align = r.u32()?;
639	            let offset = r.u32()?;
640	            if (0x54..=0x5b).contains(&op) {
641	                Ok(SimdImmediate::MemLane { align, offset, lane: r.byte()? })
642	            } else {
643	                Ok(SimdImmediate::MemArg { align, offset })
644	            }
645	        }
646	        0x0c => Ok(SimdImmediate::Bytes(r.bytes(16)?.try_into().unwrap())),
647	        0x0d => Ok(SimdImmediate::Bytes(r.bytes(16)?.try_into().unwrap())),
648	        0x15..=0x22 => Ok(SimdImmediate::Lane(r.byte()?)),
649	        _ if is_known_simd_opcode(op) => Ok(SimdImmediate::None),
650	        _ => Err(format!("unsupported SIMD opcode 0x{op:x}")),
651	    }
652	}
