#include <dlfcn.h>
#include <setjmp.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*export_fn)(void *, void *);
typedef void (*init_fn)(void);

static jmp_buf trap_context;
static volatile int trap_code;

__attribute__((noreturn)) void w2l_trap(int code) {
    trap_code = code;
    longjmp(trap_context, 1);
    __builtin_unreachable();
}

static export_fn get_export(void *module, const char *hex_name) {
    char symbol[128];
    snprintf(symbol, sizeof(symbol), "w2l_export_%s", hex_name);
    void *address = dlsym(module, symbol);
    if (!address) {
        fprintf(stderr, "missing export %s: %s\n", symbol, dlerror());
        exit(1);
    }
    return (export_fn)address;
}

static void expect_trap(void *module, const char *name, int expected, int32_t argument, int has_argument) {
    export_fn function = get_export(module, name);
    uint8_t args[16] = {0};
    uint8_t results[16] = {0};
    if (has_argument) memcpy(args, &argument, sizeof(argument));
    trap_code = -1;
    if (setjmp(trap_context) == 0) {
        function(args, results);
        fprintf(stderr, "%s did not trap\n", name);
        exit(1);
    }
    if (trap_code != expected) {
        fprintf(stderr, "%s trapped with %d, expected %d\n", name, trap_code, expected);
        exit(1);
    }
    printf("%s -> trap %d\n", name, trap_code);
}

static int32_t call_i32(void *module, const char *name, int32_t argument, int has_argument) {
    export_fn function = get_export(module, name);
    uint8_t args[16] = {0};
    uint8_t results[16] = {0};
    if (has_argument) memcpy(args, &argument, sizeof(argument));
    trap_code = -1;
    if (setjmp(trap_context) != 0) {
        fprintf(stderr, "%s unexpectedly trapped with %d\n", name, trap_code);
        exit(1);
    }
    function(args, results);
    int32_t value;
    memcpy(&value, results, sizeof(value));
    return value;
}

static void check_trap(void *module, const char *name, int code) {
    expect_trap(module, name, code, 0, 0);
    if (call_i32(module, "616e73776572", 0, 0) != 42) {
        fprintf(stderr, "depth bookkeeping was not reset after %s\n", name);
        exit(1);
    }
}

int main(int argc, char **argv) {
    if (argc != 2) return 2;
    void *module = dlopen(argv[1], RTLD_NOW | RTLD_GLOBAL);
    if (!module) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        return 1;
    }
    init_fn init = (init_fn)dlsym(module, "w2l_init");
    if (!init) {
        fprintf(stderr, "missing w2l_init\n");
        return 1;
    }
    trap_code = -1;
    if (setjmp(trap_context) != 0) {
        fprintf(stderr, "w2l_init trapped with %d\n", trap_code);
        return 1;
    }
    init();

    check_trap(module, "756e726561636861626c65", 0);
    check_trap(module, "6469767a65726f", 1);
    check_trap(module, "6469766f766572666c6f77", 2);
    check_trap(module, "6e616e7472756e63", 3);
    check_trap(module, "72616e6765", 2);
    check_trap(module, "6d656d5f6f6f62", 4);
    expect_trap(module, "696e645f6f6f62", 5, 1, 1);
    expect_trap(module, "696e645f6e756c6c", 6, 1, 1);
    expect_trap(module, "696e645f74797065", 7, 1, 1);
    if (call_i32(module, "696e645f676f6f64", 1234, 1) != 1234) {
        fprintf(stderr, "valid call_indirect returned an incorrect result\n");
        return 1;
    }
    if (call_i32(module, "72656375727365", 10000, 1) != 0) {
        fprintf(stderr, "10,000-frame recursion returned an incorrect result\n");
        return 1;
    }
    expect_trap(module, "72656375727365", 8, 20000, 1);
    if (call_i32(module, "616e73776572", 0, 0) != 42) {
        fprintf(stderr, "depth bookkeeping was not reset after stack exhaustion\n");
        return 1;
    }
    puts("passed trap codes, indirect calls, and recursion checks");
    dlclose(module);
    return 0;
}

