    if (argc != 2) return 2;
    void *module = dlopen(argv[1], RTLD_NOW | RTLD_GLOBAL);
    if (!module) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        return 1;
    }
    init_fn init = (init_fn)dlsym(module, "w2l_init");
    if (!init) {
        fprintf(stderr, "missing w2l_init\n");
        return 1;
    }
    trap_code = -1;
    if (setjmp(trap_context) != 0) {
        fprintf(stderr, "w2l_init trapped with %d\n", trap_code);
        return 1;
    }
    init();

    check_trap(module, "756e726561636861626c65", 0);
    check_trap(module, "6469767a65726f", 1);
    check_trap(module, "6469766f766572666c6f77", 2);
    check_trap(module, "6e616e7472756e63", 3);
    check_trap(module, "72616e6765", 2);
    check_trap(module, "6d656d5f6f6f62", 4);
    expect_trap(module, "696e645f6f6f62", 5, 1, 1);
    expect_trap(module, "696e645f6e756c6c", 6, 1, 1);
    expect_trap(module, "696e645f74797065", 7, 1, 1);
    if (call_i32(module, "696e645f676f6f64", 1234, 1) != 1234) {
        fprintf(stderr, "valid call_indirect returned an incorrect result\n");
        return 1;
    }
    if (call_i32(module, "72656375727365", 10000, 1) != 0) {
        fprintf(stderr, "10,000-frame recursion returned an incorrect result\n");
        return 1;
    }
    expect_trap(module, "72656375727365", 8, 20000, 1);
    if (call_i32(module, "616e73776572", 0, 0) != 42) {
        fprintf(stderr, "depth bookkeeping was not reset after stack exhaustion\n");
        return 1;
    }
    puts("passed trap codes, indirect calls, and recursion checks");
    dlclose(module);
    return 0;
}

