        "i64" => LaneInfo { lanes: 2, scalar: "i64", vector: "<2 x i64>", bits: 64, float: false },
        "f32" => LaneInfo { lanes: 4, scalar: "float", vector: "<4 x float>", bits: 32, float: true },
