#include <dlfcn.h>
#include <setjmp.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef void (*export_fn)(void *, void *);
typedef void (*init_fn)(void);

static jmp_buf trap_context;
static volatile int trap_code;

__attribute__((noreturn)) void w2l_trap(int code) {
    trap_code = code;
    longjmp(trap_context, 1);
    __builtin_unreachable();
}

static export_fn get_export(void *module, const char *hex_name) {
    char symbol[128];
    snprintf(symbol, sizeof(symbol), "w2l_export_%s", hex_name);
    void *address = dlsym(module, symbol);
    if (!address) {
        fprintf(stderr, "missing export %s: %s\n", symbol, dlerror());
        exit(1);
    }
    return (export_fn)address;
}

static void expect_trap(void *module, const char *name, int expected, int32_t argument, int has_argument) {
    export_fn function = get_export(module, name);
    uint8_t args[16] = {0};
    uint8_t results[16] = {0};
    if (has_argument) memcpy(args, &argument, sizeof(argument));
    trap_code = -1;
    if (setjmp(trap_context) == 0) {
        function(args, results);
