import ctypes
import os
import struct
import subprocess
import sys

trap_path, module_path, wasm_path = sys.argv[1:]
ctypes.CDLL(trap_path, mode=ctypes.RTLD_GLOBAL)
module = ctypes.CDLL(module_path)
module.w2l_init()

reference = subprocess.Popen(
    ["w2l-ref"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True, bufsize=1
)

def ref(command):
    reference.stdin.write(command + "\n")
    reference.stdin.flush()
    reply = reference.stdout.readline().rstrip("\n")
    if reply.startswith("error ") or reply.startswith("trap "):
        raise SystemExit(f"{command}: {reply}")
    return reply

def slot(value):
    return (struct.pack("<i", value) + bytes(12)).hex()

def invoke_generated(name, args, result_count):
    input_slots = ctypes.create_string_buffer(max(1, 16 * len(args)))
    output_slots = ctypes.create_string_buffer(max(1, 16 * result_count))
    for index, value in enumerate(args):
        struct.pack_into("<i", input_slots, 16 * index, value)
    function = getattr(module, "w2l_export_" + name.encode().hex())
    function.argtypes = (ctypes.c_void_p, ctypes.c_void_p)
    function.restype = None
    function(ctypes.addressof(input_slots), ctypes.addressof(output_slots))
    return [struct.unpack_from("<i", output_slots.raw, 16 * index)[0] for index in range(result_count)]

def invoke_reference(name, args, result_count):
    fields = ["invoke", "a", name.encode().hex(), str(result_count)]
    fields.extend(slot(value) for value in args)
    reply = ref(" ".join(fields))
    if reply == "ok":
        return []
    if not reply.startswith("ok "):
        raise SystemExit(f"unexpected invoke reply: {reply}")
    return [struct.unpack("<i", bytes.fromhex(item[:8]))[0] for item in reply[3:].split()]

def check(name, args=(), result_count=0):
    generated = invoke_generated(name, args, result_count)
    expected = invoke_reference(name, args, result_count)
    if generated != expected:
        raise SystemExit(f"{name}{tuple(args)}: generated {generated}, reference {expected}")

if ref(f"load a {os.path.abspath(wasm_path)}") != "ok" or ref("init a") != "ok":
    raise SystemExit("reference setup failed")
check("init", [0, 0, 3])
for index, expected in enumerate((15, 25, 35)):
    check("call", [index, 5], 1)
    if invoke_generated("call", [index, 5], 1) != [expected]:
        raise SystemExit(f"initial table entry {index} returned the wrong value")
check("copy", [4, 0, 2])
for index, expected in ((4, 15), (5, 25)):
    if invoke_generated("call", [index, 5], 1) != [expected]:
        raise SystemExit(f"copied table entry {index} returned the wrong value")
check("copy", [1, 0, 3])
for index, expected in ((1, 15), (2, 25), (3, 35)):
    if invoke_generated("call", [index, 5], 1) != [expected]:
        raise SystemExit(f"overlapping table copy produced the wrong entry {index}")
check("drop")
check("init", [6, 0, 0])
print("passed passive table.init/drop, table.copy, overlap, and indirect-call checks")
reference.stdin.write("quit\n")
reference.stdin.close()
reference.wait(timeout=10)

